window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0145", [{"word":"engraving technique","ipa_uk":"/ɪnˈɡreɪvɪŋ tekˈniːk/","ipa_us":"/ɪnˈɡreɪvɪŋ tekˈniːk/","definition_zh":"刻版技法；在金属、木板或石面上刻出线条以制版印刷的工艺，也指现代机械与激光雕刻方法","definition_en":"the craft of cutting lines into a hard surface so that the cut design can be inked and printed, or a particular method used for this","core_image":"一把刻刀在铜板上推出一道细沟，墨被压进沟里，压上湿纸后纸上浮出一条黑线","scene":"老作坊的木桌上摊着铜板、刻刀和刚压出的试印纸。The curator explains each engraving technique in turn before letting us touch the plate.","sceneCN":"这里 engraving technique 指「在硬质版面上刻线制版的具体工艺」（第 1 个义项：刻版技法的总称）；句意为策展人依次讲解每一种刻版技法，讲完才让我们触摸铜版。图中可辨识物件：铜版、刻刀、试印纸、木桌。","pos":[{"tag":"n.","zh":"刻版技法；版画工艺（可数名词短语）"},{"tag":"n.","zh":"雕刻工艺（现代工业与激光加工）"}],"collocations":[{"phrase":"master an engraving technique","zh":"掌握一种刻版技法"},{"phrase":"hand engraving technique","zh":"手工雕刻技法"},{"phrase":"copperplate engraving technique","zh":"铜版雕刻技法"},{"phrase":"laser engraving technique","zh":"激光雕刻工艺"},{"phrase":"traditional engraving technique","zh":"传统刻版技法"},{"phrase":"engraving technique for metal","zh":"金属雕刻技法"}],"forms":[{"label":"单数形式","form":"engraving technique"},{"label":"复数形式","form":"engraving techniques"},{"label":"所有格","form":"engraving technique's"},{"label":"相关动词","form":"engrave"},{"label":"相关人物名词","form":"engraver"}],"derivatives":[{"word":"engrave","pos":"v.","zh":"雕刻；在版面上刻线"},{"word":"engraver","pos":"n.","zh":"刻版师；雕刻工"},{"word":"engraving","pos":"n.","zh":"版画；刻版；刻痕"},{"word":"technique","pos":"n.","zh":"技术；技法"},{"word":"technical","pos":"adj.","zh":"技术的；工艺的"},{"word":"technician","pos":"n.","zh":"技术员；技师"}],"senses":[{"no":"01","title":"The craft of cutting a printable line","titleCN":"刻出可印线条的工艺","definition":"the skill of cutting a design into a hard surface so that the cut lines hold ink and can be printed","definitionCN":"把图案刻进硬质表面，使刻出的线条能留住墨并可压印成画的技艺","example":"The apprentices spent a year learning the engraving technique before touching copper.","exampleCN":"学徒先花一年学习刻版技法，之后才被允许碰铜版。","why":"engraving names the cutting of a groove and technique names the skill behind work, so together they name the skill of cutting lines that can print.","whyCN":"engraving 指刻出沟槽，technique 指做事所需的技艺，合起来就是「刻出能印的线条」这门手艺。"},{"no":"02","title":"Intaglio cutting on metal","titleCN":"金属凹版雕刻","definition":"a method in which a burin pushes a V-shaped groove into a copper or steel plate, and ink is kept in the groove after the surface is wiped","definitionCN":"用刻刀在铜版或钢版上推出楔形沟槽，擦净版面后墨只留在沟里的方法","example":"Intaglio is the slowest engraving technique, because a single palm-sized face may take weeks.","exampleCN":"凹版是最慢的刻版技法，一个巴掌大的面孔可能要刻上几周。","why":"the plate is the classic surface: the burin lifts a curl of metal and leaves a channel that holds ink below the wiped surface.","whyCN":"金属版是最经典的版面：刻刀翻起一条金属屑，留下低于版面的沟槽，擦版后墨就藏在沟里。"},{"no":"03","title":"Wood engraving","titleCN":"木口木刻","definition":"a relief method cut into the end grain of a dense hardwood block, so the uncut surface stands up and takes the ink","definitionCN":"在硬木横断面（木口）上刻线的凸版方法，未刻去的表面凸起并沾墨","example":"Her engraving technique is wood engraving, so the white lines are the ones she cuts away.","exampleCN":"她的技法是木口木刻，因此白线才是她刻掉的部分。","why":"the same word covers relief work because the tool still cuts lines, but here what remains standing prints instead of what sinks.","whyCN":"同一个词也覆盖凸版，因为工具仍在刻线，只是这次印出的是留下的凸面而非凹下的沟。"},{"no":"04","title":"Etching by acid","titleCN":"酸蚀刻技法","definition":"a method in which a needle scratches through a waxy ground and acid bites the exposed lines into the plate","definitionCN":"用针尖划透蜡层，再由酸腐蚀裸露线条，使其陷入版面的方法","example":"Etching looks like drawing, yet its engraving technique is chemical rather than mechanical.","exampleCN":"蚀刻看起来像画画，但它的刻版技法靠化学而非机械。","why":"etching joins the family because the line is still a sunken channel, though acid rather than steel does the cutting.","whyCN":"蚀刻归入这一族，因为线条仍是凹下的沟槽，只不过动手的是酸而不是钢刀。"},{"no":"05","title":"The look of line and hatching","titleCN":"线条与排线的视觉效果","definition":"the visual texture produced by parallel lines, cross-hatching and stippled dots","definitionCN":"由平行线、交叉排线和点刻形成的视觉质感","example":"Critics praised the engraving technique, meaning the crisp hatching rather than the subject.","exampleCN":"评论家称赞的是其刻版技法，指的是利落的排线，而非题材。","why":"a technique is judged by the marks it leaves, so the phrase also names the surface quality of the finished print.","whyCN":"技法靠留下的痕迹来评判，因此这个短语也指成品版画的表面质感。"},{"no":"06","title":"The whole plate-to-print sequence","titleCN":"从刻版到压印的完整流程","definition":"the full order of preparing, cutting, inking and pressing a plate","definitionCN":"备版、刻版、上墨、压印的完整步骤顺序","example":"A good engraving technique includes wiping the plate clean without pulling ink from the lines.","exampleCN":"好的刻版技法还包括把版面擦净而不把沟里的墨带走。","why":"a technique is not only a stroke but the order of steps that makes the stroke printable.","whyCN":"技法不只是一刀，还包括使这一刀最终能印出来的整套步骤顺序。"},{"no":"07","title":"Machine and laser engraving","titleCN":"机械与激光雕刻","definition":"cutting a design with a rotating tool or a focused laser beam instead of by hand","definitionCN":"用旋转刀具或聚焦激光束代替手工刻出图案","example":"Modern signage often uses a laser engraving technique to mark metal plaques.","exampleCN":"现代标牌常用激光雕刻工艺在金属牌上打标。","why":"industry kept the word for any cut mark, so the phrase now covers computer-driven engraving as well as handwork.","whyCN":"工业沿用了这个说法来指任何刻痕，因此该短语如今既指手工也指数控雕刻。"},{"no":"08","title":"A category in art history","titleCN":"艺术史与考古中的技法分类","definition":"a label scholars use to classify prints, seals and ornaments by how their lines were cut","definitionCN":"学者按刻线方式为版画、印章与饰件分类时使用的标签","example":"The catalogue lists the engraving technique of every seal in the collection.","exampleCN":"图录列出馆藏每一枚印章的刻制技法。","why":"once objects are catalogued, the phrase stops naming a workshop habit and becomes a classification term.","whyCN":"一旦物件被编目，这个短语就不再指某间作坊的习惯，而成为分类术语。"}],"etymology":{"intro":{"en":"Engraving joins an Old English verb for carving to a Greek noun for skill, and the modern phrase was fixed when print studios needed a name for each cutting method. Dates are approximate.","cn":"engraving 把古英语中表示「刻」的动词与希腊语中表示「技艺」的名词组合起来，现代短语在版画工坊需要为每种刻法命名时定型。年代均为约数。"},"items":[{"era":"OLD ENGLISH GRAFAN","en":"Grafan meant 'to dig, carve, scratch', and its past participle graven survived in English beside the newer verb grave.","cn":"grafan 意为「挖、刻、划」，其过去分词 graven 与较新的动词形式一同留在英语中。"},{"era":"MIDDLE ENGLISH ENGRAVEN","en":"A French-style prefix meaning 'in' was added to graven, giving engraven and later engrave: to cut a design into a surface.","cn":"一个表示「向内」的法语式前缀加在 graven 上，形成 engraven，后作 engrave，意为把图案刻进表面。"},{"era":"GREEK TECHNE","en":"Greek technē named an art, craft or systematic skill, and it passed through Latin and French into English as technique.","cn":"希腊语 technē 指技艺、手艺或有章法的技能，经拉丁语与法语进入英语，成为 technique。"},{"era":"PRINT STUDIO","en":"From the seventeenth century English workshops spoke of the engraving technique of a plate, meaning the particular method of cutting it.","cn":"从十七世纪起，英语工坊开始说某块版的 engraving technique，指刻制它的具体方法。"},{"era":"INDUSTRIAL ENGRAVING","en":"In the nineteenth and twentieth centuries the phrase moved into industry, covering mechanical pantographs and later laser cutters.","cn":"在十九与二十世纪，这个短语进入工业，先后覆盖机械缩放雕刻机与后来的激光雕刻机。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-English ancestry of grafan is not settled in detail, and the further root of Greek technē is disputed, so any reconstructed form for either is only a hypothesis.","cn":"来源不确定（更深来源）：grafan 在英语之前的谱系细节尚无定论，希腊语 technē 的更早词根亦有争议，凡为其给出的重构形式都只是假说。"}]},"similar":{"note":{"en":"Group one holds neighbouring print methods that share the vocabulary of cutting but not the same root; group two holds general words for cutting and for the printed result.","cn":"第一组是共用「刻」这套说法、但词根不同的邻近版画方法；第二组是泛指切割与印成品的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"etching","ipa":"/ˈetʃɪŋ/","tag":"acid-cut cousin","definition":"A print method using acid rather than a burin; it shares the workshop but comes from a Dutch word for 'corrode'.","definitionCN":"用酸而非刻刀制版的方法，与刻版同属工坊，但词源来自荷兰语「腐蚀」一词。"},{"word":"woodcut","ipa":"/ˈwʊdkʌt/","tag":"relief cousin","definition":"A relief print cut along the plank grain; the word is a plain English compound, not a relative of engrave.","definitionCN":"沿木板顺纹刻制的凸版印刷，词为英语本族复合词，与 engrave 无词源关系。"},{"word":"lithography","ipa":"/lɪˈθɒɡrəfi/","tag":"stone-writing","definition":"Printing from a flat stone or metal surface by grease and water, from Greek lithos 'stone' and graphein 'write'.","definitionCN":"借油水相斥在平版石面或金属面印刷，来自希腊语 lithos「石」与 graphein「写」。"},{"word":"intaglio","ipa":"/ɪnˈtɑːliəʊ/","tag":"sunken-line family","definition":"The Italian term for any method whose lines are cut below the surface, including engraving and etching.","definitionCN":"意大利语术语，指所有线条低于版面的方法，包括雕刻与蚀刻。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carving","ipa":"/ˈkɑːvɪŋ/","tag":"cutting for shape","definition":"Cutting wood, stone or ivory into a form; it stresses the shaped object rather than the printed line.","definitionCN":"把木、石或象牙刻成形状，强调被刻成的物件，而非印出的线条。"},{"word":"engraving","ipa":"/ɪnˈɡreɪvɪŋ/","tag":"the print itself","definition":"The noun alone usually means the finished print or the cut plate, while the full phrase names the method.","definitionCN":"单用该名词通常指成品版画或刻好的版，而完整短语才指方法。"},{"word":"printmaking","ipa":"/ˈprɪntmeɪkɪŋ/","tag":"the whole field","definition":"The general craft of making prints by any method; the phrase is one branch inside that field.","definitionCN":"泛指以任何方法制作版画的技艺，本短语只是其中的一个分支。"},{"word":"incision","ipa":"/ɪnˈsɪʒn/","tag":"the cut itself","definition":"A single cut into a surface, from Latin caedere 'to cut'; it names the mark, not the craft.","definitionCN":"在表面上的一道切口，来自拉丁语 caedere「切」，指痕迹而非技艺。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real workshop terms and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实的工坊术语与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Engrave carries a prefix meaning 'in' plus a verb meaning 'carve': to carve into a surface.","cn":"engrave 由一个表示「向内」的前缀加表示「刻」的动词构成：把图案刻进表面。"},{"en":"Technique comes from Greek technē 'art, skill', the same root as technical and technician.","cn":"technique 来自希腊语 technē「技艺」，与 technical、technician 同根。"},{"en":"The fixed phrases sort the field: copperplate engraving technique, wood engraving, laser engraving technique.","cn":"固定搭配把这个领域分开：铜版雕刻技法、木口木刻、激光雕刻工艺。"},{"en":"A burin makes a V-shaped groove; the groove holds ink; the paper takes the line.","cn":"刻刀推出楔形沟；沟里存墨；纸把线带走。"},{"en":"Relief and intaglio are opposites: in relief the raised surface prints, in intaglio the sunken line prints.","cn":"凸版与凹版正好相反：凸版印凸起处，凹版印凹下的线。"}],"abstract":[{"en":"Picture a farmer cutting a furrow, then filling it with dark seed so the field shows a line.","cn":"想象农人开出一道沟，再往沟里填黑种子，田里于是显出一条线。"},{"en":"Picture a signature pressed into wax: the shape is below the surface, yet it is the shape that reads.","cn":"想象印章压进火漆：形状低于表面，可读出来的正是这个形状。"},{"en":"Picture a language that can only be written with a knife, so every sentence is a small act of carving.","cn":"想象一种只能用刀来写的语言，每句话都是一次小小的雕刻。"}]},"examples":[{"en":"The museum label names the engraving technique used on each plate.","cn":"博物馆标签写明每块版所用的刻版技法。"},{"en":"She taught herself the engraving technique by copying old banknote plates.","cn":"她靠临摹旧钞票版自学了刻版技法。"},{"en":"Laser engraving technique now marks parts that hand tools once cut.","cn":"如今激光雕刻工艺在手工刀具曾刻过的零件上打标。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"engrave（刻进去）+ technique（技艺）→ 把线条刻进版面的手艺 → 刻版技法","word":"engraving technique"},"root":"engrave 由表示「向内」的前缀加古英语 grafan「刻、挖」构成；technique 来自希腊语 technē「技艺」，经拉丁语与法语入英语。英语 engraving technique。","sensesIntro":{"en":"Eight senses follow one gesture: a line is cut below a hard surface, and that gesture is then read as a metal method, a wood method, an acid method, a visual texture, a full process, an industrial operation and finally a catalogue label.","cn":"八个义项沿同一个动作展开：在硬质表面下刻出一道线；这个动作再依次被读作金属法、木刻法、酸蚀法、视觉质感、完整流程、工业工序，最后成为一种编目标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a blade opens a thin channel in a plate, ink settles in the channel, and paper lifts the line out.","cn":"核心意象：刀刃在版面上开出一道细沟，墨沉进沟里，纸再把线提出来。"},"chain":["CUT A LINE","SINK THE LINE","HOLD THE INK","PRESS THE PAPER","READ THE MARK","CLASSIFY THE METHOD"],"branches":[{"senses":"义项 01","en":"THE GESTURE ITSELF: the phrase first names the bare skill of cutting a line that can print.","cn":"动作本身：这个短语先指「刻出可印线条」这一门基本手艺。"},{"senses":"义项 02 · 03","en":"TWO SURFACES: metal is cut into and wood is cut around, yet both are still called engraving.","cn":"两种版面：金属是刻进去，木头是刻掉周围，两者却都仍叫 engraving。"},{"senses":"义项 04 · 05","en":"ACID AND EYE: acid can replace the blade, and the marks it leaves become the thing critics judge.","cn":"酸与眼：酸可以代替刀，而留下的痕迹成为评论家评判的对象。"},{"senses":"义项 06 · 07","en":"PROCESS AND MACHINE: the phrase grows from one stroke into a full sequence and then into an industrial operation.","cn":"流程与机器：这个短语从一刀扩展为整套流程，再扩展为工业工序。"},{"senses":"义项 08","en":"LABEL: once catalogued, the method becomes a word scholars use to sort objects.","cn":"标签：一经编目，方法就成为学者用来给物件分类的词。"}]},"affixes":{"intro":{"en":"The phrase is made of an English verb with a Germanic carving root and a Greek noun for skill, so both halves can be read morpheme by morpheme.","cn":"这个短语由带日耳曼语「刻」词根的英语动词与表示「技艺」的希腊语名词构成，两半都可以按语素读出。"},"latinIntro":{"en":"Latin had no part in the carving root and only borrowed the Greek skill word as technicus, so the Latin list here is short by nature.","cn":"拉丁语并未参与「刻」这个词根，只是把希腊语的「技艺」词借作 technicus，因此这里的拉丁词条本身就不多。"},"items":[{"word":"grafan","structure":"grafan (Old English verb, strong class VI)","meaning":"to dig, carve, scratch","meaningCN":"挖；刻；划","example":"Grafan named the cut before any plate existed.","exampleCN":"在版画出现之前，这个词就已指「刻」。"},{"word":"engrave","structure":"in- (prefix 'into') + graven (carve)","meaning":"to cut a design into a surface","meaningCN":"把图案刻进表面","example":"They engrave the date on the rim.","exampleCN":"他们把日期刻在边缘上。"},{"word":"engraver","structure":"engrave + -er (one who does)","meaning":"a person who cuts plates","meaningCN":"刻版的人","example":"The engraver proofed the plate twice.","exampleCN":"刻版师把版试印了两次。"},{"word":"engraving","structure":"engrave + -ing (action or result)","meaning":"the act of cutting, or the print produced","meaningCN":"刻版动作或成品版画","example":"The engraving hung above the press.","exampleCN":"那幅版画挂在压印机上方。"},{"word":"technē","structure":"technē (Greek noun, first declension)","meaning":"art, craft, systematic skill","meaningCN":"技艺；手艺；有章法的技能","example":"Technē covered both carpentry and poetry.","exampleCN":"这个词既涵盖木工也涵盖诗艺。"},{"word":"technique","structure":"technē through French technique","meaning":"a particular way of doing skilled work","meaningCN":"做精巧工作的具体方法","example":"Each printer guarded a different technique.","exampleCN":"每位印工都守着不同的技法。"},{"word":"technical","structure":"technē + -al (relating to)","meaning":"relating to a craft or its methods","meaningCN":"与技艺或其方法相关的","example":"The report is too technical for beginners.","exampleCN":"这份报告对初学者来说太专业了。"},{"word":"technician","structure":"technique + -ian (practitioner)","meaning":"a person trained in a craft","meaningCN":"受过技艺训练的人","example":"A technician checked the press rollers.","exampleCN":"一名技师检查了压印机的滚筒。"}],"latinEntries":[]}},{"word":"architect","ipa_uk":"/ˈɑːkɪtekt/","ipa_us":"/ˈɑːrkɪtekt/","definition_zh":"建筑师；总设计师；重大方案的谋划者；软件或系统架构师","definition_en":"a person who designs buildings and supervises their construction, or someone who plans and shapes a complex system or scheme","core_image":"一个人站在脚手架上，把纸上的线条对到尚未砌起的墙线上","scene":"工地的钢架已经立起，图纸钉在木板上。The architect walks the site each morning before the masons start.","sceneCN":"这里 architect 指「负责设计建筑并监督施工的人」（第 1 个义项：执业建筑师）；句意为石匠开工前，建筑师每天早晨都会走一遍工地。图中可辨识物件：钢架、图纸、木板、脚手架。","pos":[{"tag":"n.","zh":"建筑师；营造设计者"},{"tag":"n.","zh":"缔造者；总设计师（比喻）"},{"tag":"v.","zh":"设计并构建（系统、方案）"}],"collocations":[{"phrase":"chief architect","zh":"总建筑师；首席设计师"},{"phrase":"landscape architect","zh":"景观设计师"},{"phrase":"software architect","zh":"软件架构师"},{"phrase":"the architect of reform","zh":"改革的缔造者"},{"phrase":"architect of one's own fortune","zh":"自身命运的缔造者"},{"phrase":"naval architect","zh":"造船设计师"}],"forms":[{"label":"单数形式","form":"architect"},{"label":"复数形式","form":"architects"},{"label":"所有格","form":"architect's"},{"label":"动词三单","form":"architects"},{"label":"动词过去式","form":"architected"},{"label":"动词过去分词","form":"architected"},{"label":"动词现在分词","form":"architecting"}],"derivatives":[{"word":"architecture","pos":"n.","zh":"建筑学；建筑风格；体系结构"},{"word":"architectural","pos":"adj.","zh":"建筑（学）的"},{"word":"architecturally","pos":"adv.","zh":"在建筑方面"},{"word":"architectonics","pos":"n.","zh":"结构学；构造原理"},{"word":"architected","pos":"adj.","zh":"（系统）经架构设计的"}],"senses":[{"no":"01","title":"A licensed designer of buildings","titleCN":"执业建筑师","definition":"a professional who designs buildings, prepares drawings and supervises the work on site","definitionCN":"设计建筑、绘制图纸并监督现场施工的专业人士","example":"The architect revised the facade after the client saw the mock-up.","exampleCN":"客户看过模型后，建筑师修改了立面。","why":"the oldest sense is the master of the whole building, the person who both draws and answers for what is built.","whyCN":"最早的义项就是整栋建筑的主事者：既画图，也要为建成之物负责。"},{"no":"02","title":"The shaper of a large scheme","titleCN":"重大方案的缔造者","definition":"a person who plans and shapes a policy, institution or movement","definitionCN":"规划并塑造某项政策、制度或运动的人","example":"She was the architect of the treaty that ended the dispute.","exampleCN":"她是终结这场争端的条约的缔造者。","why":"a building is a plan made real, so anyone who turns an intention into a working structure earns the same name.","whyCN":"建筑是把计划变成实体，因此任何把意图变成可行结构的人都能得到这个称呼。"},{"no":"03","title":"A designer of software systems","titleCN":"软件或系统架构师","definition":"a engineer who decides the structure, boundaries and interactions of a large software system","definitionCN":"决定大型软件系统的结构、边界与交互方式的工程师","example":"The architect split the service into three bounded modules.","exampleCN":"架构师把这项服务拆成三个边界清晰的模块。","why":"software borrowed the word because its work is again to fix a plan before many hands build parts of it.","whyCN":"软件业借用这个词，因为其工作同样是先定下蓝图，再由许多双手分头建造。"},{"no":"04","title":"The planner of a complex project","titleCN":"复杂工程的总体规划者","definition":"the person who fixes the overall scheme of a large project before specialists begin","definitionCN":"在各方专家动工之前定下整体方案的人","example":"As architect of the exhibition, he chose the route before the curators wrote labels.","exampleCN":"作为展览的总体规划者，他在策展人写标签之前就定好了参观路线。","why":"the word marks the one who holds the whole in mind while others hold only a part.","whyCN":"这个词标记的是心中装着整体的人，而其他人只掌握其中一部分。"},{"no":"05","title":"The old master builder","titleCN":"古义的营造匠师","definition":"in older usage, the head craftsman who controlled both design and construction","definitionCN":"旧用法中同时掌管设计与施工的匠师首领","example":"In the old guild, the architect also bought the stone and hired the carvers.","exampleCN":"在旧行会里，营造匠师还负责买石料、雇雕刻工。","why":"before the professions split, drawing and building were one trade, and the title covered both.","whyCN":"在各专业分工之前，画图与施工本是一门行当，这个称号两者都涵盖。"},{"no":"06","title":"To design and build a system","titleCN":"动词义：设计并构建","definition":"to plan and assemble something complex, especially a technical system","definitionCN":"规划并搭建复杂事物，尤指技术系统","example":"They architected the network around a single secure gateway.","exampleCN":"他们围绕一个安全网关设计了整个网络。","why":"the verb is the noun turned into action: to do what an architect does, even when no building results.","whyCN":"动词是名词的动作化：做建筑师所做的事，即使最终没有实体建筑。"},{"no":"07","title":"A maker of the universe","titleCN":"神学与哲学中的造物主","definition":"a being credited with designing and making the world","definitionCN":"被认为设计并制造了世界的存在","example":"The hymn calls the creator the architect of the heavens.","exampleCN":"赞美诗称造物主为诸天的建筑师。","why":"the image of a cosmic builder is natural wherever a culture already thinks of building as the highest craft.","whyCN":"在一个把营造视为最高技艺的文化里，宇宙建造者的形象自然会出现。"},{"no":"08","title":"The builder of a plot or structure","titleCN":"情节或结构的构思者","definition":"a person who constructs the framework of a story, argument or work of art","definitionCN":"搭建故事、论证或艺术作品框架的人","example":"The novelist is the architect of a plot whose rooms the reader never sees.","exampleCN":"小说家是情节的建筑师，读者看不见那些房间的全貌。","why":"the metaphor survives because a plot also needs walls, doors and a load-bearing line.","whyCN":"这个比喻成立，是因为情节同样需要墙、门与一条承重的线。"}],"etymology":{"intro":{"en":"Architect comes from Greek through Latin and French, and its two halves mean 'chief' and 'builder'. Dates are approximate.","cn":"architect 经拉丁语与法语来自希腊语，两部分分别意为「首领」与「建造者」。年代均为约数。"},"items":[{"era":"GREEK TEKTON","en":"Tekton named a craftsman who works wood or stone, especially a builder; the word was applied to carpentry before it named design.","cn":"tekton 指加工木石的手艺人，尤指建造者；这个词最初用于木工，后来才与设计相连。"},{"era":"GREEK ARKHITEKTON","en":"Adding a word for 'chief, leader' produced arkhitekton, the head builder who directed other craftsmen.","cn":"加上表示「首领、领队」的词，得到 arkhitekton，即指挥其他匠人的匠师首领。"},{"era":"LATIN ARCHITECTUS","en":"Latin borrowed the term as architectus and used it for the designer of buildings and, by extension, of any plan.","cn":"拉丁语借入该词作 architectus，指建筑设计者，并引申指任何方案的制定者。"},{"era":"FRENCH ARCHITECTE","en":"Middle French architecte carried the word into English in the sixteenth century, when the profession was being separated from masonry.","cn":"中古法语 architecte 在十六世纪把该词带入英语，其时建筑师正从石匠行当中分离出来。"},{"era":"MODERN METAPHOR","en":"From the eighteenth century the word was used for the author of a constitution, a treaty or a movement, not only of a building.","cn":"从十八世纪起，这个词不仅指建筑的设计者，也指宪法、条约或运动的制定者。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Greek ancestry of tekton is not established, and the leading etymology treats it as a loan from an older Mediterranean language rather than a native Greek formation.","cn":"来源不确定（更深来源）：tekton 在希腊语之前的谱系未得到证明，主流词源学把它视为来自更早的地中海语言的借词，而非希腊语自身构成。"}]},"similar":{"note":{"en":"Group one holds words built on the same Greek builder root or easily mistaken for it; group two holds people who plan alongside the architect.","cn":"第一组是同出希腊「建造者」词根或容易被误认作同族的词；第二组是与建筑师并肩做规划的邻近职业。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"architecture","ipa":"/ˈɑːkɪtektʃə/","tag":"same root, abstract noun","definition":"The art or science of building, or the structure of a system; it is the abstract noun of architect, not another person.","definitionCN":"建筑的艺术或学问，也指系统的结构；是 architect 的抽象名词，而非另一个从业者。"},{"word":"architectural","ipa":"/ˌɑːkɪˈtektʃərəl/","tag":"adjective form","definition":"Relating to architecture; it describes a quality of a building, not a person.","definitionCN":"与建筑学相关的；描述建筑的品质，而非人。"},{"word":"architectonics","ipa":"/ˌɑːkɪtekˈtɒnɪks/","tag":"scientific structure","definition":"The systematic arrangement of knowledge or structure, from the same Greek root but used as a technical noun.","definitionCN":"知识或结构的系统编排，同出希腊词根，但作为技术名词使用。"},{"word":"tekton","ipa":"/ˈtektɒn/","tag":"the bare root","definition":"The Greek noun for a builder that survives in geology as the study of crustal building; it never means designer by itself.","definitionCN":"希腊语中「建造者」本词，在地质学中残留为地壳构造研究；单独使用时从不表示设计者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"designer","ipa":"/dɪˈzaɪnə/","tag":"general planner","definition":"Anyone who plans the look or working of something; architect is the specialist who also answers for the built result.","definitionCN":"泛指规划外观或运作方式的人；architect 则是还要为建成结果负责的专门人士。"},{"word":"engineer","ipa":"/ˌendʒɪˈnɪə/","tag":"technical builder","definition":"A person who solves technical problems by calculation and construction; the two roles overlap on large projects.","definitionCN":"靠计算与建造解决技术问题的人；在大工程中两种角色互相交叠。"},{"word":"planner","ipa":"/ˈplænə/","tag":"layout of land","definition":"A person who decides how land or a project should be laid out; the word stresses arrangement rather than building.","definitionCN":"决定土地或项目如何布局的人；该词强调安排而非建造。"},{"word":"builder","ipa":"/ˈbɪldə/","tag":"one who constructs","definition":"A person or firm that actually puts a structure up; the architect draws it and the builder raises it.","definitionCN":"实际把结构立起来的人或公司；建筑师画图，建造者施工。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real Greek halves, the real profession words and the real metaphor.","cn":"正常联想：两个真实的希腊语构件、真实的职业词与真实的比喻义。"},"normal":[{"en":"Two halves: 'chief' plus 'builder', so an architect is the chief builder of a plan.","cn":"两部分：首领加建造者，因此建筑师是一份蓝图的首席建造者。"},{"en":"The family runs architect, architecture, architectural, architecturally, architectonics.","cn":"同族词包括 architect、architecture、architectural、architecturally、architectonics。"},{"en":"Fixed phrases mark the branches: chief architect, software architect, the architect of reform.","cn":"固定搭配标出各分支：总建筑师、软件架构师、改革的缔造者。"},{"en":"The same root appears in tectonic, the geology of building the earth's crust.","cn":"同一词根出现在 tectonic 中，指建造地壳的地质学。"},{"en":"The modern verb keeps the noun's work: to architect a system is to fix its frame first.","cn":"现代动词保留了名词的工作：架构一个系统，就是先定下它的骨架。"}],"abstract":[{"en":"Picture a person holding a whole house inside a folded sheet of paper.","cn":"想象一个人把整栋房子折进一张纸里拿着。"},{"en":"Picture a conductor who never plays an instrument but decides where every player stands.","cn":"想象一位从不演奏乐器、却决定每位乐手站位的指挥。"},{"en":"Picture a skeleton drawn first, with the flesh of a project added later around it.","cn":"想象先画一副骨架，项目的血肉之后再围绕它长上去。"}]},"examples":[{"en":"The architect walked the roof to check how rain would drain.","cn":"建筑师走上屋顶，查看雨水会如何排出。"},{"en":"He was the architect of the peace deal and its quietest negotiator.","cn":"他是这份和平协议的缔造者，也是最不张扬的谈判者。"},{"en":"We architected the pipeline so that one failure cannot stop the rest.","cn":"我们把整条流程设计成单点故障不会拖停其余部分的样子。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"archi（首领）+ tect（建造）→ 匠人中的首领 → 建筑师；引申为总设计师","word":"architect"},"root":"希腊语 arkhitekton「匠师首领」= arkhi-（首领）+ tekton「建造者」；经拉丁 architectus、法语 architecte 入英语。tekton 的更深来源不确定。英语 architect。","sensesIntro":{"en":"Eight senses follow one role: someone holds the whole plan in mind; that role then widens from buildings to policies, software, projects, the old guild, the cosmos and the frame of a story.","cn":"八个义项沿同一个角色展开：有人心中装着整份蓝图；这个角色再从建筑扩展到政策、软件、工程、旧行会、宇宙，最后到故事的框架。"},"semanticMap":{"core":{"en":"CORE IMAGE: a figure stands with the whole building in mind while many hands hold only one stone each.","cn":"核心意象：一个人心中装着整栋建筑，而许多双手各自只握着一块石头。"},"chain":["HOLD THE PLAN","DRAW THE FRAME","DIRECT THE HANDS","ANSWER FOR THE RESULT","EXTEND TO SYSTEMS","NAME THE MAKER"],"branches":[{"senses":"义项 01","en":"THE PROFESSION: the first sense is the person licensed to draw a building and answer for it.","cn":"职业本身：第一个义项是有执照绘制建筑并为其负责的人。"},{"senses":"义项 02 · 04","en":"THE SCHEME: a policy or a large project is a building whose material is decisions.","cn":"方案：政策或大工程，是一座以决定为材料的建筑。"},{"senses":"义项 03 · 06","en":"THE SYSTEM: software turns the role into structure and then into a verb.","cn":"系统：软件把这个角色变成结构，随后又变成动词。"},{"senses":"义项 05 · 07","en":"THE OLD MASTER AND THE COSMIC ONE: the guild head and the creator are the same figure at two scales.","cn":"旧匠师与造物主：行会首领与造物主，是同一形象的两个尺度。"},{"senses":"义项 08","en":"THE STORY: a plot also needs a load-bearing line before anything can stand on it.","cn":"故事：情节也需要一条承重线，别的东西才能立在其上。"}]},"affixes":{"intro":{"en":"Architect is a Greek compound that entered English through Latin and French, and both of its halves still build other words.","cn":"architect 是一个经拉丁语与法语进入英语的希腊语复合词，两个构件至今仍在构成其他词。"},"latinIntro":{"en":"Latin architectus and architectura carried the Greek compound onward; Latin also supplied the adjective architectonicus.","cn":"拉丁语 architectus 与 architectura 把这个希腊复合词传下去，另有一个形容词 architectonicus。"},"items":[{"word":"arkhi-","structure":"arkhi- (Greek prefix, 'chief, first')","meaning":"chief; leading","meaningCN":"首领的；首要的","example":"The prefix marks the one who leads the others.","exampleCN":"这个前缀标记的是带领其他人的那一位。"},{"word":"tekton","structure":"tekton (Greek noun, 'builder, carpenter')","meaning":"builder; craftsman in wood or stone","meaningCN":"建造者；木石匠人","example":"The second half names the craft itself.","exampleCN":"后半部分点明手艺本身。"},{"word":"architectus","structure":"architectus (Latin noun, from Greek)","meaning":"master builder, designer","meaningCN":"匠师；设计者","example":"Latin kept the Greek halves unchanged.","exampleCN":"拉丁语原样保留了希腊语的两个构件。"},{"word":"architect","structure":"architectus through French architecte","meaning":"a designer of buildings","meaningCN":"建筑设计者","example":"The architect signed the drawings.","exampleCN":"建筑师在图纸上签了名。"},{"word":"architecture","structure":"architect + -ure (result or art)","meaning":"the art or result of building","meaningCN":"建筑的艺术或成果","example":"The architecture of the hall favors daylight.","exampleCN":"这座大厅的建筑设计偏重自然光。"},{"word":"architectural","structure":"architecture + -al (relating to)","meaning":"relating to building design","meaningCN":"与建筑设计相关的","example":"The city protects its architectural heritage.","exampleCN":"这座城市保护其建筑遗产。"},{"word":"architecturally","structure":"architectural + -ly (in that manner)","meaning":"in terms of building design","meaningCN":"从建筑设计角度看","example":"The two wings are architecturally unrelated.","exampleCN":"两翼在建筑风格上并无关联。"},{"word":"architectonics","structure":"architectonic + -s (field of study)","meaning":"the science of systematic structure","meaningCN":"系统构造之学","example":"The book studies the architectonics of knowledge.","exampleCN":"这本书研究知识的构造体系。"}],"latinEntries":[{"word":"architectus","structure":"architectus, architecti (m., second declension; from Greek)","meaning":"master builder, architect","meaningCN":"匠师；建筑师"},{"word":"architectura","structure":"architectura, architecturae (f., first declension)","meaning":"the art of building","meaningCN":"建筑之术"},{"word":"architectonicus","structure":"architectonicus, architectonica, architectonicum (adj.)","meaning":"skilled in building; structural","meaningCN":"擅长营造的；构造上的"}]}},{"word":"architectural style","ipa_uk":"/ˌɑːkɪˈtektʃərəl staɪl/","ipa_us":"/ˌɑːrkɪˈtektʃərəl staɪl/","definition_zh":"建筑风格；某一时期或地域的建筑形制与审美特征；建筑史中的风格分类","definition_en":"the characteristic forms, proportions and ornaments shared by buildings of a period, place or movement","core_image":"同一条街上并列着尖拱、圆拱与方盒子，一眼就能看出它们属于不同年代","scene":"街上并排着尖顶石屋、圆顶教堂和一排玻璃方楼。A guide uses each facade to explain a different architectural style without naming a single date.","sceneCN":"这里 architectural style 指「某一时期或流派在建筑上共有的形制与审美特征」（第 1 个义项：建筑风格的总称）；句意为导游借每一面立面讲一种不同的建筑风格，却一个年代都不提。图中可辨识物件：尖顶石屋、圆顶教堂、玻璃方楼、街面。","pos":[{"tag":"n.","zh":"建筑风格（可数名词短语）"},{"tag":"n.","zh":"建筑形制与审美体系"}],"collocations":[{"phrase":"Gothic architectural style","zh":"哥特式建筑风格"},{"phrase":"classical architectural style","zh":"古典建筑风格"},{"phrase":"modern architectural style","zh":"现代建筑风格"},{"phrase":"regional architectural style","zh":"地域建筑风格"},{"phrase":"a blend of architectural styles","zh":"多种建筑风格的混合"},{"phrase":"identify an architectural style","zh":"辨认一种建筑风格"}],"forms":[{"label":"单数形式","form":"architectural style"},{"label":"复数形式","form":"architectural styles"},{"label":"所有格","form":"architectural style's"},{"label":"相关形容词","form":"architectural"},{"label":"相关名词","form":"architecture"}],"derivatives":[{"word":"architecture","pos":"n.","zh":"建筑学；建筑；体系结构"},{"word":"architect","pos":"n.","zh":"建筑师"},{"word":"style","pos":"n.","zh":"风格；样式"},{"word":"stylistic","pos":"adj.","zh":"风格上的"},{"word":"stylize","pos":"v.","zh":"使风格化"},{"word":"stylus","pos":"n.","zh":"刻写笔；触控笔"}],"senses":[{"no":"01","title":"The shared look of a period","titleCN":"某一时期共有的外观","definition":"the set of forms, proportions and ornaments that buildings of one period share","definitionCN":"同一时期的建筑在形制、比例与装饰上共有的那一套特征","example":"The whole quarter keeps one architectural style, down to the window frames.","exampleCN":"整个街区保持同一种建筑风格，连窗框也不例外。","why":"style here means a recognizable family resemblance, so the phrase names what makes a group of buildings look related.","whyCN":"这里的 style 指可辨认的家族相似，因此短语命名的是让一群建筑看起来同源的东西。"},{"no":"02","title":"The classical orders","titleCN":"古典柱式体系","definition":"the system of Doric, Ionic and Corinthian columns with fixed proportions and entablatures","definitionCN":"由多立克、爱奥尼与科林斯柱式连同固定比例与檐部构成的体系","example":"The bank chose an architectural style of columns and pediments to look permanent.","exampleCN":"这家银行选用带柱与山花的古典建筑风格，好显得恒久。","why":"classical style is a grammar with rules, so a building can be correct or incorrect within it.","whyCN":"古典风格是一套有规则的语法，因此一栋建筑在其中可以被判为合规或不合规。"},{"no":"03","title":"Romanesque and Gothic","titleCN":"罗曼式与哥特式","definition":"the medieval styles marked first by heavy round arches and then by pointed arches and ribbed vaults","definitionCN":"中世纪风格，先以厚重的圆拱为标志，后以尖拱与肋拱顶为标志","example":"The nave shows how an architectural style can change within one building campaign.","exampleCN":"这座中殿显示，一种建筑风格在同一次建造中也会发生变化。","why":"the structural problem of height and light drove both styles, so their differences are engineering as much as taste.","whyCN":"高度与采光的结构难题推动了这两种风格，因此它们的差别既是工程也是审美。"},{"no":"04","title":"Renaissance and Baroque","titleCN":"文艺复兴与巴洛克","definition":"the styles that revived classical order and then stretched it into movement, curve and display","definitionCN":"先复兴古典秩序、再把它拉向动感、曲线与铺陈的风格","example":"The palace mixes an architectural style of calm symmetry with a Baroque staircase.","exampleCN":"这座宫殿把平静对称的建筑风格与一道巴洛克楼梯混在一起。","why":"each style answers the one before it, so the phrase also names a position in an argument about proportion.","whyCN":"每种风格都在回应前一种，因此这个短语也标记了一场关于比例的论辩中的立场。"},{"no":"05","title":"Modernism and the international style","titleCN":"现代主义与国际式","definition":"the twentieth-century style of plain surfaces, exposed structure and refusal of ornament","definitionCN":"二十世纪那种表面素净、结构外露并拒绝装饰的风格","example":"Critics said the new library had no architectural style at all, only a grid.","exampleCN":"评论家说新图书馆根本没有建筑风格，只有一张网格。","why":"modernism claimed to end style, yet its rules became a style recognizable enough to be named and copied.","whyCN":"现代主义声称终结风格，但它的规则本身成了足够可辨、可被命名与模仿的一种风格。"},{"no":"06","title":"Regional and vernacular building","titleCN":"地域与乡土建筑","definition":"the local forms that grow from climate, material and craft rather than from a named movement","definitionCN":"由气候、材料与手艺生长出来、而非出自某个有名流派的地方形制","example":"The island has an architectural style of low walls and thick whitewash.","exampleCN":"这座岛有一种低墙厚白灰的建筑风格。","why":"vernacular style is learned by copying neighbours, so it is a style without an author.","whyCN":"乡土风格靠模仿邻里习得，因此是一种没有作者的风格。"},{"no":"07","title":"A dating tool in art history","titleCN":"建筑史中的断代工具","definition":"a category scholars use to place a building in time, region or school","definitionCN":"学者用来把建筑放入某个年代、地区或流派的分类范畴","example":"A single carved capital can fix the architectural style of a ruined church.","exampleCN":"一个雕花柱头就能定下一座废教堂的建筑风格。","why":"once style is used for dating, the phrase stops describing a look and starts making a claim about history.","whyCN":"一旦风格被用于断代，这个短语就不再描述外观，而在对历史作出判断。"},{"no":"08","title":"The frame of any work","titleCN":"泛指作品的整体构造方式","definition":"the overall organizing manner of a work, argument or organization","definitionCN":"作品、论证或组织整体的组织方式","example":"The report has an architectural style of its own: broad base, narrow top, no ornament.","exampleCN":"这份报告有自己的一套构造风格：底盘宽、顶部窄、不加装饰。","why":"the metaphor works because any built thing, physical or not, must decide what carries the weight.","whyCN":"这个比喻成立，因为任何被建造之物，不论是否实体，都必须决定由什么承重。"}],"etymology":{"intro":{"en":"The phrase joins the Latin-derived word for building art to a Latin word for a writing tool whose meaning drifted into 'manner'. Dates are approximate.","cn":"这个短语把源自拉丁语的「建筑之术」与一个拉丁语「书写工具」词连起来，后者的意义漂移为「方式」。年代均为约数。"},"items":[{"era":"LATIN ARCHITECTURA","en":"Architectura named the art of the architect, built on the Greek compound for chief builder.","cn":"architectura 指建筑师之术，其基础是表示「匠师首领」的希腊语复合词。"},{"era":"LATIN STILUS","en":"Stilus was the pointed metal tool used to write on wax tablets; by transfer it came to mean the manner of writing.","cn":"stilus 是蜡板上书写用的尖金属笔；经转喻，它开始指书写的方式。"},{"era":"GREEK STULOS INFLUENCE","en":"The English spelling style reflects the influence of Greek stulos 'column', which is a spelling loan and not the source of the word.","cn":"英语拼写 style 受希腊语 stulos「柱子」影响，但这只是拼写上的借形，并非词源。"},{"era":"SIXTEENTH-CENTURY USAGE","en":"Writers on art began to speak of the style of a building, meaning the manner its parts were handled.","cn":"十六世纪的艺术写作者开始谈某座建筑的 style，指其各部分被处理的方式。"},{"era":"ART-HISTORY TERM","en":"In the nineteenth century the phrase became a technical label for periods and schools, such as Gothic or Romanesque.","cn":"到十九世纪，这个短语成为指称时期与流派的技术标签，如哥特式或罗曼式。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the ancestry of stilus before Latin is not established, and the link sometimes proposed to a verb for 'pricking' remains a hypothesis.","cn":"来源不确定（更深来源）：stilus 在拉丁语之前的谱系未得到证明，有人提出它与表示「刺」的动词有关，那仍只是假说。"}]},"similar":{"note":{"en":"Group one holds terms that look like style words but name different things; group two holds words for the same idea seen from another angle.","cn":"第一组是看起来像风格词、实则指别的东西的术语；第二组是从另一角度看同一概念的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stylus","ipa":"/ˈstaɪləs/","tag":"the original tool","definition":"The pointed writing tool that gave style its name; it is a physical object, not a manner.","definitionCN":"给 style 命名的尖头书写工具，是实物，而非方式。"},{"word":"stylistic","ipa":"/staɪˈlɪstɪk/","tag":"adjective, not a style","definition":"Relating to style as a quality; a stylistic choice is a choice about manner, not a named period.","definitionCN":"指与风格这一属性相关的；风格上的选择是关于方式的选择，而非某个有名时期。"},{"word":"stylized","ipa":"/ˈstaɪlaɪzd/","tag":"deliberately simplified","definition":"Simplified according to an artistic convention; it describes a treatment, not a building tradition.","definitionCN":"按某种艺术惯例加以简化；描述处理手法，而非建筑传统。"},{"word":"architecture","ipa":"/ˈɑːkɪtektʃə/","tag":"the field, not the manner","definition":"The discipline or the built result; two buildings of the same architecture can differ in style.","definitionCN":"指学科或建成成果；同属一种建筑学传统的两栋建筑，风格仍可不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"architectural order","ipa":"/ˈɔːdə/","tag":"rule system","definition":"The fixed proportions of columns and entablature; an order is one possible basis of a style, not the style itself.","definitionCN":"柱与檐部的固定比例；柱式只是某种风格可能的基础，而非风格本身。"},{"word":"building tradition","ipa":"/trəˈdɪʃn/","tag":"handed-down practice","definition":"A way of building passed between generations; it stresses method and training more than visual identity.","definitionCN":"代代相传的建造方式；更强调方法与训练，而非视觉特征。"},{"word":"design language","ipa":"/dɪˈzaɪn ˈlæŋɡwɪdʒ/","tag":"modern phrasing","definition":"A contemporary term for a consistent set of forms across products or buildings; it avoids the period claims of style.","definitionCN":"当代术语，指产品与建筑中共用的一套形制；它回避了 style 所带的时代断言。"},{"word":"look","ipa":"/lʊk/","tag":"plain everyday word","definition":"The everyday word for visible appearance; it carries no claim about period, rules or school.","definitionCN":"指可见外观的日常词，不含年代、规则或流派方面的断言。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin sources, the real period labels and the real art-history use.","cn":"正常联想：真实的拉丁语来源、真实的时期标签与真实的艺术史用法。"},"normal":[{"en":"Architecture gives the field; style gives the manner; together they name the manner of a building family.","cn":"architecture 给领域，style 给方式，合起来指一个建筑家族的做事方式。"},{"en":"The family runs style, stylistic, stylize, stylized, stylus.","cn":"同族词包括 style、stylistic、stylize、stylized、stylus。"},{"en":"Fixed phrases sort the periods: Gothic, classical, modern, regional architectural style.","cn":"固定搭配把时期分开：哥特式、古典式、现代式、地域性建筑风格。"},{"en":"The pointed writing tool and the Greek word for column both shaped the spelling of style.","cn":"尖头书写工具与希腊语「柱子」一词都影响了 style 的拼写。"},{"en":"Art historians date a building by its smallest carved detail, not by its size.","cn":"艺术史家靠最小的雕饰细节而非体量来给建筑断代。"}],"abstract":[{"en":"Picture three generations standing in one doorway, each wearing the coat of their own decade.","cn":"想象三代人站在同一道门里，各自穿着自己那个年代的外套。"},{"en":"Picture a language whose grammar is made of stone, so every sentence must be built before it is spoken.","cn":"想象一种语法由石头构成的语言，每句话都得先建起来才能说出。"},{"en":"Picture a family album where every house is a self-portrait of the person who paid for it.","cn":"想象一本家庭相册，每栋房子都是出钱建造者的自画像。"}]},"examples":[{"en":"The station borrows its architectural style from the town hall across the square.","cn":"这座车站的建筑风格借自广场对面的市政厅。"},{"en":"No single architectural style dominates the old port, which grew in waves.","cn":"老港区没有哪一种建筑风格占主导，它是分几波扩建起来的。"},{"en":"Students must identify the architectural style from a photograph of one window.","cn":"学生要凭一张窗户照片判断建筑风格。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"architectural（建筑的）+ style（风格）→ 建筑上的那套做法与样子 → 建筑风格","word":"architectural style"},"root":"architectural 源自拉丁 architectura「建筑之术」；style 源自拉丁 stilus「蜡板刻写笔」，转指书写方式；拼写受希腊 stulos「柱子」影响。英语 architectural style。","sensesIntro":{"en":"Eight senses follow one question: what makes a group of buildings look related? The answer moves from a shared look, through named periods and rules, to a dating tool and finally to any constructed frame.","cn":"八个义项围绕同一个问题展开：是什么让一群建筑看起来同源？答案从共同外观，经有名时期与规则，走到断代工具，最后落到任何被构造的框架上。"},"semanticMap":{"core":{"en":"CORE IMAGE: one street holds three centuries at once, and each facade tells you its own date without a plaque.","cn":"核心意象：一条街上同时站着三个世纪，每面立面都不用铭牌就说出自己的年代。"},"chain":["SHARED LOOK","FIXED RULES","STRUCTURAL ANSWER","PERIOD LABEL","LOCAL HABIT","DATING TOOL"],"branches":[{"senses":"义项 01","en":"RESEMBLANCE: the phrase begins with the plain fact that certain buildings look like relatives.","cn":"相似：这个短语从「某些建筑看起来像亲戚」这一朴素事实开始。"},{"senses":"义项 02 · 03","en":"RULES AND STRUCTURE: columns follow a grammar, while arches answer a problem of height and light.","cn":"规则与结构：柱式遵循一套语法，而拱券回应高度与采光的难题。"},{"senses":"义项 04 · 05","en":"REVIVAL AND REFUSAL: one style revives the past, the next claims to have no style at all.","cn":"复兴与拒绝：一种风格复兴过去，下一种则声称自己根本没有风格。"},{"senses":"义项 06 · 08","en":"HABIT WITHOUT AN AUTHOR: local building and any constructed frame show style as an organizing manner.","cn":"没有作者的习惯：乡土建造与任何被构造的框架，都把风格显示为一种组织方式。"},{"senses":"义项 07","en":"THE LABEL: scholars turn the look into a tool for placing a building in time.","cn":"标签：学者把外观变成一种把建筑放回时间里的工具。"}]},"affixes":{"intro":{"en":"The phrase combines a Latin noun of building with a Latin noun of writing that became a noun of manner, so each half has its own derivational family.","cn":"这个短语把一个拉丁语「建筑」名词与一个由「书写」转为「方式」的拉丁语名词组合起来，两半各有自己的派生家族。"},"latinIntro":{"en":"Latin architectura and stilus both passed into English through French, and stilus also gave the doublet stylus.","cn":"拉丁语 architectura 与 stilus 都经法语进入英语，而 stilus 还给出了同源异形词 stylus。"},"items":[{"word":"architectura","structure":"architectura, architecturae (Latin noun, first declension)","meaning":"the art of building","meaningCN":"建筑之术","example":"Architectura covered design and construction alike.","exampleCN":"这个词同时涵盖设计与施工。"},{"word":"architectural","structure":"architecture + -al (relating to)","meaning":"relating to building design","meaningCN":"与建筑设计相关的","example":"The drawing is an architectural record.","exampleCN":"这张图是一份建筑记录。"},{"word":"architecture","structure":"architect + -ure (result or art)","meaning":"building art or built result","meaningCN":"建筑之术或建成成果","example":"The architecture of the station is austere.","exampleCN":"这座车站的建筑风格很朴素。"},{"word":"stilus","structure":"stilus, stili (Latin noun, second declension)","meaning":"a pointed writing tool; manner of writing","meaningCN":"尖头书写工具；书写方式","example":"Stilus meant the tool before it meant the manner.","exampleCN":"stilus 先指工具，后指方式。"},{"word":"style","structure":"stilus through Old French style","meaning":"manner; characteristic form","meaningCN":"方式；特征性形制","example":"The style of the porch is unmistakable.","exampleCN":"这道门廊的风格不会认错。"},{"word":"stylistic","structure":"style + -istic (relating to a quality)","meaning":"relating to manner","meaningCN":"与方式相关的","example":"The change is stylistic rather than structural.","exampleCN":"这一改动属于风格层面，而非结构层面。"},{"word":"stylize","structure":"style + -ize (make or conform)","meaning":"to treat in a simplified artistic manner","meaningCN":"按简化的艺术方式处理","example":"The sculptor stylized the leaves into flat fans.","exampleCN":"雕刻家把叶子处理成扁平的扇面。"},{"word":"stylus","structure":"stilus, respelled through Latin","meaning":"a pointed instrument for writing or touching","meaningCN":"书写或触控用的尖头工具","example":"A stylus scratched the wax tablet.","exampleCN":"一支尖笔划过了蜡板。"}],"latinEntries":[{"word":"architectura","structure":"architectura, architecturae (f., first declension)","meaning":"the art of building","meaningCN":"建筑之术"},{"word":"stilus","structure":"stilus, stili (m., second declension)","meaning":"pointed writing tool; manner of writing","meaningCN":"尖头书写工具；书写方式"}]}},{"word":"cathedral","ipa_uk":"/kəˈθiːdrəl/","ipa_us":"/kəˈθiːdrəl/","definition_zh":"主教座堂；大教堂；设有主教宝座的教堂","definition_en":"the principal church of a diocese, which contains the bishop's throne and is usually a very large building","core_image":"一座巨教堂的唱诗席旁，主教的宝座比所有座椅都高，整座建筑围绕这个座位展开","scene":"石砌长廊里管风琴正在试音，回声一直滚到后殿。The cathedral keeps the bishop's seat at the centre of the choir.","sceneCN":"这里 cathedral 指「设有主教宝座、作为一个教区首要教堂的主教座堂」（第 1 个义项：主教宝座所在的教区主堂）；句意为这座主教座堂把主教的座位安置在唱诗席的正中。图中可辨识物件：石砌长廊、管风琴、唱诗席、主教座椅。","pos":[{"tag":"n.","zh":"主教座堂；大教堂"},{"tag":"n.","zh":"（比喻）宏伟殿堂"}],"collocations":[{"phrase":"Gothic cathedral","zh":"哥特式大教堂"},{"phrase":"cathedral city","zh":"有主教座堂的城市"},{"phrase":"cathedral choir","zh":"座堂唱诗班"},{"phrase":"cathedral spire","zh":"大教堂尖塔"},{"phrase":"a cathedral of commerce","zh":"商业殿堂（比喻）"},{"phrase":"the cathedral's nave","zh":"大教堂的中殿"}],"forms":[{"label":"单数形式","form":"cathedral"},{"label":"复数形式","form":"cathedrals"},{"label":"所有格","form":"cathedral's"},{"label":"相关形容词","form":"cathedral (attributive)"},{"label":"相关名词（宝座）","form":"cathedra"}],"derivatives":[{"word":"cathedra","pos":"n.","zh":"主教宝座；权威讲席"},{"word":"cathedral city","pos":"n.","zh":"有主教座堂的城市"},{"word":"cathedral choir","pos":"n.","zh":"座堂唱诗班"},{"word":"cathedral-like","pos":"adj.","zh":"大教堂般的"},{"word":"ex cathedra","pos":"adv.","zh":"以权威身份（宣告）"}],"senses":[{"no":"01","title":"The bishop's principal church","titleCN":"主教座堂","definition":"the main church of a diocese, containing the throne of its bishop","definitionCN":"一个教区的主要教堂，内置该教区主教的宝座","example":"The bishop entered the cathedral through the north porch.","exampleCN":"主教从北侧门廊进入主教座堂。","why":"the word comes from the name of the seat itself, so a church is a cathedral only because a bishop's chair stands in it.","whyCN":"这个词来自「座位」本身的名字，因此一座教堂之所以是主教座堂，只因主教的座位立在其中。"},{"no":"02","title":"Any very large church","titleCN":"泛指大教堂","definition":"in everyday usage, any church impressive enough to seem like a bishop's seat","definitionCN":"在日常说法里，泛指任何宏伟得像是主教座堂的教堂","example":"Tourists call the parish church a cathedral because of its spire.","exampleCN":"游客因为那座尖塔，把这座堂区教堂称作大教堂。","why":"size and dignity blur the technical line, so the popular sense is wider than the church's actual rank.","whyCN":"体量与庄严模糊了技术界线，因此通俗义比教堂的实际等级更宽。"},{"no":"03","title":"A Gothic building type","titleCN":"哥特式大教堂建筑类型","definition":"a building type defined by pointed arches, ribbed vaults, flying buttresses and a long nave","definitionCN":"以尖拱、肋拱顶、飞扶壁与长中殿为特征的建筑类型","example":"The cathedral is studied as a machine for making coloured light.","exampleCN":"这座大教堂被当作一台制造彩色光的机器来研究。","why":"the great medieval cathedrals solved height and light together, so the building became a type with its own engineering logic.","whyCN":"中世纪的大教堂把高度与采光一并解决，因此这种建筑自成一个有工程逻辑的类型。"},{"no":"04","title":"The seat of a diocese","titleCN":"教区中心的座堂","definition":"the church that marks the administrative centre of a diocese and its city","definitionCN":"标记一个教区及其所在城市行政中心的教堂","example":"The small cathedral still governs a diocese larger than three counties.","exampleCN":"这座不大的座堂仍管理着比三个郡还大的教区。","why":"a cathedral is first an administrative fact: where the seat is, there the diocese is governed.","whyCN":"主教座堂首先是一个行政事实：座位在哪里，教区就在哪里受管理。"},{"no":"05","title":"The chapter and its clergy","titleCN":"座堂教士团","definition":"the body of clergy attached to a cathedral, led by a dean","definitionCN":"附属于座堂的教士团体，通常由座堂主任牧师领导","example":"The cathedral voted to keep the boys' choir after the funding cut.","exampleCN":"经费削减后，座堂教士团投票决定保留男童唱诗班。","why":"an institution needs people, so the word shifted from the building to the chapter that runs its daily worship.","whyCN":"机构需要人来运转，因此这个词从建筑转指主持其日常礼拜的教士团。"},{"no":"06","title":"A grand hall of another kind","titleCN":"比喻：另一类宏伟殿堂","definition":"a very large building devoted to a secular activity, described as if it were a church","definitionCN":"把服务于世俗活动的大型建筑说成像教堂一样宏伟","example":"The old bank is a cathedral of marble, brass and guarded money.","exampleCN":"那家老银行是一座由大理石、黄铜与守护着的金钱构成的殿堂。","why":"the metaphor borrows the cathedral's scale and hush, which is exactly what a grand secular hall wants to project.","whyCN":"这个比喻借用了大教堂的尺度与肃静，而这正是宏伟世俗厅堂想传达的东西。"},{"no":"07","title":"The bishop's chair as authority","titleCN":"主教宝座与权威","definition":"the chair itself, and by extension teaching pronounced with formal authority","definitionCN":"指宝座本身，并引申为以正式权威宣告的教导","example":"The phrase ex cathedra marks a statement made from the bishop's seat.","exampleCN":"ex cathedra 这个说法标记的是从主教座位上作出的宣告。","why":"because the chair was the seat of a teacher, speaking 'from the chair' came to mean speaking with unquestionable authority.","whyCN":"因为座位是教导者的座位，「从座位上」说话就转指以不容置疑的权威说话。"},{"no":"08","title":"A home of choral music","titleCN":"合唱音乐的场所","definition":"a building whose acoustic and choral tradition make it a musical institution","definitionCN":"凭声学条件与合唱传统而成为音乐机构的建筑","example":"The cathedral's evening service is now a concert heard online.","exampleCN":"这座大教堂的晚祷现在成了网上可听的音乐会。","why":"stone naves and daily singing produced a repertory, so the building also names a way of performing.","whyCN":"石砌中殿与每日歌唱孕育出一套曲目，因此这座建筑也代表一种演出方式。"}],"etymology":{"intro":{"en":"Cathedral comes from the Latin name of the bishop's chair, itself a Greek compound meaning 'a seat down'. Dates are approximate.","cn":"cathedral 来自拉丁语中「主教座位」的名称，而那本身是一个意为「向下坐的座位」的希腊语复合词。年代均为约数。"},"items":[{"era":"GREEK HEDRA","en":"Hedra meant a seat, chair or sitting place, and it appears in many Greek compounds for things one sits on.","cn":"hedra 指座位、椅子或坐处，出现在许多表示「可坐之物」的希腊语复合词中。"},{"era":"GREEK KATHEDRA","en":"Adding a prefix meaning 'down' gave kathedra, a seat to sit down on, especially a teacher's chair.","cn":"加上表示「向下」的前缀构成 kathedra，指可以坐下的座位，尤指教师的椅子。"},{"era":"LATIN CATHEDRA","en":"Latin borrowed it as cathedra and used it for a chair, a teacher's throne and, in Christian usage, a bishop's seat.","cn":"拉丁语借作 cathedra，用于椅子、教师讲席，在基督教用法中特指主教的座位。"},{"era":"CHURCH LATIN CATHEDRALIS","en":"The adjective describing a church that held the bishop's chair gave the English noun its meaning.","cn":"描述「设有主教座位之教堂」的形容词，给了英语名词今天的意义。"},{"era":"ENGLISH CATHEDRAL","en":"English borrowed the word in the fourteenth century for the principal church of a diocese.","cn":"英语在十四世纪借入这个词，指一个教区的主要教堂。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the earlier ancestry of Greek hedra is disputed, and any Indo-European form proposed for it is a reconstruction rather than a recorded word.","cn":"来源不确定（更深来源）：希腊语 hedra 的更早谱系有争议，凡为其提出的印欧语形式都是重构形式，而非有记录的词。"}]},"similar":{"note":{"en":"Group one holds church words that look close but rank differently; group two holds sacred buildings that are not defined by a bishop's seat.","cn":"第一组是看起来接近、等级却不同的教堂词；第二组是不以主教座位为定义的宗教建筑。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cathedra","ipa":"/kəˈθiːdrə/","tag":"the chair, not the church","definition":"The bishop's throne itself; a cathedral is named after it but the two words are not interchangeable.","definitionCN":"指主教宝座本身；大教堂因它得名，但两词不能互换。"},{"word":"basilica","ipa":"/bəˈzɪlɪkə/","tag":"rank, not seat","definition":"A church given a papal honour, or an early rectangular hall church; it may or may not also be a cathedral.","definitionCN":"获教宗荣衔的教堂，或早期长方形会堂式教堂；它可能同时是主教座堂，也可能不是。"},{"word":"minster","ipa":"/ˈmɪnstə/","tag":"English title","definition":"An English title for a church of a monastery or a very large parish church; it says nothing about a bishop.","definitionCN":"英语中对修道院教堂或特大堂区教堂的称号，与主教无关。"},{"word":"chapel","ipa":"/ˈtʃæpl/","tag":"small and private","definition":"A small place of worship, often inside a larger building or attached to a private house.","definitionCN":"小型礼拜场所，常位于更大建筑之内或附于私宅。"}]},{"heading":"NEAR MEANING","entries":[{"word":"church","ipa":"/tʃɜːtʃ/","tag":"the general word","definition":"Any building for Christian worship; a cathedral is one kind of church with a specific rank.","definitionCN":"泛指任何基督教礼拜建筑；大教堂是其中具有特定等级的一种。"},{"word":"abbey","ipa":"/ˈæbi/","tag":"monastic house","definition":"A monastery or its church, headed by an abbot or abbess rather than by a bishop.","definitionCN":"修道院或其教堂，由院长而非主教领导。"},{"word":"temple","ipa":"/ˈtempl/","tag":"non-Christian shrine","definition":"A building for worship in many non-Christian traditions; it is not organized around a bishop's seat.","definitionCN":"许多非基督教传统中的礼拜建筑，不以主教座位为核心。"},{"word":"sanctuary","ipa":"/ˈsæŋktʃuəri/","tag":"holy or safe place","definition":"The holiest room of a church, or any place of refuge; it stresses safety rather than rank.","definitionCN":"教堂中最神圣的房间，或任何避难之处；强调安全而非等级。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek halves, the real church ranks and the real fixed phrase.","cn":"正常联想：真实的希腊语构件、真实的教会等级与真实的固定短语。"},"normal":[{"en":"Two halves: 'down' plus 'seat', so a cathedral is named for the seat inside it.","cn":"两部分「向下」加「座位」，因此大教堂是因其中那座座位得名。"},{"en":"The family runs cathedra, cathedral, cathedral city, cathedral choir, ex cathedra.","cn":"同族说法包括 cathedra、cathedral、cathedral city、cathedral choir、ex cathedra。"},{"en":"Fixed phrases mark the building: Gothic cathedral, cathedral spire, cathedral nave.","cn":"固定搭配标出建筑本身：哥特式大教堂、大教堂尖塔、大教堂中殿。"},{"en":"Rank matters: a cathedral has a bishop, a basilica has a papal honour, an abbey has an abbot.","cn":"等级很关键：大教堂有主教，宗座圣殿有教宗荣衔，修道院教堂有院长。"},{"en":"The phrase ex cathedra survives as a warning that someone is speaking as if from a throne.","cn":"ex cathedra 这个说法留存至今，用来提醒某人说话像从宝座上发令。"}],"abstract":[{"en":"Picture a single empty chair that a whole town is built around.","cn":"想象一座空椅子，整座城镇都围着它建造。"},{"en":"Picture a room so tall that sound needs several seconds to come back to the speaker.","cn":"想象一间高到声音要好几秒才回到说话者耳中的屋子。"},{"en":"Picture a bank vault designed to feel like a church, with marble instead of hymns.","cn":"想象一座故意造得像教堂的金库，用大理石代替赞美诗。"}]},"examples":[{"en":"The cathedral's spire is visible from the far side of the valley.","cn":"从山谷对面就能看见大教堂的尖塔。"},{"en":"Repairs closed the cathedral for two winters.","cn":"修缮工程让这座主教座堂关闭了两个冬天。"},{"en":"The city grew rich around its cathedral and its pilgrims.","cn":"这座城市因主教座堂与朝圣者而日渐富庶。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"cathedra（座位）→ 主教的座位所在之堂 → 主教座堂、大教堂","word":"cathedral"},"root":"拉丁 cathedra「座位、讲席」来自希腊 kathedra「可坐下的座位」= kata-（向下）+ hedra「座位」；英语 cathedral。hedra 的更早来源不确定。","sensesIntro":{"en":"Eight senses follow one object: a chair. The building is named for it, then grows into a type, an administration, a clergy body, a metaphor and a musical institution.","cn":"八个义项围绕同一件东西展开：一把椅子。建筑因它得名，随后长成一个类型、一套行政、一个教士团体、一个比喻与一个音乐机构。"},"semanticMap":{"core":{"en":"CORE IMAGE: one elevated chair in the middle of a choir, and a whole stone building arranged around that chair.","cn":"核心意象：唱诗席中央的一把高座，整座石造建筑都围绕着那把椅子排布。"},"chain":["A SEAT","A CHURCH","A DIOCESE","A BUILDING TYPE","A CLERGY BODY","A GRAND HALL"],"branches":[{"senses":"义项 01","en":"THE CHAIR: the first sense is simply the church that holds the bishop's seat.","cn":"座位：第一个义项就是安置主教座位的那座教堂。"},{"senses":"义项 02 · 03","en":"SCALE AND TYPE: size makes the word popular, and medieval engineering makes it a building type.","cn":"体量与类型：体量让这个词进入日常，中世纪的工程又使它成为一个建筑类型。"},{"senses":"义项 04 · 05","en":"ADMINISTRATION AND PEOPLE: the seat governs a diocese and supports a chapter.","cn":"行政与人：座位管理一个教区，也供养一个教士团。"},{"senses":"义项 06 · 07","en":"AUTHORITY: the building's scale becomes a metaphor, and the chair becomes a claim to unquestionable teaching.","cn":"权威：建筑的尺度变成比喻，而座位变成对不容置疑教导的宣称。"},{"senses":"义项 08","en":"SOUND: stone and daily singing turn the building into a musical institution.","cn":"声音：石头与每日歌唱把这座建筑变成一个音乐机构。"}]},"affixes":{"intro":{"en":"Cathedral is a Greek compound filtered through Latin church usage, and both halves still appear in English words.","cn":"cathedral 是一个经拉丁教会用法过滤的希腊语复合词，两个构件仍出现在英语词中。"},"latinIntro":{"en":"Latin cathedra and the church adjective cathedralis are the direct sources; Greek supplied the two halves.","cn":"拉丁语 cathedra 与教会形容词 cathedralis 是直接来源，希腊语提供了两个构件。"},"items":[{"word":"kata-","structure":"kata- (Greek prefix, 'down, downward')","meaning":"down; downward","meaningCN":"向下","example":"The prefix pictures the act of sitting down.","exampleCN":"这个前缀描绘「坐下去」的动作。"},{"word":"hedra","structure":"hedra (Greek noun, 'seat, base')","meaning":"seat; base","meaningCN":"座位；基座","example":"The second half names the seat itself.","exampleCN":"后半部分点明座位本身。"},{"word":"kathedra","structure":"kathedra (Greek noun, 'seat, chair')","meaning":"a seat, especially a teacher's chair","meaningCN":"座位，尤指教师的椅子","example":"A teacher spoke from a kathedra.","exampleCN":"教师从讲席上讲话。"},{"word":"cathedra","structure":"cathedra, cathedrae (Latin noun, first declension)","meaning":"chair; bishop's throne","meaningCN":"椅子；主教宝座","example":"The bishop's cathedra stood behind the altar.","exampleCN":"主教的宝座立在祭坛之后。"},{"word":"cathedral","structure":"cathedralis (church Latin adjective) used as a noun","meaning":"the church containing the bishop's chair","meaningCN":"设有主教座位的教堂","example":"The cathedral was rebuilt after the fire.","exampleCN":"大火之后，这座主教座堂被重建。"},{"word":"ex cathedra","structure":"ex ('from') + cathedra ('the chair')","meaning":"with formal, unquestionable authority","meaningCN":"以正式而不容置疑的权威","example":"He spoke ex cathedra on the budget.","exampleCN":"他就预算问题以权威口吻发话。"},{"word":"cathedral city","structure":"cathedral + city (English compound)","meaning":"a city that has a cathedral","meaningCN":"设有主教座堂的城市","example":"The railway bypassed the cathedral city.","exampleCN":"铁路绕过了这座有主教座堂的城市。"},{"word":"cathedral choir","structure":"cathedral + choir (English compound)","meaning":"the choir attached to a cathedral","meaningCN":"附属于主教座堂的唱诗班","example":"The cathedral choir sings evensong daily.","exampleCN":"座堂唱诗班每天唱晚祷。"}],"latinEntries":[{"word":"cathedra","structure":"cathedra, cathedrae (f., first declension; from Greek)","meaning":"chair, teacher's seat, bishop's throne","meaningCN":"椅子；讲席；主教宝座"},{"word":"cathedralis","structure":"cathedralis, cathedrale (adj., church Latin)","meaning":"of a bishop's seat","meaningCN":"主教座位的"}]}},{"word":"basilica","ipa_uk":"/bəˈzɪlɪkə/","ipa_us":"/bəˈzɪlɪkə/","definition_zh":"巴西利卡；古罗马长方形会堂；早期基督教长方形教堂；天主教宗座圣殿","definition_en":"a long rectangular hall used in ancient Rome for public business, later the standard plan of early Christian churches, or a church holding a papal honour","core_image":"一条长长的中殿通向半圆后殿，两侧各有一道侧廊，人流从中间穿过","scene":"石阶通向一座长厅，中央宽道一直通到半圆形的后殿。The basilica in the forum once held law courts and market stalls under one roof.","sceneCN":"这里 basilica 指「古罗马用于公共事务的长方形会堂」（第 1 个义项：古罗马公共会堂）；句意为广场上那座巴西利卡曾在同一屋顶下容纳法庭与市集摊位。图中可辨识物件：长厅、中央宽道、半圆后殿、石阶。","pos":[{"tag":"n.","zh":"巴西利卡；长方形会堂式教堂"},{"tag":"n.","zh":"宗座圣殿（天主教荣衔）"}],"collocations":[{"phrase":"papal basilica","zh":"教宗圣殿"},{"phrase":"major basilica","zh":"特级宗座圣殿"},{"phrase":"basilica plan","zh":"巴西利卡式平面"},{"phrase":"early Christian basilica","zh":"早期基督教巴西利卡"},{"phrase":"the nave of the basilica","zh":"巴西利卡的中殿"},{"phrase":"minor basilica","zh":"次级宗座圣殿"}],"forms":[{"label":"单数形式","form":"basilica"},{"label":"复数形式","form":"basilicas"},{"label":"拉丁复数","form":"basilicae"},{"label":"所有格","form":"basilica's"},{"label":"相关形容词","form":"basilican"}],"derivatives":[{"word":"basilican","pos":"adj.","zh":"巴西利卡式的"},{"word":"basilical","pos":"adj.","zh":"与巴西利卡相关的"},{"word":"basilica plan","pos":"n.","zh":"巴西利卡式平面布局"},{"word":"minor basilica","pos":"n.","zh":"次级宗座圣殿"},{"word":"archbasilica","pos":"n.","zh":"总主教座堂级圣殿"}],"senses":[{"no":"01","title":"A Roman public hall","titleCN":"古罗马公共会堂","definition":"a long roofed hall in a Roman forum used for courts, markets and public business","definitionCN":"罗马广场上用于法庭、市集与公共事务的长形有顶大厅","example":"The basilica in the forum doubled as a courtroom and a trading floor.","exampleCN":"广场上的巴西利卡同时充当法庭与交易场。","why":"the word first named a civic building, not a church: it was the roofed public space where a city did its business.","whyCN":"这个词最初指市政建筑而非教堂：它是城市办理公共事务的有顶空间。"},{"no":"02","title":"The early Christian church plan","titleCN":"早期基督教教堂形制","definition":"a church built on the Roman hall plan, with a wide nave, side aisles and a semicircular apse","definitionCN":"沿用罗马会堂平面的教堂，有宽中殿、侧廊与半圆后殿","example":"The first basilica on the site had a wooden roof and no dome.","exampleCN":"此地最早的巴西利卡式教堂是木顶，没有穹顶。","why":"early Christians adopted the hall because it held a crowd and let the whole assembly face one end.","whyCN":"早期基督徒采用这种会堂，因为它能容纳人群，并让全体会众朝向同一端。"},{"no":"03","title":"A papal honour","titleCN":"天主教宗座圣殿荣衔","definition":"a church granted special status by the pope, ranked as major or minor","definitionCN":"由教宗授予特殊地位的教堂，分特级与次级","example":"The parish was raised to the rank of minor basilica last year.","exampleCN":"这座堂区教堂去年被升格为次级宗座圣殿。","why":"the title no longer describes the shape, only the privilege, so an ordinary-looking church can be a basilica.","whyCN":"这个称号不再描述形状，只表示特权，因此外观普通的教堂也可以是宗座圣殿。"},{"no":"04","title":"A Byzantine hall church","titleCN":"拜占庭式长厅教堂","definition":"the long hall church form used in Byzantine lands, often vaulted and colonnaded","definitionCN":"拜占庭地区常用的长厅式教堂，常带拱顶与列柱","example":"The basilica in the old quarter is roofed with brick vaults.","exampleCN":"老城区那座巴西利卡式教堂以砖拱为顶。","why":"the eastern church kept the hall plan but replaced timber with masonry, giving the type a second architectural life.","whyCN":"东方教会保留长厅平面却以砖石代替木料，使这一类型获得第二次建筑生命。"},{"no":"05","title":"The hall plan itself","titleCN":"巴西利卡式平面","definition":"the layout of a central wide nave flanked by narrower aisles and closed by an apse","definitionCN":"中央宽中殿、两侧较窄侧廊、末端以半圆后殿收束的布局","example":"The architect kept the basilica plan but opened the roof to the sky.","exampleCN":"建筑师保留了巴西利卡式平面，却把屋顶向天空敞开。","why":"once the plan became a pattern, the word could name a layout independent of any building's use.","whyCN":"一旦平面成为范式，这个词就能指一种独立于用途的布局。"},{"no":"06","title":"A privileged place of pilgrimage","titleCN":"享有特权的朝圣之所","definition":"a church with indulgences and privileges that make it a pilgrimage destination","definitionCN":"带有赦罪与特权、因而成为朝圣目的地的教堂","example":"Pilgrims queue at the basilica door on the feast day.","exampleCN":"节日当天朝圣者在圣殿门口排队。","why":"honorary rank brings concrete privileges, and privileges bring crowds, so rank and pilgrimage belong together.","whyCN":"荣衔带来实际特权，特权带来人群，因此等级与朝圣总是相连。"},{"no":"07","title":"A modern hall in the old shape","titleCN":"现代仿巴西利卡式大厅","definition":"a modern civic or exhibition hall built with a long nave and aisles for ceremonial effect","definitionCN":"为营造仪式感而建成长中殿加侧廊的现代市政或展览大厅","example":"The railway station borrows the basilica form for its main concourse.","exampleCN":"火车站的主大厅借用了巴西利卡的形式。","why":"the plan still reads as dignified and communal, so modern builders reuse it without any religious purpose.","whyCN":"这种平面至今仍显得庄重而有公共感，因此现代建造者在毫无宗教用途时也复用。"},{"no":"08","title":"A category in archaeology","titleCN":"考古与建筑史的分类","definition":"a type label used to sort Roman civic halls and early church buildings in excavation reports","definitionCN":"发掘报告中用来为罗马市政会堂与早期教堂分类的类型标签","example":"The excavation report lists three basilicas under the modern square.","exampleCN":"发掘报告列出今日广场之下的三座巴西利卡。","why":"classification is where a building word becomes a tool for reading a site's history.","whyCN":"正是在分类之中，一个建筑词变成解读遗址历史的工具。"}],"etymology":{"intro":{"en":"Basilica is a Greek adjective used as a noun in Latin, meaning 'royal hall', and it moved from civic architecture to church architecture. Dates are approximate.","cn":"basilica 本是一个希腊语形容词，在拉丁语中作名词使用，意为「王者之厅」，并从市政建筑移入教堂建筑。年代均为约数。"},"items":[{"era":"GREEK BASILEUS","en":"Basileus meant king or sovereign, and its adjective basilikos meant royal or kingly.","cn":"basileus 指国王或君主，其形容词 basilikos 意为王的、王者般的。"},{"era":"GREEK BASILIKE STOA","en":"The phrase for the royal portico, a covered colonnade in the Athenian agora, was shortened into a single noun.","cn":"指「王者柱廊」的短语，即雅典集市中的有顶柱廊，后来缩略为一个名词。"},{"era":"LATIN BASILICA","en":"Latin took the word for a large public hall, used for courts and commerce, without any sacred meaning.","cn":"拉丁语用这个词指大型公共会堂，供法庭与商业使用，并无神圣含义。"},{"era":"CHRISTIAN ADOPTION","en":"From the fourth century Christians built their main churches on the hall plan and kept the old name.","cn":"从四世纪起，基督徒按会堂平面建造主要教堂，并沿用了旧名。"},{"era":"PAPAL TITLE","en":"In later canon law the word became an honorary rank conferred by the pope on selected churches.","cn":"在后来的教会法中，这个词成为教宗授予特定教堂的荣誉等级。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Greek ancestry of basileus is not established, and the usual suggestion of a loan from an older Aegean language remains a hypothesis.","cn":"来源不确定（更深来源）：basileus 在希腊语之前的谱系未得到证明，通常认为它借自更早的爱琴海语言，那仍只是假说。"}]},"similar":{"note":{"en":"Group one holds building words built on the same royal root or easily confused with the rank; group two holds church types defined another way.","cn":"第一组是同出「王者」词根或容易与这一等级混淆的建筑词；第二组是以其他方式定义的教堂类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"basileus","ipa":"/bəˈsɪləs/","tag":"the king himself","definition":"The Greek word for king that stands behind basilica, but it never names a building.","definitionCN":"巴西利卡背后的希腊语「国王」一词，但它从不指建筑。"},{"word":"basilican","ipa":"/bəˈsɪlɪkən/","tag":"adjective form","definition":"Describing the long hall form; the adjective says nothing about papal rank.","definitionCN":"描述长厅形制的形容词，与教宗授予的等级无关。"},{"word":"cathedral","ipa":"/kəˈθiːdrəl/","tag":"different rank","definition":"The bishop's church; a basilica is defined by a papal honour, so a building may be one, the other, or both.","definitionCN":"主教座堂以主教座位定义，而巴西利卡以教宗荣衔定义，同一建筑可以居其一或兼有。"},{"word":"basil","ipa":"/ˈbæzɪl/","tag":"unrelated plant","definition":"The herb is from Greek basileus too, but through a different word for a royal plant; it has no link to buildings.","definitionCN":"这种香草也源于希腊语「王」，但走的是「王者之草」另一条词线，与建筑无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nave","ipa":"/neɪv/","tag":"the central lane","definition":"The long central space of a church; it is one part of a basilica, not the whole building.","definitionCN":"教堂中央的长空间，是巴西利卡的一部分，而非整座建筑。"},{"word":"aisle","ipa":"/aɪl/","tag":"the side lane","definition":"A narrow passage beside the nave; basilicas are defined by having them, but an aisle is not a building.","definitionCN":"中殿旁的窄通道；巴西利卡以拥有侧廊为特征，但侧廊本身不是建筑。"},{"word":"hall church","ipa":"/hɔːl tʃɜːtʃ/","tag":"flat-roofed type","definition":"A church whose nave and aisles are of equal height; it contrasts with the taller nave of a basilica.","definitionCN":"中殿与侧廊等高的教堂，与中殿更高的巴西利卡形成对照。"},{"word":"sanctuary","ipa":"/ˈsæŋktʃuəri/","tag":"holy area","definition":"The most sacred part of a church; the word concerns holiness, not plan or rank.","definitionCN":"教堂中最神圣的部分；这个词关乎神圣性，而非平面或等级。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real royal root, the real plan words and the real papal rank.","cn":"正常联想：真实的「王者」词根、真实的平面术语与真实的教宗等级。"},"normal":[{"en":"The word began as 'royal hall' and only later meant a church.","cn":"这个词最初是「王者之厅」，后来才指教堂。"},{"en":"The family runs basilica, basilican, basilical, basilica plan, archbasilica.","cn":"同族说法包括 basilica、basilican、basilical、basilica plan、archbasilica。"},{"en":"Fixed phrases mark the rank: major basilica, minor basilica, papal basilica.","cn":"固定搭配标出等级：特级宗座圣殿、次级宗座圣殿、教宗圣殿。"},{"en":"The plan has three parts: a wide nave, narrow aisles, and a rounded apse at the end.","cn":"这种平面分三段：宽中殿、窄侧廊、末端的半圆后殿。"},{"en":"A basilica may also be a cathedral, but neither word implies the other.","cn":"巴西利卡也可能同时是主教座堂，但两个词互不蕴含。"}],"abstract":[{"en":"Picture a king's covered walkway emptied of the king and filled with merchants.","cn":"想象一条属于国王的有顶长廊，国王走了，商人挤了进来。"},{"en":"Picture a single long room that can be a court in the morning and a church at night.","cn":"想象一间长屋，上午是法庭，晚上是教堂。"},{"en":"Picture a modern hall that keeps the old aisle rhythm but sells tickets at the door.","cn":"想象一座现代大厅保留旧时的侧廊节奏，却在门口卖票。"}]},"examples":[{"en":"The Roman basilica had no religious function at all.","cn":"古罗马的巴西利卡完全没有宗教功能。"},{"en":"The basilica's apse still holds its original mosaic.","cn":"这座巴西利卡的后殿仍保有原来的镶嵌画。"},{"en":"The pope raised the shrine to the rank of minor basilica.","cn":"教宗把这处圣地升格为次级宗座圣殿。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"basileus（王）+ ica（……的）→ 王者之厅 → 罗马会堂 → 长方形教堂、宗座圣殿","word":"basilica"},"root":"希腊 basilikē「王者柱廊」来自 basileus「王」+ basilikos「王的」；拉丁 basilica 指公共会堂，后为教堂形制与教宗荣衔。英语 basilica。basileus 更深来源不确定，一般认为是借词。","sensesIntro":{"en":"Eight senses follow one long room: a royal hall becomes a civic hall, then a church plan, then a rank, then a layout, a pilgrimage site, a modern hall and a dig-site label.","cn":"八个义项沿一间长屋展开：王者之厅成为公共会堂，再成为教堂形制、荣誉等级、平面布局、朝圣地、现代大厅，最后成为遗址标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: one long roofed lane with side lanes, ending in a rounded niche.","cn":"核心意象：一条有顶的长廊，两侧各有窄道，末端收进一个半圆凹室。"},"chain":["A ROYAL HALL","A CIVIC HALL","A CHURCH PLAN","A PAPAL RANK","A PILGRIM SITE","A TYPE LABEL"],"branches":[{"senses":"义项 01","en":"THE HALL: the first sense is the Roman civic building where courts and trade shared a roof.","cn":"会堂：第一个义项是法庭与交易共用一顶屋顶的罗马市政建筑。"},{"senses":"义项 02 · 04","en":"THE CHURCH PLAN: western timber roofs and eastern masonry vaults both kept the long hall.","cn":"教堂平面：西方木顶与东方砖拱都保留了这间长厅。"},{"senses":"义项 03 · 06","en":"THE HONOUR: papal rank replaces shape, and privilege turns the church into a destination.","cn":"荣衔：教宗授予的等级取代了形状，特权又把教堂变成目的地。"},{"senses":"义项 05 · 07","en":"THE PATTERN: the layout outlives its uses and returns in secular halls.","cn":"范式：布局比用途活得更久，并在世俗大厅中回归。"},{"senses":"义项 08","en":"THE LABEL: archaeology turns the building word into a sorting tool.","cn":"标签：考古学把这个建筑词变成分类工具。"}]},"affixes":{"intro":{"en":"Basilica is a Greek royal adjective that Latin turned into a building noun, so its parts explain both the throne and the hall.","cn":"basilica 是一个希腊语「王者」形容词，被拉丁语转为建筑名词，其构件同时解释了王座与厅堂。"},"latinIntro":{"en":"Greek basileus and basilikos passed into Latin as the building name basilica; the church adjective basilicanus followed.","cn":"希腊语 basileus 与 basilikos 经拉丁语形成建筑名 basilica，随后又有教会形容词 basilicanus。"},"items":[{"word":"basileus","structure":"basileus (Greek noun, 'king')","meaning":"king; sovereign","meaningCN":"国王；君主","example":"The root names a king, not a building.","exampleCN":"这个词根指的是国王，而非建筑。"},{"word":"basilikos","structure":"basileus + -ikos (belonging to)","meaning":"royal; kingly","meaningCN":"王的；王者般的","example":"The adjective turned a hall into a royal hall.","exampleCN":"这个形容词把一间厅堂变成王者之厅。"},{"word":"basilikē","structure":"basilikē (stoa) (Greek noun phrase, shortened)","meaning":"the royal portico","meaningCN":"王者柱廊","example":"The portico gave the building type its name.","exampleCN":"这条柱廊给了这种建筑类型名称。"},{"word":"basilica","structure":"basilica, basilicae (Latin noun, first declension)","meaning":"a large public hall","meaningCN":"大型公共会堂","example":"A Roman basilica held courts and shops.","exampleCN":"罗马的巴西利卡容纳法庭与商铺。"},{"word":"basilican","structure":"basilica + -an (relating to)","meaning":"of the long hall form","meaningCN":"长厅形制的","example":"The basilican nave runs the full length.","exampleCN":"巴西利卡式中殿贯通全长。"},{"word":"basilical","structure":"basilica + -al (relating to)","meaning":"relating to a basilica","meaningCN":"与巴西利卡相关的","example":"The basilical plan was copied in brick.","exampleCN":"巴西利卡式平面被用砖复制。"},{"word":"basilica plan","structure":"basilica + plan (English compound)","meaning":"the long hall layout","meaningCN":"长厅式布局","example":"The drawing labels the basilica plan.","exampleCN":"图纸标出了巴西利卡式平面。"},{"word":"minor basilica","structure":"minor ('lesser') + basilica","meaning":"a lower rank of papal church","meaningCN":"较低一级的教宗圣殿","example":"The shrine became a minor basilica.","exampleCN":"这处圣地成为次级宗座圣殿。"}],"latinEntries":[{"word":"basilica","structure":"basilica, basilicae (f., first declension; from Greek)","meaning":"public hall; later a church","meaningCN":"公共会堂；后指教堂"},{"word":"basilicanus","structure":"basilicanus, basilicana, basilicanum (adj., church Latin)","meaning":"relating to a basilica","meaningCN":"巴西利卡式的"}]}},{"word":"temple","ipa_uk":"/ˈtempl/","ipa_us":"/ˈtempl/","definition_zh":"神庙；寺庙；圣殿；太阳穴；眼镜腿；（文化）殿堂","definition_en":"a building used for worship in many religions, or the flat side of the forehead above the cheekbone","core_image":"石柱围出一间内殿，门内是神像，门外是台阶；同一张脸上，眉骨外侧的一处凹陷也叫这个名字","scene":"山道尽头是石阶与断柱，海风穿过柱间。The temple stands on the ridge above the harbour, its columns still unbroken.","sceneCN":"这里 temple 指「供奉神明的神庙」（第 1 个义项：古代宗教建筑）；句意为这座神庙立在海港上方的山脊上，柱身至今未断。图中可辨识物件：石阶、断柱、山脊、海港。","pos":[{"tag":"n.","zh":"神庙；寺庙；圣殿"},{"tag":"n.","zh":"太阳穴；眼镜腿"}],"collocations":[{"phrase":"Buddhist temple","zh":"佛寺"},{"phrase":"ancient temple","zh":"古代神庙"},{"phrase":"temple ruins","zh":"神庙遗址"},{"phrase":"the Temple in Jerusalem","zh":"耶路撒冷圣殿"},{"phrase":"temple of art","zh":"艺术殿堂"},{"phrase":"the temple of the head","zh":"太阳穴"}],"forms":[{"label":"单数形式","form":"temple"},{"label":"复数形式","form":"temples"},{"label":"所有格","form":"temple's"},{"label":"相关形容词","form":"temperate (unrelated sense of tempus)"}],"derivatives":[{"word":"temples","pos":"n.","zh":"太阳穴（复数）"},{"word":"temple-like","pos":"adj.","zh":"神庙般的"},{"word":"templed","pos":"adj.","zh":"建有神庙的"},{"word":"contemplate","pos":"v.","zh":"凝视；沉思（同出 templum）"},{"word":"contemplation","pos":"n.","zh":"沉思；凝视"}],"senses":[{"no":"01","title":"A shrine of the old religions","titleCN":"古代宗教神庙","definition":"a building dedicated to a god, especially in Greek, Roman or Egyptian worship","definitionCN":"献给某位神明的建筑，尤见于希腊、罗马或埃及崇拜","example":"The temple walls still carry the names of donors from three centuries.","exampleCN":"神庙墙上仍留着三个世纪以来捐赠者的名字。","why":"the oldest sense is a marked-off sacred precinct, and the building is only its most visible part.","whyCN":"最早的义项是一块被划分出来的神圣地界，建筑只是它最显眼的部分。"},{"no":"02","title":"An East Asian place of worship","titleCN":"东亚的寺庙宫观","definition":"a Buddhist, Taoist or Shinto building used for worship and ritual","definitionCN":"佛教、道教或神道用于礼拜与仪式的建筑","example":"Incense smoke hangs under the temple eaves all afternoon.","exampleCN":"整个下午，香烟都悬在寺庙的檐下。","why":"the word travelled with traders and translators, so it was applied to buildings of religions it never originally named.","whyCN":"这个词随商人与译者旅行，于是被用在它原本从未命名的宗教建筑上。"},{"no":"03","title":"The Temple of Jerusalem","titleCN":"耶路撒冷圣殿","definition":"the central sanctuary of ancient Israel, of which only the western retaining wall survives","definitionCN":"古代以色列的中心圣所，今仅存西侧挡土墙","example":"Pilgrims still pray at the wall of the temple.","exampleCN":"朝圣者仍在圣殿的墙边祈祷。","why":"in this use the word is almost a proper name: one building, one city, one covenant.","whyCN":"在这一用法中，这个词几乎成了专名：一座建筑、一座城、一份盟约。"},{"no":"04","title":"A Latter-day Saint temple","titleCN":"摩门教圣殿","definition":"a building in the Latter-day Saint movement reserved for special ordinances, as distinct from an ordinary meetinghouse","definitionCN":"后期圣徒运动中专供特定仪式的建筑，区别于普通礼拜堂","example":"Only members with recommends enter the temple for ordinances.","exampleCN":"只有持推荐书的成员才能进圣殿参加仪式。","why":"a new religion kept the old word but narrowed it to one kind of building among several.","whyCN":"一个新宗教沿用了旧词，却把它收窄为若干建筑中的一类。"},{"no":"05","title":"The side of the forehead","titleCN":"太阳穴","definition":"the flat area at the side of the forehead above the cheekbone","definitionCN":"额部两侧、颧骨上方的平坦区域","example":"The blow landed on his left temple and blurred his vision.","exampleCN":"那一击打在他左侧太阳穴，令视线发花。","why":"this is a different Latin word, the plural of the time noun, which in the plural named the temples of the head.","whyCN":"这是另一个拉丁词，即「时间」名词的复数形式，其复数专门指头部的太阳穴。"},{"no":"06","title":"The arm of a pair of glasses","titleCN":"眼镜腿","definition":"the part of a spectacle frame that rests against the side of the head","definitionCN":"眼镜架上贴着头部两侧的部分","example":"One temple of the frame was bent after the fall.","exampleCN":"摔倒之后，镜架的一条腿弯了。","why":"eyeglasses are named by the body part they touch, so the anatomical word was transferred to the frame.","whyCN":"眼镜以它所接触的身体部位命名，因此这个解剖词被转用到镜架上。"},{"no":"07","title":"A temple of art or commerce","titleCN":"艺术或商业的殿堂","definition":"a large building devoted to a valued activity, described with religious awe","definitionCN":"把某项受珍视的活动说成带有宗教敬畏的大型建筑","example":"The old library is a temple of quiet and paper.","exampleCN":"那座老图书馆是一座安静与纸张的殿堂。","why":"the metaphor works because both a temple and a great hall set apart a space from ordinary use.","whyCN":"这个比喻成立，因为神庙与宏伟厅堂都把一处空间从日常使用中划分出来。"},{"no":"08","title":"A marked-off piece of sky","titleCN":"古罗马占卜划定的天空区","definition":"in Roman augury, a region of the sky marked out for observing signs","definitionCN":"罗马占卜中为观察征兆而划出的一片天空区域","example":"The augur divided the temple of the sky into quarters.","exampleCN":"占卜官把这片天空的圣域分成四方。","why":"the Latin word began as a space cut off for observation, which is why the building sense and the sky sense share a root.","whyCN":"这个拉丁词最初是为观察而划出的一片空间，因此建筑义与天空义共用同一词根。"}],"etymology":{"intro":{"en":"Two different Latin words lie behind English temple: one means a consecrated space, the other names the temples of the head. Dates are approximate.","cn":"英语 temple 背后有两个不同的拉丁词：一个指被祝圣的空间，另一个指头部的太阳穴。年代均为约数。"},"items":[{"era":"LATIN TEMPLUM","en":"Templum meant a space marked out and consecrated for observation, especially by an augur, and only later a shrine building.","cn":"templum 指划出并祝圣供观察的空间，尤用于占卜，后来才指神庙建筑。"},{"era":"OLD ENGLISH TEMPEL","en":"English borrowed the word early, and it appears in Old English for the Temple of Jerusalem before it named pagan shrines.","cn":"英语很早就借入这个词，古英语中先用于指耶路撒冷圣殿，之后才指异教神庙。"},{"era":"LATIN TEMPORA","en":"The plural of the time noun, tempora, was used for the flat places at either side of the forehead, giving the anatomical sense.","cn":"表示「时间」的名词其复数 tempora 被用来指额头两侧的平坦处，形成解剖义。"},{"era":"TRANSLATION AND MISSIONS","en":"Translators extended the word to Buddhist and Taoist buildings, so English temple now covers many religions.","cn":"译者把这个词扩展到佛教与道教建筑，因此英语 temple 如今涵盖多种宗教。"},{"era":"SPECTACLE FRAME","en":"By the nineteenth century the anatomical word named the side pieces of eyeglasses, which rest against the temples.","cn":"到十九世纪，这个解剖词被用来命名眼镜架两侧贴着太阳穴的部分。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the ancestry of templum before Latin is not established; a link to a verb meaning 'to cut' has been proposed, but competing explanations exist and none is proven.","cn":"来源不确定（更深来源）：templum 在拉丁语之前的谱系未得到证明；有人提出它与表示「切」的动词有关，但存在多种竞争性解释，无一得到证实。"}]},"similar":{"note":{"en":"Group one holds words that look like temple or sit in the same semantic field but differ in root; group two holds other sacred buildings.","cn":"第一组是与 temple 形近或同属语义场、但词根不同的词；第二组是其他宗教建筑。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"templet","ipa":"/ˈtemplɪt/","tag":"pattern piece","definition":"A small pattern or gauge used in building; it comes from the same root as template and has nothing to do with worship.","definitionCN":"建筑中用的小样板或规尺，与 template 同源，与礼拜无关。"},{"word":"temporal","ipa":"/ˈtempərəl/","tag":"time, not forehead","definition":"Relating to time or the material world; it comes from the time noun, which also supplied the plural behind the anatomical sense.","definitionCN":"与时间或世俗世界相关的；来自「时间」名词，该名词的复数又给出了解剖义。"},{"word":"contemplate","ipa":"/kənˈtemplət/","tag":"same root, different verb","definition":"To look at or think about at length; it comes from the Latin verb for observing within a marked-off space.","definitionCN":"长时间注视或思考；来自拉丁语中「在被划出的空间内观察」的动词。"},{"word":"tempo","ipa":"/ˈtempəʊ/","tag":"unrelated borrowing","definition":"The speed of music, from Italian tempo 'time'; it shares the Latin time noun but not the shrine word.","definitionCN":"音乐的速度，来自意大利语「时间」；与拉丁「时间」名词同源，但与神庙词无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"shrine","ipa":"/ʃraɪn/","tag":"holy container","definition":"A place or receptacle holding something holy, often smaller than a temple and centred on a relic.","definitionCN":"存放圣物之处或容器，常比神庙小，并以圣物为中心。"},{"word":"sanctuary","ipa":"/ˈsæŋktʃuəri/","tag":"safe sacred area","definition":"The holiest room of a religious building or a place of refuge; it stresses protection.","definitionCN":"宗教建筑中最神圣的房间或避难处；强调保护。"},{"word":"church","ipa":"/tʃɜːtʃ/","tag":"Christian building","definition":"A building for Christian worship; temple is used for other traditions and for the Jewish sanctuary.","definitionCN":"基督教礼拜建筑；temple 多用于其他传统或犹太圣所。"},{"word":"synagogue","ipa":"/ˈsɪnəɡɒɡ/","tag":"Jewish assembly house","definition":"A Jewish house of prayer and study; the Temple was the single sanctuary, while synagogues are local.","definitionCN":"犹太人的祈祷与研习之所；圣殿是唯一圣所，会堂则是地方性的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real Latin sources, the real translation history and the real glasses term.","cn":"正常联想：两个真实的拉丁语来源、真实的翻译史与真实的眼镜术语。"},"normal":[{"en":"The building sense means a space marked off for a god; the head sense means the flat side of the forehead.","cn":"建筑义指为神划出的空间；头部义指额侧的平坦处。"},{"en":"The family runs temple, temples, temple-like, templed, contemplate, contemplation.","cn":"同族词包括 temple、temples、temple-like、templed、contemplate、contemplation。"},{"en":"Fixed phrases mark the branches: Buddhist temple, temple ruins, the Temple in Jerusalem, temple of art.","cn":"固定搭配标出各分支：佛寺、神庙遗址、耶路撒冷圣殿、艺术殿堂。"},{"en":"The glasses sense is anatomy transferred to an object that touches the same spot.","cn":"眼镜义是把解剖词转用到接触同一部位的物件上。"},{"en":"Roman augury used the word for a patch of sky before it was used for a building.","cn":"罗马占卜先用这个词指一片天空，之后才用于建筑。"}],"abstract":[{"en":"Picture a rope laid on the ground to mark a square of sky as belonging to a god.","cn":"想象一根绳子铺在地上，把一方天空划归某位神明。"},{"en":"Picture a forehead and a temple wall both carrying the same small hollow.","cn":"想象额头与神庙的墙各有一处相同的小凹。"},{"en":"Picture a library so silent that visitors whisper as if at an altar.","cn":"想象一座图书馆静得让访客像在祭坛前一样低语。"}]},"examples":[{"en":"The temple was rebuilt in marble after the earthquake.","cn":"地震之后，这座神庙用大理石重建。"},{"en":"A small temple stands at the top of the stone stair.","cn":"石阶顶端立着一座小寺庙。"},{"en":"The frame's temple snapped where it met the hinge.","cn":"镜架的那条腿在铰链处折断了。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"templum（划出的神圣空间）→ 神庙；同形词又指额侧平坦处 → 太阳穴","word":"temple"},"root":"建筑义来自拉丁 templum「划出并祝圣的空间」，后指神庙；太阳穴义来自拉丁 tempora，即「时间」名词的复数，专指额侧；两源不同。英语 temple。templum 更深来源不确定。","sensesIntro":{"en":"Eight senses follow two paths: a marked-off sacred space becomes a shrine, then a whole class of religious buildings and a metaphor; a separate Latin plural names the forehead, then the glasses arm.","cn":"八个义项分两条线：被划出的神圣空间成为神庙，再扩展为各类宗教建筑与比喻；另一个拉丁复数指额侧，再转指眼镜腿。"},"semanticMap":{"core":{"en":"CORE IMAGE: a boundary drawn around a space, and a hollow at the side of a face that shares the same name.","cn":"核心意象：围绕一处空间画下的界线，以及脸侧一处同名的凹陷。"},"chain":["MARKED SPACE","SACRED BUILDING","MANY RELIGIONS","THE ONE TEMPLE","THE FOREHEAD","THE FRAME ARM"],"branches":[{"senses":"义项 01 · 08","en":"MARKED-OFF SPACE: the shrine and the augur's patch of sky are the same act of setting space apart.","cn":"划出的空间：神庙与占卜官划出的那片天空，是同一个「把空间分开」的动作。"},{"senses":"义项 02 · 04","en":"MANY FAITHS: translation and new religions apply the word to their own buildings.","cn":"多种信仰：翻译与新宗教把这个词用于自己的建筑。"},{"senses":"义项 03","en":"THE UNIQUE SANCTUARY: one building becomes a proper name and a whole covenant.","cn":"唯一的圣所：一座建筑成为专名，也代表一整份盟约。"},{"senses":"义项 05 · 06","en":"THE FOREHEAD: a separate Latin plural names the head, and glasses borrow it.","cn":"额侧：另一个拉丁复数指头部，眼镜又把它借去。"},{"senses":"义项 07","en":"THE METAPHOR: any revered place can be called a temple of its own craft.","cn":"比喻：任何受敬重的地方都可称为其本行的殿堂。"}]},"affixes":{"intro":{"en":"Temple is two words in one shape: a Latin sacred-space noun and a Latin plural for the sides of the head, so the affix list follows both.","cn":"temple 是一个词形下的两个词：一个拉丁语「神圣空间」名词与一个指头侧的拉丁语复数，因此词缀清单两条线都跟。"},"latinIntro":{"en":"Latin templum gave the shrine family, and the plural tempora gave the anatomical family; the verb contemplari grew from templum.","cn":"拉丁语 templum 给出神庙一族，复数 tempora 给出解剖一族；动词 contemplari 由 templum 生长出来。"},"items":[{"word":"templum","structure":"templum, templi (Latin noun, second declension)","meaning":"consecrated space; shrine","meaningCN":"祝圣的空间；神庙","example":"The augur observed within the templum.","exampleCN":"占卜官在划定的圣域内观察。"},{"word":"temple","structure":"templum through Old English tempel","meaning":"a building for worship","meaningCN":"礼拜建筑","example":"The temple stood above the harbour.","exampleCN":"神庙立在海港上方。"},{"word":"temple (head)","structure":"tempora, plural of tempus (Latin)","meaning":"the flat side of the forehead","meaningCN":"额侧的平坦处","example":"A pulse beat at his temple.","exampleCN":"他的太阳穴处有脉搏跳动。"},{"word":"temples","structure":"temple + plural -s","meaning":"both sides of the forehead","meaningCN":"头部两侧的太阳穴","example":"The headache sat behind both temples.","exampleCN":"头痛压在两侧太阳穴后面。"},{"word":"contemplari","structure":"contemplari (Latin verb, first conjugation)","meaning":"to observe, gaze at, consider","meaningCN":"观察；凝视；思量","example":"The verb began as watching the sky.","exampleCN":"这个动词最初指观察天空。"},{"word":"contemplate","structure":"contemplari through French contempler","meaning":"to look at or think about deeply","meaningCN":"深深注视或思考","example":"She contemplated the empty altar.","exampleCN":"她凝视着空祭坛。"},{"word":"contemplation","structure":"contemplate + -ion (act or state)","meaning":"deep thought or gazing","meaningCN":"沉思；凝视","example":"Contemplation needs silence.","exampleCN":"沉思需要安静。"},{"word":"temple-like","structure":"temple + -like (resembling)","meaning":"resembling a temple","meaningCN":"神庙般的","example":"The reading room has a temple-like calm.","exampleCN":"这间阅览室有一种神庙般的宁静。"}],"latinEntries":[{"word":"templum","structure":"templum, templi (n., second declension)","meaning":"consecrated space, shrine","meaningCN":"祝圣空间；神庙"},{"word":"tempus","structure":"tempus, temporis (n., third declension); plural tempora","meaning":"time; in the plural, the temples of the head","meaningCN":"时间；复数指头部太阳穴"},{"word":"contemplari","structure":"contemplari, contemplatus sum (verb, first conjugation)","meaning":"to observe, consider","meaningCN":"观察；思量"}]}},{"word":"sanctuary","ipa_uk":"/ˈsæŋktʃuəri/","ipa_us":"/ˈsæŋktʃueri/","definition_zh":"圣所；至圣所；避难所；野生动物保护区；庇护地位","definition_en":"the holiest part of a religious building, or a place where a person, animal or community is protected from harm","core_image":"一道厚重的门帘后面是空无一物的内室，门外的人只能停在台阶上","scene":"战火逼近时，修道院的大门向逃难的人敞开。The old abbey became a sanctuary for families who had lost their homes.","sceneCN":"这里 sanctuary 指「使人免受伤害的庇护之所」（第 2 个义项：避难所）；句意为那座古老修道院成了失去家园的家庭的避难所。图中可辨识物件：修道院大门、门帘、台阶、逃难者的行囊。","pos":[{"tag":"n.","zh":"圣所；至圣所"},{"tag":"n.","zh":"避难所；庇护；保护区"}],"collocations":[{"phrase":"wildlife sanctuary","zh":"野生动物保护区"},{"phrase":"seek sanctuary","zh":"寻求庇护"},{"phrase":"take sanctuary in","zh":"在……中避难"},{"phrase":"sanctuary city","zh":"庇护城市"},{"phrase":"the inner sanctuary","zh":"至圣所；内殿"},{"phrase":"right of sanctuary","zh":"教堂庇护权"}],"forms":[{"label":"单数形式","form":"sanctuary"},{"label":"复数形式","form":"sanctuaries"},{"label":"所有格","form":"sanctuary's"},{"label":"相关动词","form":"sanctify"},{"label":"相关名词","form":"sanctity"}],"derivatives":[{"word":"sanctify","pos":"v.","zh":"使神圣；祝圣"},{"word":"sanctity","pos":"n.","zh":"神圣；圣洁"},{"word":"sanctimonious","pos":"adj.","zh":"假装虔诚的"},{"word":"sanctification","pos":"n.","zh":"圣化；祝圣"},{"word":"sanctuarize","pos":"v.","zh":"使成为庇护所（罕用）"}],"senses":[{"no":"01","title":"The holiest inner room","titleCN":"至圣所；内殿","definition":"the most sacred room of a temple or church, often separated by a screen or curtain","definitionCN":"神庙或教堂中最神圣的房间，常以屏风或门帘隔开","example":"Only the high priest entered the inner sanctuary once a year.","exampleCN":"只有大祭司每年进入至圣所一次。","why":"the word comes from the Latin for 'holy place', so its first sense is the room set apart as most holy.","whyCN":"这个词来自拉丁语「神圣之地」，因此第一个义项就是被分别出来、最为神圣的房间。"},{"no":"02","title":"A place of refuge","titleCN":"避难所","definition":"a place where a person in danger can stay safe from pursuit or violence","definitionCN":"身处危险者可在此免受追捕或暴力侵害的地方","example":"The villagers gave the refugees sanctuary for the winter.","exampleCN":"村民让难民在那里避难过冬。","why":"a holy place was physically inviolable, so protection from harm became the word's everyday sense.","whyCN":"神圣之地在实体上不可侵犯，因此「免受伤害」成为这个词的日常义。"},{"no":"03","title":"A protected area for wildlife","titleCN":"野生动物保护区","definition":"an area where hunting and development are restricted so that animals can breed","definitionCN":"限制狩猎与开发、使动物得以繁殖的区域","example":"The marsh was declared a sanctuary for nesting birds.","exampleCN":"这片沼泽被宣布为筑巢鸟类的保护区。","why":"the idea of a space where harm is forbidden transfers easily from people to animals.","whyCN":"「禁止伤害」的空间这一观念，从人身上转到动物身上十分自然。"},{"no":"04","title":"The medieval right of sanctuary","titleCN":"中世纪教堂庇护权","definition":"the legal privilege by which a fugitive who reached a church could not be seized for a set period","definitionCN":"逃犯抵达教堂后在一定期限内不得被逮捕的法律特权","example":"He claimed the right of sanctuary and stayed forty days.","exampleCN":"他援引教堂庇护权，留了四十天。","why":"the church's immunity was a real legal rule, so the word named a procedure, not only a feeling of safety.","whyCN":"教会的不可侵犯性曾是真实的法律规则，因此这个词指一套程序，而不只是一种安全感。"},{"no":"05","title":"A quiet place for the mind","titleCN":"心灵的安宁之处","definition":"a place or activity that gives relief from pressure and noise","definitionCN":"使人从压力与喧闹中获得缓解的地方或活动","example":"The garden shed is his sanctuary after a long shift.","exampleCN":"长时间轮班之后，那间园艺小屋是他的避难所。","why":"refuge need not be physical; the word follows the feeling of being shielded.","whyCN":"庇护不必是实体的；这个词跟着「被遮蔽」的感受走。"},{"no":"06","title":"A city that shields migrants","titleCN":"庇护城市","definition":"a city that limits cooperation with immigration enforcement and offers services to undocumented residents","definitionCN":"限制与移民执法合作、并向无证居民提供服务的城市","example":"The city declared itself a sanctuary and refused to hold detainees for federal agents.","exampleCN":"该市宣布自己是庇护城市，拒绝为联邦人员关押被拘者。","why":"modern politics reused the old legal word for a municipal policy of non-cooperation.","whyCN":"现代政治把这一古老法律词重新用于市政层面的不合作政策。"},{"no":"07","title":"Inviolable protection","titleCN":"不可侵犯的庇护地位","definition":"the state of being protected from interference by authorities or outsiders","definitionCN":"免受当局或外来者干预的保护状态","example":"The archive claims sanctuary from political pressure.","exampleCN":"该档案馆声称享有免受政治压力干预的庇护。","why":"when the place is abstract, the word names the immunity itself rather than a building.","whyCN":"当地点变得抽象时，这个词指豁免本身，而非某座建筑。"},{"no":"08","title":"The altar area of a church","titleCN":"教堂圣坛区（建筑术语）","definition":"in church architecture, the area around the altar, often raised and separated from the nave","definitionCN":"教堂建筑中祭坛周围、常被抬高并与中殿隔开的区域","example":"The sanctuary step marks where the choir stalls begin.","exampleCN":"圣坛区的台阶标出唱诗席开始的位置。","why":"builders needed a precise word for the holiest zone of the floor plan, so the religious term became a measuring term.","whyCN":"建造者需要一个精确的词来指平面图上的至圣区域，于是宗教词变成量度用词。"}],"etymology":{"intro":{"en":"Sanctuary comes from the Latin noun for a holy place, built on the verb that made things sacred. Dates are approximate.","cn":"sanctuary 来自拉丁语中表示「神圣之地」的名词，其基础是使事物成为神圣的动词。年代均为约数。"},"items":[{"era":"LATIN SACER","en":"Sacer meant sacred or dedicated to a god, and it stood at the centre of Roman religious vocabulary.","cn":"sacer 意为神圣的、献给神的，处于罗马宗教词汇的核心。"},{"era":"LATIN SANCIRE","en":"Sancire meant to make sacred, to ratify or to forbid violation; a law was 'sanctioned' by being made untouchable.","cn":"sancire 意为使神圣、批准或禁止侵犯；一条法律因不可触犯而获得「批准」。"},{"era":"LATIN SANCTUS","en":"The participle sanctus described what had been made holy, and it became the everyday word for a saint.","cn":"分词 sanctus 描述已被视为神圣之物，后来成为指「圣人」的日常词。"},{"era":"LATIN SANCTUARIUM","en":"Sanctuarium named the place where holy things were kept, and in Christian use the holiest part of a church.","cn":"sanctuarium 指存放圣物之处，在基督教用法中指教堂中最神圣的部分。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French saintuaire carried the word into English, where it widened from the holy room to any place of shelter.","cn":"古法语 saintuaire 把这个词带入英语，其义从神圣房间扩展到任何庇护之处。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the link between sacer and sancire is widely accepted in outline but the exact derivation and the pre-Latin ancestry of either word are not settled.","cn":"来源不确定（更深来源）：sacer 与 sancire 之间的联系在轮廓上被广泛接受，但确切派生关系与两词在拉丁语之前的谱系都尚无定论。"}]},"similar":{"note":{"en":"Group one holds words from the same holiness root or easily confused with refuge terms; group two holds other words for protection.","cn":"第一组是同出「神圣」词根或容易与避难类词混淆的词；第二组是其他表示保护的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sanctity","ipa":"/ˈsæŋktəti/","tag":"the quality, not the place","definition":"The state of being holy; it is an abstract quality, while sanctuary is a place or a protected condition.","definitionCN":"指神圣的状态，是抽象属性；而 sanctuary 指地点或受保护的状态。"},{"word":"sanctify","ipa":"/ˈsæŋktɪfaɪ/","tag":"the verb","definition":"To make something holy or set it apart for sacred use; the verb acts, the noun names the result.","definitionCN":"使某物神圣或分别为圣；动词表示动作，名词表示结果。"},{"word":"sanctimonious","ipa":"/ˌsæŋktɪˈməʊniəs/","tag":"false holiness","definition":"Pretending to be morally superior; the word mocks a show of holiness rather than naming a place.","definitionCN":"假装道德高人一等；这个词嘲讽神圣的姿态，而非指地点。"},{"word":"sanctum","ipa":"/ˈsæŋktəm/","tag":"private room","definition":"A private or inviolable room, from the Latin for 'holy thing'; it is smaller and more personal than a sanctuary.","definitionCN":"私密或不可侵犯的房间，来自拉丁语「神圣之物」；比 sanctuary 更小、更私人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"refuge","ipa":"/ˈrefjuːdʒ/","tag":"shelter from danger","definition":"A place or state of safety from danger; it is the plain word, while sanctuary adds a sacred or legal flavour.","definitionCN":"脱离危险的处所或状态；这是朴素说法，sanctuary 则带神圣或法律色彩。"},{"word":"asylum","ipa":"/əˈsaɪləm/","tag":"legal protection","definition":"Protection granted by a state to a foreigner, or an old word for an institution for the mentally ill.","definitionCN":"国家给予外国人的保护，也旧指精神病院。"},{"word":"preserve","ipa":"/prɪˈzɜːv/","tag":"protected land","definition":"An area protected for wildlife or landscape; it is a conservation term without religious overtones.","definitionCN":"为野生动物或景观保护的区域；是保育术语，无宗教意味。"},{"word":"shelter","ipa":"/ˈʃeltə/","tag":"basic cover","definition":"A structure or state giving cover from weather or attack; it makes no claim of inviolability.","definitionCN":"提供遮风避雨或防护的结构或状态，不含不可侵犯之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real holiness root, the real legal history and the real conservation use.","cn":"正常联想：真实的「神圣」词根、真实的法律史与真实的保育用法。"},"normal":[{"en":"The root means 'made sacred', so the place is first untouchable and only then comforting.","cn":"词根意为「被祝圣」，因此这地方先是不可侵犯，然后才令人安心。"},{"en":"The family runs sanctuary, sanctify, sanctity, sanctification, sanctimonious.","cn":"同族词包括 sanctuary、sanctify、sanctity、sanctification、sanctimonious。"},{"en":"Fixed phrases mark the branches: wildlife sanctuary, sanctuary city, right of sanctuary.","cn":"固定搭配标出各分支：野生动物保护区、庇护城市、教堂庇护权。"},{"en":"A church's holiest room and a marsh for nesting birds are both places where harm is forbidden.","cn":"教堂的至圣所与鸟类的筑巢沼泽，都是禁止伤害的地方。"},{"en":"The same word in a floor plan names the raised area around the altar.","cn":"在平面图上，同一个词指祭坛周围被抬高的区域。"}],"abstract":[{"en":"Picture a line on the floor that no pursuer is allowed to cross.","cn":"想象地上画着一条线，追捕者不被允许跨过。"},{"en":"Picture a room with no furniture, only a curtain and a step.","cn":"想象一间没有家具的房间，只有一道门帘与一级台阶。"},{"en":"Picture a garden shed that becomes the smallest possible country.","cn":"想象一间园艺小屋成了最小的国度。"}]},"examples":[{"en":"The hermit built a sanctuary of stone and turf on the island.","cn":"隐修士在岛上用石头与草皮建了一处圣所。"},{"en":"The forest is a sanctuary for the last wild herd.","cn":"这片森林是最后一群野生兽群的保护区。"},{"en":"She found sanctuary in the reading room during the strike.","cn":"罢工期间，她在阅览室里找到了安宁。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"sanct（神圣）+ uary（场所）→ 神圣不可侵犯之处 → 圣所、避难所","word":"sanctuary"},"root":"拉丁 sanctuarium「存放圣物之处」来自 sanctus「神圣的」，其动词 sancire 意为「使神圣、批准、禁止侵犯」；英语 sanctuary。sacer 与 sancire 的确切派生关系不确定。","sensesIntro":{"en":"Eight senses follow one boundary: a room marked off as untouchable becomes a refuge, then a conservation area, a legal privilege, a mental shelter, a city policy, a form of immunity and finally a point on a floor plan.","cn":"八个义项沿同一条界线展开：被划为不可侵犯的房间成为避难所，再成为保护区、法律特权、心灵庇护、城市政策、豁免形式，最后成为平面图上的一点。"},"semanticMap":{"core":{"en":"CORE IMAGE: a threshold that danger is not allowed to cross.","cn":"核心意象：一道危险不得越过的门槛。"},"chain":["HOLY ROOM","UNTOUCHABLE PLACE","REFUGE","PROTECTED LAND","LEGAL IMMUNITY","SAFE FEELING"],"branches":[{"senses":"义项 01 · 08","en":"THE ROOM: the holiest inner space and the altar area are the same sacred zone at different scales.","cn":"房间：至圣所与圣坛区，是同一神圣区域的两个尺度。"},{"senses":"义项 02 · 05","en":"REFUGE: a physical shelter for the body and a quiet place for the mind follow the same feeling of being shielded.","cn":"庇护：身体的庇护所与心灵的安静处，跟随同一种被遮蔽的感受。"},{"senses":"义项 03","en":"PROTECTED LAND: the untouchable zone is applied to animals and their breeding grounds.","cn":"受保护的土地：不可侵犯的区域被用于动物及其繁殖地。"},{"senses":"义项 04 · 07","en":"IMMUNITY: the medieval right and the modern claim both name protection from seizure or pressure.","cn":"豁免：中世纪的庇护权与现代的豁免主张，都指免受抓捕或压力。"},{"senses":"义项 06","en":"POLICY: a city borrows the old word for a modern rule about migrants.","cn":"政策：一座城市借这个旧词表达现代移民规则。"}]},"affixes":{"intro":{"en":"Sanctuary is built from a Latin root for 'sacred' plus a suffix for a place, and that root also builds a whole family of English words.","cn":"sanctuary 由拉丁语「神圣」词根加表示场所的后缀构成，这个词根还构成一整族英语词。"},"latinIntro":{"en":"Latin sacer, sancire and sanctus produced sanctuarium; English later formed sanctify, sanctity and sanctimonious from the same stem.","cn":"拉丁语 sacer、sancire 与 sanctus 产生 sanctuarium；英语后来用同一词干构成 sanctify、sanctity 与 sanctimonious。"},"items":[{"word":"sacer","structure":"sacer, sacra, sacrum (Latin adjective)","meaning":"sacred, dedicated to a god","meaningCN":"神圣的；献给神的","example":"Sacer marked what belonged to the gods.","exampleCN":"sacer 标记属于神明之物。"},{"word":"sancire","structure":"sancire, sanxi, sanctum (Latin verb, fourth conjugation)","meaning":"to make sacred, ratify, forbid violation","meaningCN":"使神圣；批准；禁止侵犯","example":"The law was sancire before it was written.","exampleCN":"这条法律在被写下之前就已受批准。"},{"word":"sanctus","structure":"sanctus, sancta, sanctum (Latin participle used as adjective)","meaning":"holy, consecrated","meaningCN":"神圣的；被祝圣的","example":"Sanctus named a person as well as a place.","exampleCN":"这个词既指人，也指地方。"},{"word":"sanctuarium","structure":"sanctus + -arium (place of)","meaning":"a place for holy things","meaningCN":"存放圣物之处","example":"The sanctuarium held the relics.","exampleCN":"圣所存放着圣物。"},{"word":"sanctuary","structure":"sanctuarium through Old French saintuaire","meaning":"holy place; refuge","meaningCN":"圣所；避难所","example":"The abbey offered sanctuary.","exampleCN":"修道院提供了庇护。"},{"word":"sanctify","structure":"sanctus + -ify (make)","meaning":"to make holy","meaningCN":"使神圣","example":"Ritual sanctifies the ordinary object.","exampleCN":"仪式使寻常物件变得神圣。"},{"word":"sanctity","structure":"sanctus + -ity (quality)","meaning":"holiness","meaningCN":"神圣性","example":"The sanctity of the site is legally protected.","exampleCN":"该地的神圣性受法律保护。"},{"word":"sanctimonious","structure":"sanctimony + -ous (full of)","meaning":"falsely pious","meaningCN":"假装虔诚的","example":"His sanctimonious tone fooled nobody.","exampleCN":"他那假虔诚的腔调骗不了任何人。"}],"latinEntries":[{"word":"sacer","structure":"sacer, sacra, sacrum (adj.)","meaning":"sacred","meaningCN":"神圣的"},{"word":"sancire","structure":"sancire, sanxi, sanctum (v., fourth conjugation)","meaning":"to consecrate, ratify","meaningCN":"祝圣；批准"},{"word":"sanctuarium","structure":"sanctuarium, sanctuarii (n., second declension)","meaning":"place of holy things","meaningCN":"圣物之所"}]}},{"word":"palace","ipa_uk":"/ˈpælɪs/","ipa_us":"/ˈpælɪs/","definition_zh":"宫殿；王宫；主教府；豪华宅邸；大型公共文化建筑","definition_en":"the official residence of a king, queen, bishop or other high dignitary, or any very large and grand building","core_image":"一道正门通向铺石大院，院后是层层抬高的殿堂，每一层都比前一层更不容外人进入","scene":"铁门后是铺石大院，台阶一层层通向正殿。The palace opens its state rooms to visitors only two months a year.","sceneCN":"这里 palace 指「君主或高级显要的官邸」（第 1 个义项：王宫、宫殿）；句意为这座王宫每年只有两个月向访客开放国事厅。图中可辨识物件：铁门、铺石大院、台阶、正殿。","pos":[{"tag":"n.","zh":"宫殿；王宫；官邸"},{"tag":"n.","zh":"豪华大宅；大型公共建筑"}],"collocations":[{"phrase":"royal palace","zh":"王宫"},{"phrase":"archbishop's palace","zh":"大主教府"},{"phrase":"palace gates","zh":"宫门"},{"phrase":"palace of culture","zh":"文化宫"},{"phrase":"the palace officials","zh":"宫廷官员"},{"phrase":"a palace of a hotel","zh":"宫殿般的豪华旅馆"}],"forms":[{"label":"单数形式","form":"palace"},{"label":"复数形式","form":"palaces"},{"label":"所有格","form":"palace's"},{"label":"相关形容词","form":"palatial"}],"derivatives":[{"word":"palatial","pos":"adj.","zh":"宫殿般的；宏伟的"},{"word":"palatinate","pos":"n.","zh":"行宫领地；普法尔茨伯爵领地"},{"word":"palace coup","pos":"n.","zh":"宫廷政变"},{"word":"palace revolution","pos":"n.","zh":"宫廷革命"},{"word":"palazzo","pos":"n.","zh":"意大利式府邸"}],"senses":[{"no":"01","title":"The residence of a ruler","titleCN":"君主的王宫","definition":"the official home and ceremonial centre of a king, queen or emperor","definitionCN":"国王、女王或皇帝的官邸与礼仪中心","example":"The palace balcony faces the wide avenue where crowds gather.","exampleCN":"王宫的阳台朝向人群聚集的宽阔大道。","why":"the word began as the name of one hill in Rome, then of the emperor's house on it, and finally of any ruler's house.","whyCN":"这个词最初是罗马一座山的名字，随后指山上皇帝的宅邸，最后泛指任何君主的宅邸。"},{"no":"02","title":"A bishop's residence","titleCN":"主教府","definition":"the official residence of a bishop or archbishop, often beside the cathedral","definitionCN":"主教或大主教的官邸，常位于主教座堂旁","example":"The archbishop's palace shares a wall with the cathedral garden.","exampleCN":"大主教府与主教座堂的花园共用一道墙。","why":"bishops held princely authority in many periods, so their houses took the same word as a king's.","whyCN":"在许多时期主教握有诸侯般的权柄，因此他们的宅邸与国王用同一个词。"},{"no":"03","title":"A very grand private house","titleCN":"豪华大宅","definition":"a private mansion large and ornate enough to seem royal","definitionCN":"大到与华丽到看上去像王室居所的私人宅邸","example":"The merchant built a palace of brick beside the river.","exampleCN":"那位商人在河边建了一座砖砌豪宅。","why":"wealth copies the forms of power, so a rich man's house borrows the name of a ruler's house.","whyCN":"财富会模仿权力的形式，因此富人的宅邸借用了君主居所的名字。"},{"no":"04","title":"A public palace of culture","titleCN":"文化宫等大型公共建筑","definition":"a large state-built hall for culture, sport or exhibitions, common in former socialist countries","definitionCN":"国家兴建的大型文化、体育或展览场馆，在旧社会主义国家常见","example":"The palace of culture has a theatre, a library and a swimming pool.","exampleCN":"这座文化宫里有剧场、图书馆和游泳池。","why":"the state took the prestige of the palace and gave it to public leisure, so the word became civic.","whyCN":"国家把宫殿的声望转给公共休闲，因此这个词变得市政化。"},{"no":"05","title":"Any lavish place","titleCN":"泛指豪华场所","definition":"a building or room remarkable for comfort, size and expense","definitionCN":"以舒适、宽敞与昂贵著称的建筑或房间","example":"The old cinema was a palace of red velvet and gilded plaster.","exampleCN":"那座老电影院是一座红丝绒与镀金灰泥的宫殿。","why":"the metaphor keeps only the splendour of the original, dropping the ruler entirely.","whyCN":"这个比喻只保留原义的富丽，把君主完全去掉了。"},{"no":"06","title":"The court as a government","titleCN":"宫廷；王室政府","definition":"the ruler's household and advisers, treated as a political actor","definitionCN":"君主的家臣与顾问群体，被当作一个政治行为者","example":"The palace denied that the minister had been dismissed.","exampleCN":"王室方面否认那位大臣已被免职。","why":"reporters say 'the palace' when they mean the household that speaks for the ruler.","whyCN":"记者说「王室」时，指的是替君主发声的那套家臣体系。"},{"no":"07","title":"The Palatine hill in Rome","titleCN":"罗马帕拉蒂尼山上的宫殿","definition":"the imperial residence on the Palatine hill, whose name became the general word","definitionCN":"帕拉蒂尼山上的皇帝居所，其名字成为通名","example":"The ruins of the palace overlook the forum.","exampleCN":"宫殿废墟俯瞰着广场。","why":"one hill's name spread until every ruler's house in Europe carried it.","whyCN":"一座山的名字扩散开来，直到欧洲每位君主的宅邸都带上了它。"},{"no":"08","title":"A movie palace","titleCN":"豪华影院（电影宫）","definition":"a large, lavishly decorated cinema of the early twentieth century","definitionCN":"二十世纪初那种装饰华丽的大型电影院","example":"The movie palace seats two thousand under a painted sky.","exampleCN":"这座电影宫在画出来的天空下可坐两千人。","why":"early cinemas sold an evening of luxury, so they named themselves after the most luxurious building they knew.","whyCN":"早期影院卖的是一晚的奢华，因此用他们所知最奢华的建筑来命名自己。"}],"etymology":{"intro":{"en":"Palace is a place name before it is a building word: the Palatine hill in Rome gave its name to the emperor's house and then to grand houses everywhere. Dates are approximate.","cn":"palace 先是地名，后才是建筑词：罗马的帕拉蒂尼山把名字给了皇帝的宅邸，再给了各地的宏大宅邸。年代均为约数。"},"items":[{"era":"LATIN PALATIUM","en":"Palatium was the name of one of Rome's seven hills, where Augustus and later emperors built their residences.","cn":"Palatium 是罗马七座山之一的名字，奥古斯都及后来的皇帝在此营建居所。"},{"era":"IMPERIAL HOUSE","en":"Because the emperor's house stood on that hill, the hill's name became a word for the house itself.","cn":"由于皇帝的宅邸立在那座山上，山名便成了指宅邸本身的词。"},{"era":"OLD FRENCH PALAIS","en":"Old French palais carried the word into English, where it first named a royal residence.","cn":"古法语 palais 把该词带入英语，最初指王室居所。"},{"era":"BISHOPS AND MERCHANTS","en":"In the Middle Ages the word widened to bishops' houses and then to any exceptionally grand town house.","cn":"中世纪时该词扩展到主教府，再扩展到任何格外宏大的城中宅邸。"},{"era":"CIVIC PALACE","en":"In the twentieth century states built palaces of culture and workers' clubs, giving the word a public meaning.","cn":"二十世纪国家兴建文化宫与工人俱乐部，使这个词带上公共含义。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the origin of the hill name Palatium is disputed; a link to a shepherd god or to a word for a stake has been suggested, but neither is demonstrated.","cn":"来源不确定（更深来源）：山名 Palatium 的来源有争议；有人提出与牧神有关，或与表示「木桩」的词有关，但两者都未得到证实。"}]},"similar":{"note":{"en":"Group one holds words that look like palace or share its grand-house field but differ in origin; group two holds other grand residences.","cn":"第一组是与 palace 形近或同属「宏大宅邸」语义场、但来源不同的词；第二组是其他显赫居所。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"palatial","ipa":"/pəˈleɪʃl/","tag":"adjective form","definition":"Like a palace in size and splendour; it describes a quality and never names a building type.","definitionCN":"在体量与富丽上像宫殿；描述一种性质，从不指建筑类型。"},{"word":"palatinate","ipa":"/pəˈlætɪnət/","tag":"territory, not house","definition":"The domain of a count palatine, an official with royal powers in a border region; it names land and office.","definitionCN":"宫廷伯爵的领地，指在边境地区拥有王权的官员辖区；指土地与职衔。"},{"word":"palazzo","ipa":"/pəˈlætsəʊ/","tag":"Italian borrowing","definition":"An Italian town house of a noble family; English borrowed it for a specific Mediterranean type.","definitionCN":"意大利贵族家族的城中宅邸；英语借来表示一种特定的地中海类型。"},{"word":"palace coup","ipa":"/kuː/","tag":"fixed phrase","definition":"A seizure of power by insiders close to the ruler; the phrase uses palace as the seat of power, not as architecture.","definitionCN":"由君主身边内部人发动的夺权；短语把 palace 当作权力中心，而非建筑。"}]},{"heading":"NEAR MEANING","entries":[{"word":"castle","ipa":"/ˈkɑːsl/","tag":"fortified house","definition":"A fortified residence; it stresses defence, while a palace stresses display and administration.","definitionCN":"设防的居所，强调防御；而 palace 强调展示与治理。"},{"word":"mansion","ipa":"/ˈmænʃn/","tag":"large private house","definition":"A very large private house; it lacks the royal or episcopal rank that palace implies.","definitionCN":"极大型的私人住宅；缺少 palace 所含的王室或主教等级。"},{"word":"residence","ipa":"/ˈrezɪdəns/","tag":"neutral official home","definition":"The neutral word for an official home, used when rank should not be emphasized.","definitionCN":"指官邸的中性词，用于不宜强调等级时。"},{"word":"château","ipa":"/ˈʃætəʊ/","tag":"French country house","definition":"A French country house or estate; it combines castle and country house associations.","definitionCN":"法国的乡间宅邸或庄园，兼有城堡与乡居宅邸的联想。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real hill name, the real rank words and the real compounds.","cn":"正常联想：真实的山名、真实的等级词与真实的复合词。"},"normal":[{"en":"One hill in Rome gave its name to every royal house in Europe.","cn":"罗马的一座山，把名字给了欧洲每一座王室宅邸。"},{"en":"The family runs palace, palatial, palatinate, palazzo, palace coup.","cn":"同族说法包括 palace、palatial、palatinate、palazzo、palace coup。"},{"en":"Fixed phrases mark the branches: royal palace, archbishop's palace, palace of culture.","cn":"固定搭配标出各分支：王宫、大主教府、文化宫。"},{"en":"Rank decides the word: a bishop's house and a king's house can both be palaces.","cn":"等级决定用词：主教的宅邸与国王的宅邸都可以叫 palace。"},{"en":"The movie palace sold luxury by borrowing the most luxurious name available.","cn":"电影宫借用了当时最奢华的名字来售卖奢华。"}],"abstract":[{"en":"Picture a house that has swallowed a whole hill and now wears its name.","cn":"想象一座房子吞下了整座山，并把山名穿在身上。"},{"en":"Picture a private hallway so long that a guest needs a map to reach the dining room.","cn":"想象一条私家长廊，长到客人要拿地图才找得到餐厅。"},{"en":"Picture a cinema whose ceiling is painted as a night sky, so the audience sits outdoors indoors.","cn":"想象一座影院把天花板画成夜空，观众于是在室内坐在户外。"}]},"examples":[{"en":"The palace was opened as a museum after the monarchy ended.","cn":"君主制结束后，这座王宫被改为博物馆开放。"},{"en":"The archbishop's palace dates from the twelfth century.","cn":"大主教府始建于十二世纪。"},{"en":"They restored the movie palace instead of demolishing it.","cn":"他们修复了那座电影宫，而没有将其拆除。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"Palatium（罗马帕拉蒂尼山）→ 山上皇帝宅邸 → 宫殿、豪华宅邸","word":"palace"},"root":"拉丁 Palatium 原为罗马七丘之一的名字，因皇帝宅邸建于其上而转指宫殿；经古法语 palais 入英语。山名本身的来源不确定。英语 palace。","sensesIntro":{"en":"Eight senses follow one address: a ruler's house on a hill becomes a bishop's house, a rich man's house, a public hall, a metaphor, a government, a ruin and a cinema.","cn":"八个义项沿同一个住处展开：山上的君主宅邸成为主教府、富商大宅、公共厅堂、比喻、政府、废墟与影院。"},"semanticMap":{"core":{"en":"CORE IMAGE: gate, courtyard, stair and inner hall, each layer admitting fewer people than the last.","cn":"核心意象：门、院、阶、内殿，每一层允许进入的人都比前一层更少。"},"chain":["A HILL","A RULER'S HOUSE","A DIGNITARY'S HOUSE","A RICH HOUSE","A PUBLIC HALL","A METAPHOR"],"branches":[{"senses":"义项 01 · 07","en":"THE ORIGINAL HOUSE: the hill name became the emperor's residence, and that residence became the general word.","cn":"最初的宅邸：山名成为皇帝居所之名，那座居所又成为通名。"},{"senses":"义项 02","en":"PRINCELY CLERGY: a bishop's house takes the royal word because bishops held princely power.","cn":"诸侯般的主教：主教府沿用王室用词，因为主教握有诸侯般的权力。"},{"senses":"义项 03 · 05","en":"WEALTH COPIES POWER: a merchant's mansion and a lavish hotel borrow palace's splendour without a ruler.","cn":"财富模仿权力：富商豪宅与豪华旅馆借走了 palace 的富丽，却不要君主。"},{"senses":"义项 04 · 08","en":"PUBLIC SPLENDOUR: the state builds palaces of culture, and cinemas call themselves movie palaces.","cn":"公共的富丽：国家兴建文化宫，影院则自称电影宫。"},{"senses":"义项 06","en":"THE HOUSEHOLD: the building's name moves to the people who speak for the ruler.","cn":"家臣体系：建筑之名转到替君主发声的那群人身上。"}]},"affixes":{"intro":{"en":"Palace has no prefix or suffix of its own: it is a place name that became a noun, and its derived words are built on that noun.","cn":"palace 本身没有前缀或后缀：它是一个变成名词的地名，其派生词都建在这个名词上。"},"latinIntro":{"en":"Latin Palatium supplied the name, and the adjective palatinus described what belonged to the imperial hill.","cn":"拉丁语 Palatium 提供了这个名字，形容词 palatinus 描述属于皇帝那座山的事物。"},"items":[{"word":"Palatium","structure":"Palatium (Latin proper noun, the Palatine hill)","meaning":"the Palatine hill in Rome","meaningCN":"罗马的帕拉蒂尼山","example":"Palatium named a place before it named a building.","exampleCN":"这个名字先指地点，后指建筑。"},{"word":"palatinus","structure":"palatinus, palatina, palatinum (Latin adjective)","meaning":"of the Palatine; of the imperial court","meaningCN":"帕拉蒂尼山的；宫廷的","example":"Palatinus described an imperial official.","exampleCN":"这个词描述一位宫廷官员。"},{"word":"palais","structure":"palais (Old French noun)","meaning":"a royal residence","meaningCN":"王室居所","example":"Old French carried the hill's name to a house.","exampleCN":"古法语把山名带到了房子上。"},{"word":"palace","structure":"palais through Middle English","meaning":"a ruler's residence","meaningCN":"君主居所","example":"The palace faces the river.","exampleCN":"王宫面向河流。"},{"word":"palatial","structure":"palace + -ial (relating to)","meaning":"like a palace","meaningCN":"宫殿般的","example":"The flat has a palatial bathroom.","exampleCN":"这套公寓有一间宫殿般的浴室。"},{"word":"palatinate","structure":"palatine + -ate (office or domain)","meaning":"the territory of a count palatine","meaningCN":"宫廷伯爵的领地","example":"The palatinate had its own courts.","exampleCN":"该领地有自己的法庭。"},{"word":"palazzo","structure":"Italian palazzo, from Latin palatium","meaning":"an Italian noble town house","meaningCN":"意大利贵族城中宅邸","example":"The palazzo opens onto a small square.","exampleCN":"这座府邸朝向一个小广场。"},{"word":"palace coup","structure":"palace + coup (English compound)","meaning":"a seizure of power from inside the court","meaningCN":"由宫廷内部发动的夺权","example":"A palace coup removed the old guard.","exampleCN":"一场宫廷政变清除了旧班底。"}],"latinEntries":[{"word":"Palatium","structure":"Palatium (n., proper noun, second declension)","meaning":"the Palatine hill; the imperial residence","meaningCN":"帕拉蒂尼山；皇帝居所"},{"word":"palatinus","structure":"palatinus, palatina, palatinum (adj.)","meaning":"of the Palatine or the court","meaningCN":"帕拉蒂尼山的；宫廷的"}]}},{"word":"fortress","ipa_uk":"/ˈfɔːtrɪs/","ipa_us":"/ˈfɔːrtrɪs/","definition_zh":"要塞；堡垒；设防城市；坚固屏障（比喻）","definition_en":"a heavily fortified place built to resist attack, or something regarded as an unbreakable defence","core_image":"厚墙上只开一道窄门，门前是斜坡与壕沟，墙顶的守军能看见来路每一寸","scene":"山路在壕沟前突然收窄，只剩一道窄门可以进去。The fortress held out for a year while the valley below changed hands twice.","sceneCN":"这里 fortress 指「为抵御进攻而设防的要塞」（第 1 个义项：堡垒、要塞）；句意为这座要塞坚守了一年，其间下方山谷两度易手。图中可辨识物件：厚墙、窄门、壕沟、斜坡。","pos":[{"tag":"n.","zh":"要塞；堡垒；巩固的防御据点"},{"tag":"n.","zh":"（比喻）不可攻破的屏障"}],"collocations":[{"phrase":"mountain fortress","zh":"山地要塞"},{"phrase":"the fortress walls","zh":"要塞城墙"},{"phrase":"fortress Europe","zh":"壁垒森严的欧洲（比喻）"},{"phrase":"hold the fortress","zh":"守住要塞"},{"phrase":"a fortress of solitude","zh":"孤独的堡垒"},{"phrase":"fortress town","zh":"设防城镇"}],"forms":[{"label":"单数形式","form":"fortress"},{"label":"复数形式","form":"fortresses"},{"label":"所有格","form":"fortress's"},{"label":"相关形容词","form":"fortress-like"},{"label":"相关动词","form":"fortify"}],"derivatives":[{"word":"fortify","pos":"v.","zh":"设防；加固"},{"word":"fortification","pos":"n.","zh":"防御工事；筑城"},{"word":"fortified","pos":"adj.","zh":"设防的；加固的"},{"word":"fortitude","pos":"n.","zh":"坚毅；刚强"},{"word":"fortalice","pos":"n.","zh":"小堡垒（古语）"}],"senses":[{"no":"01","title":"A fortified stronghold","titleCN":"设防要塞","definition":"a large fortified place with thick walls, ditches and defensive works","definitionCN":"拥有厚墙、壕沟与防御工事的大型设防之地","example":"The fortress commands the only road through the pass.","exampleCN":"这座要塞控制着穿越山口的唯一道路。","why":"the word comes from a Latin adjective meaning 'strong', so a fortress is simply a place made strong against attack.","whyCN":"这个词来自意为「坚固」的拉丁形容词，因此要塞就是一个被造得能抗攻击的地方。"},{"no":"02","title":"A walled town","titleCN":"设防城镇","definition":"a town whose whole perimeter is enclosed by walls and gates","definitionCN":"整个周边被城墙与城门围住的城镇","example":"The old fortress is still inhabited inside its ring of walls.","exampleCN":"那座旧设防城镇仍有人住在城墙围成的圈内。","why":"when a whole settlement is fortified, the word names the town as much as the walls.","whyCN":"当整个聚落都被设防时，这个词指城镇本身，也指那些墙。"},{"no":"03","title":"A system of permanent works","titleCN":"永备防御工事群","definition":"the whole set of bastions, ramparts and batteries built to hold a position","definitionCN":"为守住阵地而建的棱堡、壁垒与炮台的整体","example":"Engineers surveyed the fortress before adding two new bastions.","exampleCN":"工程师勘测了整片工事，之后加建两座棱堡。","why":"military usage treats the fortress as a system, not a single building.","whyCN":"军事用法把要塞视作一个系统，而非单栋建筑。"},{"no":"04","title":"An unbreakable barrier","titleCN":"比喻：不可攻破的屏障","definition":"something treated as impossible to penetrate or overcome","definitionCN":"被视为无法穿透或攻克的事物","example":"The company built a fortress of patents around its core product.","exampleCN":"这家公司围绕核心产品建起一座专利堡垒。","why":"the metaphor keeps only resistance: a fortress does not need walls to be a fortress.","whyCN":"这个比喻只保留「抵抗」：一座堡垒不必有墙也能是堡垒。"},{"no":"05","title":"A forward military base","titleCN":"前沿军事据点","definition":"a strongly held position at the edge of controlled territory","definitionCN":"位于控制区边缘、被强力据守的阵地","example":"The brigade turned the village into a fortress on the front line.","exampleCN":"该旅把这座村庄变成前线上的一座堡垒。","why":"modern armies reuse the word for any position they intend to hold rather than pass through.","whyCN":"现代军队把这个词用于任何打算守住而非路过的阵地。"},{"no":"06","title":"The inner keep of a castle","titleCN":"城堡的军事核心","definition":"the strongest inner part of a castle, the last place of resistance","definitionCN":"城堡中最坚固的内部，是最后抵抗之处","example":"The outer walls fell, but the fortress in the centre held.","exampleCN":"外墙陷落，但中央的核心堡垒仍在坚守。","why":"a castle can contain a fortress: the word marks the part designed never to fall.","whyCN":"城堡之内可以有一座要塞：这个词标记的是那部分永不打算陷落的结构。"},{"no":"07","title":"An unyielding position","titleCN":"抽象义：寸步不让的立场","definition":"a political or personal stance maintained against all pressure","definitionCN":"在各种压力下都不退让的政治或个人立场","example":"The ministry became a fortress of resistance to the reform.","exampleCN":"该部门成了抵抗这项改革的堡垒。","why":"people defend institutions as they defend walls, so the word describes stubbornness as well as stone.","whyCN":"人捍卫机构如同捍卫城墙，因此这个词既描述石头，也描述固执。"},{"no":"08","title":"A fortress-like structure","titleCN":"要塞式建筑","definition":"a modern building whose massing and small openings make it look defensive","definitionCN":"体量厚重、开窗狭小、看上去带防御性的现代建筑","example":"The new museum is a fortress of concrete with almost no windows.","exampleCN":"新博物馆是一座几乎没有窗的混凝土堡垒。","why":"architects borrow the word when a building's form, not its function, suggests defence.","whyCN":"当建筑的形式而非功能暗示防御时，建筑师便借用了这个词。"}],"etymology":{"intro":{"en":"Fortress comes from a Latin adjective for 'strong' through medieval and Old French forms meaning 'a strong place'. Dates are approximate.","cn":"fortress 来自一个意为「坚固」的拉丁形容词，经中世纪拉丁语与古法语中表示「坚固之地」的形式而来。年代均为约数。"},"items":[{"era":"LATIN FORTIS","en":"Fortis meant strong, mighty or brave, and it described both bodies and buildings.","cn":"fortis 意为坚固的、强大的或勇敢的，既能描述身体也能描述建筑。"},{"era":"LATIN FORTALITIA","en":"Medieval Latin fortalitia named a strong place, formed from the adjective with a suffix for a built thing.","cn":"中世纪拉丁语 fortalitia 指坚固之地，由该形容词加表示建筑物的后缀构成。"},{"era":"OLD FRENCH FORTERESSE","en":"Old French forteresse carried the word into English, where it first meant a fortified town or castle.","cn":"古法语 forteresse 把这个词带入英语，最初指设防城镇或城堡。"},{"era":"BASTIONED WARFARE","en":"From the sixteenth century the word was used for the new low, thick, angular works designed to resist cannon.","cn":"从十六世纪起，这个词用于指为抵御火炮而设计的新式低厚棱角工事。"},{"era":"MODERN METAPHOR","en":"In the twentieth century fortress spread to politics and business, as in fortress Europe or a fortress of patents.","cn":"二十世纪，fortress 扩展到政治与商业，如「壁垒欧洲」或「专利堡垒」。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin ancestry of fortis is not settled, and the Indo-European root commonly proposed for it is a reconstruction only.","cn":"来源不确定（更深来源）：fortis 在拉丁语之前的谱系尚无定论，通常为其提出的印欧语词根只是重构形式。"}]},"similar":{"note":{"en":"Group one holds words from the same strength or fortification stock; group two holds defensive places and buildings.","cn":"第一组同出「坚固」或「筑城」词干的词；第二组是其他防御性地点与建筑。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"fortify","ipa":"/ˈfɔːtɪfaɪ/","tag":"the verb","definition":"To strengthen a place against attack; the verb acts on a site, while the noun names the site itself.","definitionCN":"加固某地以御攻击；动词作用于地点，名词则指该地点本身。"},{"word":"fortitude","ipa":"/ˈfɔːtɪtjuːd/","tag":"strength of mind","definition":"Courage in pain or adversity; it shares the strength root but names a personal quality.","definitionCN":"在痛苦或逆境中的坚毅；同出「坚固」词根，但指个人品质。"},{"word":"fortification","ipa":"/ˌfɔːtɪfɪˈkeɪʃn/","tag":"the works","definition":"The walls and works built to defend a place, or the act of building them.","definitionCN":"为防卫某地而建的墙与工事，或建造行为。"},{"word":"forte","ipa":"/ˈfɔːteɪ/","tag":"strong point","definition":"A person's strong point; from the same Latin adjective but used in a different sense.","definitionCN":"某人的长处；同出拉丁形容词，但用于不同意义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"castle","ipa":"/ˈkɑːsl/","tag":"residence plus defence","definition":"A fortified home of a lord; it is both house and stronghold, while a fortress is primarily military.","definitionCN":"领主的设防居所，既是住宅也是据点；而 fortress 主要是军事性的。"},{"word":"citadel","ipa":"/ˈsɪtədəl/","tag":"city's strong core","definition":"The strongest part of a city's defences, often on high ground; it is a fortress inside a town.","definitionCN":"城市防御中最坚固的部分，常位于高地；是城镇内部的要塞。"},{"word":"stronghold","ipa":"/ˈstrɒŋhəʊld/","tag":"held position","definition":"A place firmly held against opposition; it can be a fortress or a political base.","definitionCN":"被牢牢守住的据点，可以是军事要塞或政治基地。"},{"word":"bastion","ipa":"/ˈbæstiən/","tag":"one projecting part","definition":"A projecting part of a fortification; it is one piece of a fortress, not the whole.","definitionCN":"防御工事中向外突出的部分，是要塞的一件构件而非整体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real strength root, the real siege terms and the real modern metaphor.","cn":"正常联想：真实的「坚固」词根、真实的攻城术语与真实的现代比喻。"},"normal":[{"en":"The root means strong, so a fortress is a place made artificially strong.","cn":"词根意为坚固，因此要塞就是一处被人为加固的地方。"},{"en":"The family runs fortress, fortify, fortification, fortified, fortitude, fortalice.","cn":"同族词包括 fortress、fortify、fortification、fortified、fortitude、fortalice。"},{"en":"Fixed phrases mark the branches: mountain fortress, fortress town, fortress Europe.","cn":"固定搭配标出各分支：山地要塞、设防城镇、壁垒欧洲。"},{"en":"A castle is a home that can fight; a fortress is a fighter that can house troops.","cn":"城堡是能作战的家，要塞是能驻军的战士。"},{"en":"The modern metaphor keeps only one feature: you cannot get through.","cn":"现代比喻只保留一个特征：你过不去。"}],"abstract":[{"en":"Picture a door so narrow that an army must enter one person at a time.","cn":"想象一道窄到军队只能一人一人进入的门。"},{"en":"Picture a wall with no windows, only arrow slits like thin closed eyes.","cn":"想象一面没有窗的墙，只有像细闭合眼睛的箭孔。"},{"en":"Picture a company that answers every question with a patent number.","cn":"想象一家公司对每个问题都回以一个专利号。"}]},"examples":[{"en":"The fortress surrendered only after its water cistern was breached.","cn":"这座要塞直到蓄水池被攻破后才投降。"},{"en":"The border has become a fortress of fences and cameras.","cn":"边境已成了一道由围栏与摄像头构成的壁垒。"},{"en":"Its old fortress walls now hold a public garden.","cn":"它旧日的要塞城墙如今围着一座公共花园。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"fort（坚固）+ ress（场所）→ 被造得坚固的地方 → 要塞、堡垒","word":"fortress"},"root":"古法语 forteresse 来自中世纪拉丁 fortalitia「坚固之地」，其基础是拉丁 fortis「坚固的、强大的」；英语 fortress。fortis 在拉丁语之前的来源不确定，相关印欧词根属重构形式。","sensesIntro":{"en":"Eight senses follow one refusal: a place refuses entry, and that refusal scales from walls to towns, works, bases, keeps, beliefs, institutions and finally to a building's shape.","cn":"八个义项沿同一种拒绝展开：某处拒绝进入；这种拒绝从城墙扩展到城镇、工事群、据点、核心、信念、机构，最后扩展到建筑的形状。"},"semanticMap":{"core":{"en":"CORE IMAGE: thick stone and one narrow gate, with every approach visible from the wall.","cn":"核心意象：厚石与一道窄门，从墙上能看见每一条来路。"},"chain":["THICK WALL","NARROW GATE","HELD POSITION","LAST RESISTANCE","BARRIER","STUBBORN STANCE"],"branches":[{"senses":"义项 01 · 02","en":"THE PLACE: a stronghold and a walled town are the same refusal at two scales.","cn":"地点：据点与设防城镇，是同一拒绝的两个尺度。"},{"senses":"义项 03 · 05","en":"THE SYSTEM: permanent works and forward bases turn the single wall into a military machine.","cn":"系统：永备工事与前沿据点把单面墙变成一台军事机器。"},{"senses":"义项 04 · 07","en":"THE BARRIER: patents and institutions become fortresses when they refuse to be crossed.","cn":"屏障：专利与机构在拒绝被越过时就成为堡垒。"},{"senses":"义项 06","en":"THE LAST CORE: the keep is the part built on the assumption that everything else may fall.","cn":"最后的核：核心堡垒是按「其余皆可能陷落」的假设造出的那一部分。"},{"senses":"义项 08","en":"THE LOOK: a modern concrete mass borrows defence as a style.","cn":"外观：现代混凝土体量把防御当作一种风格借用过来。"}]},"affixes":{"intro":{"en":"Fortress is a Latin strength adjective plus a suffix for a built place, and the same stem supplies the whole fortification family.","cn":"fortress 是一个拉丁语「坚固」形容词加表示建筑物的后缀，同一词干给出了整族筑城词汇。"},"latinIntro":{"en":"Latin fortis and the medieval noun fortalitia passed through Old French; English then built fortify, fortification and fortitude on the same stem.","cn":"拉丁语 fortis 与中世纪名词 fortalitia 经古法语传来；英语随后用同一词干构成 fortify、fortification 与 fortitude。"},"items":[{"word":"fortis","structure":"fortis, forte (Latin adjective)","meaning":"strong, mighty, brave","meaningCN":"坚固的；强大的；勇敢的","example":"Fortis described walls and soldiers alike.","exampleCN":"这个词既能描述墙，也能描述士兵。"},{"word":"fortalitia","structure":"fortis + -alia (built thing), medieval Latin","meaning":"a strong place","meaningCN":"坚固之地","example":"Fortalitia named the place, not the quality.","exampleCN":"这个词指地点，而非性质。"},{"word":"forteresse","structure":"forteresse (Old French noun)","meaning":"fortified town or castle","meaningCN":"设防城镇或城堡","example":"The forteresse guarded the river crossing.","exampleCN":"这座要塞守卫着河流渡口。"},{"word":"fortress","structure":"forteresse through Middle English","meaning":"a fortified stronghold","meaningCN":"设防据点","example":"The fortress held the pass.","exampleCN":"要塞控制着山口。"},{"word":"fortify","structure":"fortis + -ify (make)","meaning":"to make strong against attack","meaningCN":"加固以御攻击","example":"They fortified the gate with earth.","exampleCN":"他们用土加固了城门。"},{"word":"fortification","structure":"fortify + -ication (act or result)","meaning":"defensive works or the building of them","meaningCN":"防御工事或其建造","example":"The fortification followed the hill's contour.","exampleCN":"防御工事顺着山势延展。"},{"word":"fortified","structure":"fortify + -ed (provided with)","meaning":"made defensive","meaningCN":"设防的","example":"A fortified village blocked the road.","exampleCN":"一座设防村庄堵住了道路。"},{"word":"fortitude","structure":"fortis + -tudo (quality)","meaning":"strength of mind under pressure","meaningCN":"压力下的坚毅","example":"She bore the siege with fortitude.","exampleCN":"她以坚毅承受围困。"}],"latinEntries":[{"word":"fortis","structure":"fortis, forte (adj., third declension)","meaning":"strong, brave","meaningCN":"坚固的；勇敢的"},{"word":"fortitudo","structure":"fortitudo, fortitudinis (f., third declension)","meaning":"strength, courage","meaningCN":"力量；勇气"},{"word":"fortalitia","structure":"fortalitia, fortalitiae (f., first declension; medieval Latin)","meaning":"stronghold","meaningCN":"坚固据点"}]}},{"word":"castle","ipa_uk":"/ˈkɑːsl/","ipa_us":"/ˈkæsl/","definition_zh":"城堡；城堡式大宅；国际象棋的车；船首楼","definition_en":"a large fortified building with thick walls and towers, or the chess piece shaped like its tower","core_image":"山脊上一圈厚墙围着主楼，门楼两侧各有塔，吊桥正对唯一的来路","scene":"草坡上只剩一圈断墙，主楼的基座还看得出方形。The castle once controlled the river crossing below the hill.","sceneCN":"这里 castle 指「带厚墙与塔楼的设防居所」（第 1 个义项：城堡）；句意为这座城堡曾控制山下的河流渡口。图中可辨识物件：断墙、主楼基座、门楼、草坡。","pos":[{"tag":"n.","zh":"城堡；堡垒式大宅"},{"tag":"n.","zh":"（国际象棋）车"},{"tag":"v.","zh":"（国际象棋）王车易位"}],"collocations":[{"phrase":"medieval castle","zh":"中世纪城堡"},{"phrase":"castle walls","zh":"城堡城墙"},{"phrase":"castle gate","zh":"城堡城门"},{"phrase":"a castle in the air","zh":"空中楼阁（比喻）"},{"phrase":"castle keep","zh":"城堡主楼"},{"phrase":"build castles in the air","zh":"做白日梦"}],"forms":[{"label":"单数形式","form":"castle"},{"label":"复数形式","form":"castles"},{"label":"所有格","form":"castle's"},{"label":"动词三单","form":"castles"},{"label":"动词过去式","form":"castled"},{"label":"动词现在分词","form":"castling"}],"derivatives":[{"word":"castellan","pos":"n.","zh":"城堡守将；城主"},{"word":"castellated","pos":"adj.","zh":"有城垛的；城堡式的"},{"word":"castellation","pos":"n.","zh":"城垛装饰；城堡化"},{"word":"forecastle","pos":"n.","zh":"船首楼"},{"word":"castle-like","pos":"adj.","zh":"城堡般的"}],"senses":[{"no":"01","title":"A fortified residence","titleCN":"设防的城堡","definition":"a large building with walls, towers and a gate, built both to be lived in and to resist attack","definitionCN":"带城墙、塔楼与城门的大型建筑，既可居住又可抵御进攻","example":"The castle was built on a ridge where the river bends.","exampleCN":"这座城堡建在河流转弯处的山脊上。","why":"the Latin source is a diminutive of 'fort', so a castle is literally a little fort that grew into a home.","whyCN":"其拉丁来源是「堡垒」的指小形式，因此城堡字面上就是一座长成住宅的小堡垒。"},{"no":"02","title":"A castle-like country house","titleCN":"城堡式大宅","definition":"a grand British country house built with battlements and towers for prestige rather than defence","definitionCN":"为显声望而非防御建起、带城垛与塔楼的英国乡间大宅","example":"The family built a castle in the eighteenth century with no real fortifications.","exampleCN":"这个家族在十八世纪建了一座没有真正防御工事的城堡。","why":"once cannon made walls useless, the castle became a style that wealth could wear.","whyCN":"火炮让城墙失去作用之后，城堡就变成一种财富可以穿戴的风格。"},{"no":"03","title":"The rook in chess","titleCN":"国际象棋的车","definition":"the chess piece that moves any number of squares along a rank or file","definitionCN":"沿横线或竖线可走任意格数的棋子","example":"A castle on the open file controls the whole rank.","exampleCN":"一条开放线上的车控制整条横线。","why":"the piece was carved as a tower, and the tower's name replaced the older word for it.","whyCN":"这枚棋子被刻成塔楼，塔楼的名字取代了它原来的称呼。"},{"no":"04","title":"To move king and rook together","titleCN":"王车易位","definition":"in chess, to move the king two squares toward a rook and place the rook on the other side","definitionCN":"在国际象棋中把王向车方向移两格，并把车放到另一侧","example":"He castled early to bring the rook into the game.","exampleCN":"他早早易位，好让车投入战斗。","why":"the verb names the one move in which king and tower trade places.","whyCN":"这个动词指唯一一种王与塔交换位置的行棋方式。"},{"no":"05","title":"The raised deck at a ship's bow","titleCN":"船首楼","definition":"the raised structure at the front of a ship, originally a fighting platform","definitionCN":"船首的抬高结构，最初是作战平台","example":"The forecastle was rebuilt as a cabin for the crew.","exampleCN":"船首楼被改建成了船员舱。","why":"a ship's bow platform was a castle at sea, so sailors gave it the same name.","whyCN":"船首的作战平台就是海上的城堡，因此水手用了同一个名字。"},{"no":"06","title":"A private stronghold","titleCN":"比喻：退守的堡垒","definition":"a home or position treated as a place of retreat and safety","definitionCN":"被当作退守与安全之处看待的家或立场","example":"After the scandal he retreated to his castle in the country.","exampleCN":"丑闻之后，他退回到乡下的宅子里。","why":"the metaphor keeps the castle's two promises at once: privacy and resistance.","whyCN":"这个比喻同时保留了城堡的两个承诺：私密与抵抗。"},{"no":"07","title":"A motte-and-bailey earthwork","titleCN":"土丘加外郭的早期城堡","definition":"an early castle form with a raised mound and an enclosed bailey of earth and timber","definitionCN":"由抬高土丘与土木围成外郭的早期城堡形式","example":"The castle began as a mound of earth with a wooden tower.","exampleCN":"这座城堡最初只是一个带木塔的土丘。","why":"the earliest castles were earth and timber, so the word covers works that leave almost no stone.","whyCN":"最早的城堡是土与木，因此这个词也涵盖几乎不留石痕的工事。"},{"no":"08","title":"A fantasy castle","titleCN":"童话与装饰性城堡","definition":"a building or model built in a romantic tower-and-battlement style","definitionCN":"按浪漫化的塔楼与城垛样式建成或制作的建筑或模型","example":"The theme park's castle has six towers and a drawbridge.","exampleCN":"主题公园里的城堡有六座塔和一座吊桥。","why":"the castle survives as an image long after it stopped being a military fact.","whyCN":"城堡在不再是军事事实之后，仍作为图像长期存活。"}],"etymology":{"intro":{"en":"Castle comes from a Latin diminutive of 'fort', through Old French, and its military meaning later turned decorative. Dates are approximate.","cn":"castle 来自拉丁语中「堡垒」的指小形式，经古法语而来，其军事意义后来转向装饰。年代均为约数。"},"items":[{"era":"LATIN CASTRUM","en":"Castrum named a fortified camp or fort, the basic unit of Roman military building.","cn":"castrum 指设防营地或堡垒，是罗马军事营建的基本单位。"},{"era":"LATIN CASTELLUM","en":"The diminutive castellum meant a small fort or strong point, and it is the direct source of castle.","cn":"指小形式 castellum 意为小堡垒或据点，正是 castle 的直接来源。"},{"era":"OLD FRENCH CASTEL","en":"Old French castel carried the word into English, where it named a fortified residence of a lord.","cn":"古法语 castel 把这个词带入英语，指领主的设防居所。"},{"era":"STONE CASTLES","en":"From the eleventh century stone castles with keeps and curtain walls spread across Europe.","cn":"从十一世纪起，带主楼与环墙的石造城堡在欧洲扩散。"},{"era":"DECORATIVE CASTLE","en":"After gunpowder made high walls obsolete, the word was kept for grand houses and romantic follies.","cn":"火药使高墙过时之后，这个词被保留下来用于豪宅与浪漫化的仿建物。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin ancestry of castrum is disputed; a link to a root meaning 'to cut' has been proposed, but the reconstruction is not accepted by all scholars.","cn":"来源不确定（更深来源）：castrum 在拉丁语之前的谱系有争议；有人提出它与表示「切」的词根有关，但该重构并非所有学者都接受。"}]},"similar":{"note":{"en":"Group one holds words that look like castle or share its building field but come from other roots; group two holds kinds of fortified buildings.","cn":"第一组是与 castle 形近或同属建筑语义场、但来源不同的词；第二组是各类设防建筑。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"castellan","ipa":"/kæˈstelən/","tag":"the person","definition":"The officer in charge of a castle; it is a person word, not a building word.","definitionCN":"负责守卫城堡的官员；指人，不指建筑。"},{"word":"castellated","ipa":"/kæˈsteleɪtɪd/","tag":"having battlements","definition":"Built with battlements like a castle; it describes a feature rather than a whole fortified place.","definitionCN":"建有城垛如城堡；描述一种特征，而非整座设防建筑。"},{"word":"forecastle","ipa":"/ˈfəʊksl/","tag":"ship part","definition":"The bow deck of a ship; it borrows the castle image but has nothing to do with land warfare.","definitionCN":"船首甲板；借用了城堡意象，但与陆战无关。"},{"word":"château","ipa":"/ˈʃætəʊ/","tag":"French cousin","definition":"A French castle or country house; it comes from the same Latin fort word but through a different French form.","definitionCN":"法国的城堡或乡间宅邸；同出拉丁「堡垒」一词，但经不同的法语形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fortress","ipa":"/ˈfɔːtrɪs/","tag":"military first","definition":"A purely military stronghold; a castle is also a residence and a seat of local power.","definitionCN":"纯军事据点；而城堡同时也是居所与地方权力中心。"},{"word":"palace","ipa":"/ˈpælɪs/","tag":"display first","definition":"A ruler's residence built for ceremony and administration; it need not be defensible.","definitionCN":"为礼仪与治理而建的君主居所，不一定具备防御能力。"},{"word":"keep","ipa":"/kiːp/","tag":"the inner tower","definition":"The strongest tower inside a castle; it is one part of the castle, not the whole.","definitionCN":"城堡内最坚固的塔楼，是城堡的一部分而非整体。"},{"word":"citadel","ipa":"/ˈsɪtədəl/","tag":"city core","definition":"The fortified core of a city; it protects the town rather than serving as a lord's home.","definitionCN":"城市的设防核心，用于保护城镇而非作为领主住宅。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin diminutive, the real chess term and the real ship term.","cn":"正常联想：真实的拉丁指小形式、真实的象棋术语与真实的船舶术语。"},"normal":[{"en":"The Latin word is a small fort, so a castle is a fort that became a house.","cn":"拉丁词意为小堡垒，因此城堡就是变成住宅的堡垒。"},{"en":"The family runs castle, castellan, castellated, castellation, forecastle.","cn":"同族词包括 castle、castellan、castellated、castellation、forecastle。"},{"en":"Fixed phrases mark the branches: medieval castle, castle keep, castle in the air.","cn":"固定搭配标出各分支：中世纪城堡、城堡主楼、空中楼阁。"},{"en":"The chess piece and the ship's bow both borrow the tower idea.","cn":"棋子与船首都借用了塔楼这个意象。"},{"en":"A castle is a home that expects a fight; a palace expects a procession.","cn":"城堡是预期会打仗的家，宫殿预期的是仪仗。"}],"abstract":[{"en":"Picture a house wearing a stone coat it no longer needs.","cn":"想象一座房子穿着一件它已不再需要的石头外套。"},{"en":"Picture a chessboard where one square is a small tower with a view.","cn":"想象一张棋盘，其中一格是一座带视野的小塔。"},{"en":"Picture a ship's bow lifted like a chin, ready to take a blow.","cn":"想象船首像下巴一样抬起，准备挨一击。"}]},"examples":[{"en":"The castle's keep is the only part still standing.","cn":"城堡的主楼是唯一仍然立着的部分。"},{"en":"They castled on the seventh move and attacked on the ninth.","cn":"他们第七步易位，第九步开始进攻。"},{"en":"The hotel is a Victorian castle with forty rooms.","cn":"这家旅馆是一座有四十个房间的维多利亚式城堡。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"castellum（小堡垒）→ 设防的住宅 → 城堡；塔形棋子也叫这个名字","word":"castle"},"root":"拉丁 castellum「小堡垒」是 castrum「设防营地」的指小形式，经古法语 castel 入英语。英语 castle。castrum 的更早来源不确定，相关词根属重构形式。","sensesIntro":{"en":"Eight senses follow one building: a small fort becomes a lord's home, then a status house, a chess tower, a ship's deck, a private retreat, an earthwork and finally a fairytale image.","cn":"八个义项沿同一座建筑展开：小堡垒成为领主住宅，再成为身份宅邸、棋子塔楼、船首甲板、私人退守处、土方工事，最后成为童话图像。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ring of stone on a high place, with one gate and many towers.","cn":"核心意象：高地上的一圈石头，一道门与许多塔。"},"chain":["A SMALL FORT","A LORD'S HOUSE","A STATUS HOUSE","A TOWER PIECE","A SHIP'S PLATFORM","A FANTASY IMAGE"],"branches":[{"senses":"义项 01 · 07","en":"THE FORT: earthwork and stone castle are the same fortified home at two stages of building.","cn":"堡垒：土方工事与石造城堡，是设防住宅的两个建造阶段。"},{"senses":"义项 02","en":"STATUS: when walls stop working, battlements become a costume for wealth.","cn":"身份：当城墙失去作用，城垛就成了财富的戏服。"},{"senses":"义项 03 · 04","en":"THE TOWER PIECE: chess borrows the tower's shape and then its name for a move.","cn":"塔形棋子：国际象棋先借塔的形状，再借其名指一种走法。"},{"senses":"义项 05 · 06","en":"THE PRIVATE STRONGHOLD: a ship's bow and a country retreat are both places to hold out.","cn":"私人据点：船首与乡间退守处，都是可以据守的地方。"},{"senses":"义项 08","en":"THE IMAGE: the castle outlives its military use as a shape children recognize.","cn":"图像：城堡在军事用途之后仍作为一种儿童也认得的形状存活。"}]},"affixes":{"intro":{"en":"Castle is a Latin diminutive noun, so its parts explain a small fort, and English built a family of office, adjective and compound words on it.","cn":"castle 是一个拉丁语指小名词，其构件解释了「小堡垒」，英语又在其上建起职务、形容词与复合词一族。"},"latinIntro":{"en":"Latin castrum and its diminutive castellum are the sources; English castellan and castellated were formed later on the same stem.","cn":"拉丁语 castrum 及其指小形式 castellum 是来源；英语的 castellan 与 castellated 后来用同一词干构成。"},"items":[{"word":"castrum","structure":"castrum, castri (Latin noun, second declension)","meaning":"fortified camp, fort","meaningCN":"设防营地；堡垒","example":"A castrum housed a legion.","exampleCN":"一座营垒驻扎一个军团。"},{"word":"castellum","structure":"castrum + -ellum (diminutive)","meaning":"small fort","meaningCN":"小堡垒","example":"The diminutive made the fort smaller and homier.","exampleCN":"指小形式让堡垒更小、更像住处。"},{"word":"castle","structure":"castellum through Old French castel","meaning":"a fortified residence","meaningCN":"设防居所","example":"The castle guarded the bend.","exampleCN":"城堡守住了河湾。"},{"word":"castellan","structure":"castle + -an (officer of)","meaning":"the governor of a castle","meaningCN":"城堡守将","example":"The castellan answered to the count.","exampleCN":"守将向伯爵负责。"},{"word":"castellated","structure":"castellate + -ed (provided with)","meaning":"fitted with battlements","meaningCN":"带有城垛的","example":"A castellated tower rose above the trees.","exampleCN":"一座带城垛的塔楼高出树梢。"},{"word":"castellation","structure":"castellate + -ion (act or result)","meaning":"battlement work; castle-style ornament","meaningCN":"城垛工程；城堡式装饰","example":"The castellation is purely decorative.","exampleCN":"这些城垛纯粹是装饰。"},{"word":"forecastle","structure":"fore- ('front') + castle","meaning":"the raised bow deck of a ship","meaningCN":"船首的抬高甲板","example":"The crew slept in the forecastle.","exampleCN":"船员睡在船首楼。"},{"word":"castle-like","structure":"castle + -like (resembling)","meaning":"resembling a castle","meaningCN":"城堡般的","example":"A castle-like gate marks the estate.","exampleCN":"一道城堡式大门标记着这座庄园。"}],"latinEntries":[{"word":"castrum","structure":"castrum, castri (n., second declension)","meaning":"fortified camp","meaningCN":"设防营地"},{"word":"castellum","structure":"castellum, castelli (n., second declension; diminutive of castrum)","meaning":"small fort","meaningCN":"小堡垒"}]}},{"word":"dome","ipa_uk":"/dəʊm/","ipa_us":"/doʊm/","definition_zh":"穹顶；圆顶；半球形顶盖；穹丘；（俚语）头顶","definition_en":"a rounded roof shaped like half a ball, or any object with such a top","core_image":"一圈圆形石墙向上收拢，最后在正中合成一个采光的小孔","scene":"圆形大厅的墙向上收拢，顶部只留一个采光孔。The dome above the hall carries the weight of the whole roof without a single interior column.","sceneCN":"这里 dome 指「半球形的圆顶屋顶」（第 1 个义项：穹顶）；句意为大厅上方的穹顶不用一根内柱就承起整片屋顶。图中可辨识物件：圆形石墙、采光孔、大厅地面、屋顶轮廓。","pos":[{"tag":"n.","zh":"穹顶；圆顶；圆顶建筑"},{"tag":"n.","zh":"穹状顶盖；穹丘"}],"collocations":[{"phrase":"domed roof","zh":"穹形屋顶"},{"phrase":"the dome of the cathedral","zh":"主教座堂的穹顶"},{"phrase":"glass dome","zh":"玻璃圆顶"},{"phrase":"salt dome","zh":"盐穹"},{"phrase":"lava dome","zh":"熔岩穹丘"},{"phrase":"the dome of heaven","zh":"天穹（诗语）"}],"forms":[{"label":"单数形式","form":"dome"},{"label":"复数形式","form":"domes"},{"label":"所有格","form":"dome's"},{"label":"相关形容词","form":"domed"},{"label":"相关形容词（建筑）","form":"domical"}],"derivatives":[{"word":"domed","pos":"adj.","zh":"有圆顶的"},{"word":"domical","pos":"adj.","zh":"穹顶式的"},{"word":"semi-dome","pos":"n.","zh":"半穹顶"},{"word":"dome-shaped","pos":"adj.","zh":"穹形的"},{"word":"doming","pos":"n.","zh":"起穹；穹形隆起"}],"senses":[{"no":"01","title":"A rounded roof","titleCN":"穹顶屋顶","definition":"a roof formed as a hemisphere or similar curved surface over a circular or polygonal space","definitionCN":"覆盖圆形或多边形空间的半球形或类似曲面屋顶","example":"The dome rests on a ring of stone called a drum.","exampleCN":"穹顶架在一圈称为鼓座的石环上。","why":"the shape is the sense: a curved surface that closes a round space without internal supports.","whyCN":"形状就是词义：一种不用内部支撑就能封住圆形空间的曲面。"},{"no":"02","title":"A domed building","titleCN":"圆顶建筑","definition":"a building whose most prominent feature is its dome, such as a capitol or an observatory","definitionCN":"以穹顶为最显著特征的建筑，如议会大厦或天文台","example":"The observatory dome rotates to follow the sky.","exampleCN":"天文台的圆顶会转动以追随天空。","why":"by metonymy the roof stands for the whole building, especially when the roof is what people recognize.","whyCN":"以提喻法，屋顶代表整座建筑，尤其当人们认出的正是那片屋顶时。"},{"no":"03","title":"Any hemispherical cover","titleCN":"半球形顶盖","definition":"a rounded cover on an object, such as a tank, a lamp or a stadium roof","definitionCN":"物体上的圆顶盖，如储罐、灯具或体育场屋顶","example":"The fuel tank's dome vents gas when pressure rises.","exampleCN":"压力升高时，燃料罐的圆顶会排气。","why":"the architectural shape is abstracted into any rounded lid or cap.","whyCN":"建筑形状被抽象成任何圆形的盖或罩。"},{"no":"04","title":"A geological dome","titleCN":"地质穹丘","definition":"a rounded uplift of rock or salt, often formed by pressure from below","definitionCN":"由下方压力形成的岩石或盐层圆形隆起","example":"The salt dome traps oil in the layers above it.","exampleCN":"盐穹把石油封存在其上方的岩层里。","why":"geology borrowed the shape word because a rising mass of salt or lava looks like a roof from below.","whyCN":"地质学借用了这个形状词，因为上升的盐体或熔岩从下方看就像一片屋顶。"},{"no":"05","title":"A slang word for the head","titleCN":"俚语：脑袋","definition":"in informal use, the top of a person's head","definitionCN":"非正式用法中指人的头顶","example":"He took off his cap and rubbed his dome.","exampleCN":"他摘下帽子，摸了摸脑袋。","why":"the slang keeps only the roundness and position of a dome, with no architecture left.","whyCN":"这个俚语只保留了穹顶的圆与位置，建筑义已不剩。"},{"no":"06","title":"The vault of the sky","titleCN":"诗语：天穹","definition":"the sky pictured as a great curved roof over the earth","definitionCN":"把天空想象成覆盖大地的巨大曲面屋顶","example":"Stars filled the dome of heaven above the desert.","exampleCN":"星空布满沙漠上方的天穹。","why":"ancient cosmology pictured the sky as a solid bowl, and the image survives in poetry.","whyCN":"古代宇宙观把天空想象成一只实心碗，这个意象在诗歌中留存。"},{"no":"07","title":"A domed sports arena","titleCN":"圆顶体育馆","definition":"a large indoor arena whose roof is a dome, often referred to by the name Dome","definitionCN":"屋顶为穹形的大型室内场馆，常直接以「圆顶」为名","example":"The finals were played under the dome before sixty thousand people.","exampleCN":"决赛在这座圆顶场馆内、六万人面前举行。","why":"venues took the building part as a brand, so the word now names arenas as well as roofs.","whyCN":"场馆把这一建筑部件当作招牌，因此这个词也指场馆本身。"},{"no":"08","title":"A cathedral in Italian usage","titleCN":"意大利语中的主教座堂","definition":"the older English sense, from Italian, of a cathedral church, especially one with a dome","definitionCN":"英语旧义，来自意大利语，指主教座堂，尤指带穹顶者","example":"The guide calls the cathedral simply the dome, as Italians do.","exampleCN":"导游像意大利人那样，径直把这座主教座堂称作圆顶。","why":"the English word entered through the Italian name for a cathedral, so the building and its roof were once the same word.","whyCN":"英语词是经意大利语中「主教座堂」之名进来的，因此建筑与屋顶曾同为一词。"}],"etymology":{"intro":{"en":"Dome entered English through French from the Italian word for a cathedral, and only later narrowed to the rounded roof. Dates are approximate.","cn":"dome 经法语从意大利语中「主教座堂」一词进入英语，后来才收窄为圆形屋顶。年代均为约数。"},"items":[{"era":"LATIN DOMUS","en":"Domus meant house or household, and the phrase for a house of God supplied the Italian church word.","cn":"domus 意为房屋或家庭，「上帝之屋」这一短语给出了意大利语的教堂词。"},{"era":"ITALIAN DUOMO","en":"Duomo named a cathedral, especially the principal church of a city, and many such churches carried a dome.","cn":"duomo 指主教座堂，尤指一座城市的主要教堂，而许多此类教堂都带穹顶。"},{"era":"FRENCH DOME","en":"French dôme borrowed the Italian word and used it for the rounded roof as well as the church.","cn":"法语 dôme 借入意大利语词，既用于教堂，也用于圆形屋顶。"},{"era":"ENGLISH DOME","en":"English took the word in the seventeenth century, when domes were being built again in Britain.","cn":"英语在十七世纪借入该词，其时英国正重新兴建穹顶。"},{"era":"SCIENTIFIC EXTENSION","en":"In later centuries geology and engineering applied the shape word to salt uplifts, tank tops and stadium roofs.","cn":"在后来的世纪里，地质与工程把这个形状词用于盐层隆起、罐顶与体育场屋顶。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin ancestry of domus is not settled, and the Indo-European root usually cited for it is a reconstruction.","cn":"来源不确定（更深来源）：domus 在拉丁语之前的谱系尚无定论，通常为其引用的印欧语词根属重构形式。"}]},"similar":{"note":{"en":"Group one holds curved-roof words that are often confused; group two holds words for rounded tops and for the buildings beneath them.","cn":"第一组是容易混淆的曲面屋顶词；第二组是圆顶状顶盖与穹顶之下建筑的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cupola","ipa":"/ˈkjuːpələ/","tag":"small crown","definition":"A small dome-like structure on a roof, often with windows; it sits on the roof rather than covering the whole room.","definitionCN":"屋顶上的小型穹状结构，常带窗；它置于屋顶之上，而非覆盖整个房间。"},{"word":"duomo","ipa":"/ˈdwɔːməʊ/","tag":"Italian cathedral","definition":"The Italian word for a cathedral, which gave dome its English sense; it names the church, not the roof.","definitionCN":"意大利语中「主教座堂」一词，给了 dome 英语词义；它指教堂，而非屋顶。"},{"word":"domed","ipa":"/dəʊmd/","tag":"adjective","definition":"Having a dome; it describes a building or object rather than naming the structure.","definitionCN":"有圆顶的；描述建筑或物体，而非命名结构。"},{"word":"domical","ipa":"/ˈdəʊmɪkəl/","tag":"technical adjective","definition":"Of dome form, used in architectural writing; it never names a physical dome.","definitionCN":"穹顶形式的，用于建筑写作；从不指实体穹顶。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vault","ipa":"/vɔːlt/","tag":"arched ceiling","definition":"An arched ceiling, usually continuous along a corridor; a dome is a vault turned around a central point.","definitionCN":"拱形顶棚，通常沿走廊连续延伸；穹顶是绕中心点旋转的拱顶。"},{"word":"arch","ipa":"/ɑːtʃ/","tag":"curved support","definition":"A curved structure spanning an opening; a dome is a curved roof, while an arch is a curved span.","definitionCN":"跨越开口的曲线结构；穹顶是曲面屋顶，拱则是曲线跨度。"},{"word":"spire","ipa":"/spaɪə/","tag":"pointed top","definition":"A tall pointed structure on a tower; it rises to a point, while a dome closes in a curve.","definitionCN":"塔上高耸的尖顶；它收成一点，而穹顶以曲线闭合。"},{"word":"roof","ipa":"/ruːf/","tag":"general word","definition":"The covering of a building; a dome is one kind of roof with a particular geometry.","definitionCN":"建筑的覆盖物；穹顶是其中一种具有特定几何形状的屋顶。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Italian route, the real shape words and the real technical compounds.","cn":"正常联想：真实的意大利语来源路径、真实的形状词与真实的技术复合词。"},"normal":[{"en":"The word travelled from 'house of God' to 'cathedral' to 'rounded roof'.","cn":"这个词从「上帝之屋」走到「主教座堂」，再到「圆形屋顶」。"},{"en":"The family runs dome, domed, domical, semi-dome, dome-shaped, doming.","cn":"同族词包括 dome、domed、domical、semi-dome、dome-shaped、doming。"},{"en":"Fixed phrases mark the branches: glass dome, salt dome, lava dome, dome of heaven.","cn":"固定搭配标出各分支：玻璃圆顶、盐穹、熔岩穹丘、天穹。"},{"en":"A dome closes a round space without interior columns; that is its engineering point.","cn":"穹顶不用内柱就能封住圆形空间，这正是它的工程要点。"},{"en":"The slang sense keeps only the round top of a head.","cn":"俚语义只保留了脑袋的圆顶。"}],"abstract":[{"en":"Picture a bowl turned upside down and made of stone.","cn":"想象一只倒扣过来的碗，材料是石头。"},{"en":"Picture a room where the ceiling is the sky and the walls are only a rim.","cn":"想象一间以天空为顶、墙只剩一圈边缘的房间。"},{"en":"Picture a stadium breathing under a single continuous lid.","cn":"想象一座体育场在一整片连续的盖下呼吸。"}]},"examples":[{"en":"The dome was regilded after a century of weather.","cn":"经历一个世纪的风雨之后，穹顶被重新贴金。"},{"en":"A glass dome covers the whole courtyard.","cn":"一座玻璃圆顶覆盖整个庭院。"},{"en":"Drilling stopped when the bit reached the salt dome.","cn":"钻头抵达盐穹时，钻探停止了。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"duomo（主教座堂）→ 教堂上的圆屋顶 → 穹顶；也指任何圆顶盖","word":"dome"},"root":"法语 dôme 来自意大利 duomo「主教座堂」，其源头是拉丁 domus「房屋、家」，尤指「上帝之屋」；英语 dome 由教堂义转为圆顶义。domus 的更早来源不确定。","sensesIntro":{"en":"Eight senses follow one curve: a roof closes a round room, then stands for a building, a lid, a rock uplift, a head, the sky, an arena and an old name for a cathedral.","cn":"八个义项沿同一条曲线展开：屋顶封住圆形房间，再代表整座建筑、一只盖、一处岩隆、一个头、一片天、一座场馆，以及主教座堂的旧称。"},"semanticMap":{"core":{"en":"CORE IMAGE: a circle of wall rising and closing into one point of light.","cn":"核心意象：一圈墙向上升起，最后收拢成一点光。"},"chain":["A CURVED ROOF","A ROUND BUILDING","A ROUND LID","A ROCK UPLIFT","A ROUND HEAD","A CURVED SKY"],"branches":[{"senses":"义项 01","en":"THE ROOF: the first sense is the curved surface that closes a round space.","cn":"屋顶：第一个义项是封住圆形空间的曲面。"},{"senses":"义项 02 · 07","en":"THE BUILDING: an observatory and an arena are known by the roof that crowns them.","cn":"建筑：天文台与体育馆都因冠于其上的屋顶而被认出。"},{"senses":"义项 03 · 04","en":"THE SHAPE ITSELF: a tank lid and a salt uplift are the same curve at different scales.","cn":"形状本身：罐盖与盐穹，是同一曲线的不同尺度。"},{"senses":"义项 05 · 06","en":"ROUND TOPS: a head and the sky repeat the dome as a plain image of roundness.","cn":"圆顶：脑袋与天空把穹顶重复为单纯的圆形意象。"},{"senses":"义项 08","en":"THE OLD NAME: Italian usage once made the cathedral and its roof a single word.","cn":"旧名：意大利语用法曾让主教座堂与其屋顶同为一词。"}]},"affixes":{"intro":{"en":"Dome has no productive prefix or suffix in English; its history is a borrowing from a house word to a roof word, and its derived forms simply add English endings.","cn":"dome 在英语中没有能产的前缀或后缀；它的历史是从「房屋」词借为「屋顶」词，其派生形式只是加英语词尾。"},"latinIntro":{"en":"Latin domus is the ultimate source, through Italian duomo and French dôme; Latin also had the adjective domesticus from the same house word.","cn":"拉丁语 domus 是最终源头，经意大利语 duomo 与法语 dôme 而来；拉丁语还有同出「房屋」词的形容词 domesticus。"},"items":[{"word":"domus","structure":"domus, domus (Latin noun, fourth declension)","meaning":"house, household","meaningCN":"房屋；家庭","example":"Domus named a home before it named a church.","exampleCN":"这个词先指家，后指教堂。"},{"word":"duomo","structure":"duomo (Italian noun, from Latin domus)","meaning":"cathedral","meaningCN":"主教座堂","example":"The duomo stands in the centre of the old city.","exampleCN":"主教座堂立在老城中心。"},{"word":"dôme","structure":"dôme (French noun, from Italian duomo)","meaning":"cathedral; rounded roof","meaningCN":"主教座堂；圆形屋顶","example":"French kept both meanings for a time.","exampleCN":"法语有一段时间两义并用。"},{"word":"dome","structure":"dôme through English","meaning":"a rounded roof","meaningCN":"圆形屋顶","example":"The dome covers the crossing.","exampleCN":"穹顶覆盖交叉部。"},{"word":"domed","structure":"dome + -ed (having)","meaning":"having a dome","meaningCN":"有圆顶的","example":"A domed hall reflects sound for seconds.","exampleCN":"带穹顶的大厅能把声音反射数秒。"},{"word":"domical","structure":"dome + -ical (relating to)","meaning":"of dome form","meaningCN":"穹顶形式的","example":"The domical vault is a technical label.","exampleCN":"穹形拱顶是一个技术标签。"},{"word":"semi-dome","structure":"semi- ('half') + dome","meaning":"a half dome, as over an apse","meaningCN":"半穹顶，如后殿上方的顶","example":"A semi-dome closes the apse.","exampleCN":"半穹顶封住后殿。"},{"word":"dome-shaped","structure":"dome + shaped (English compound)","meaning":"having the form of a dome","meaningCN":"穹形的","example":"A dome-shaped lid seals the tank.","exampleCN":"一个穹形盖密封储罐。"}],"latinEntries":[{"word":"domus","structure":"domus, domus (f., fourth declension)","meaning":"house, home","meaningCN":"房屋；家"},{"word":"domesticus","structure":"domesticus, domestica, domesticum (adj.)","meaning":"of the house, household","meaningCN":"房屋的；家庭的"}]}},{"word":"arch","ipa_uk":"/ɑːtʃ/","ipa_us":"/ɑːrtʃ/","definition_zh":"拱；拱门；足弓；拱起；首要的（构词前缀义）","definition_en":"a curved structure that spans an opening and supports weight above it, or a curved shape resembling this","core_image":"一块块楔形石互相挤压，把上方的重量沿曲线传到两侧墙脚","scene":"石桥下的圆弧把整条桥面托住，石缝里长着细草。The stone arch carries the weight of the wall above it without any wooden beam.","sceneCN":"这里 arch 指「跨越开口并把上方重量分散到两侧的拱形结构」（第 1 个义项：拱）；句意为这道石拱不用木梁就承住了上方的墙。图中可辨识物件：石桥、圆弧、楔形石、墙脚。","pos":[{"tag":"n.","zh":"拱；拱门；拱形结构"},{"tag":"n.","zh":"足弓；眉弓"},{"tag":"v.","zh":"拱起；成拱形"},{"tag":"adj.","zh":"首要的；为首的（多作构词成分）"}],"collocations":[{"phrase":"stone arch","zh":"石拱"},{"phrase":"arch bridge","zh":"拱桥"},{"phrase":"arch of the foot","zh":"足弓"},{"phrase":"arch support","zh":"足弓支撑"},{"phrase":"a triumphal arch","zh":"凯旋门"},{"phrase":"arch enemy","zh":"头号敌人"}],"forms":[{"label":"单数形式","form":"arch"},{"label":"复数形式","form":"arches"},{"label":"所有格","form":"arch's"},{"label":"动词三单","form":"arches"},{"label":"动词过去式","form":"arched"},{"label":"动词过去分词","form":"arched"},{"label":"动词现在分词","form":"arching"}],"derivatives":[{"word":"arched","pos":"adj.","zh":"拱形的"},{"word":"archer","pos":"n.","zh":"弓箭手（同出拉丁「弓」）"},{"word":"archery","pos":"n.","zh":"射箭"},{"word":"archway","pos":"n.","zh":"拱道；拱门通道"},{"word":"archwise","pos":"adv.","zh":"成拱形地"}],"senses":[{"no":"01","title":"A curved spanning structure","titleCN":"拱形承重结构","definition":"a curved structure that spans an opening and carries weight by compression","definitionCN":"跨越开口、靠受压传递重量的曲线结构","example":"The arch turns the downward load into a sideways thrust.","exampleCN":"拱把向下的荷载转为向两侧的推力。","why":"the word first named a bow, and a bent bow is exactly the shape that carries weight by compression.","whyCN":"这个词最初指弓，而弯弓正是靠受压承重的形状。"},{"no":"02","title":"A gateway with a curved top","titleCN":"拱门；牌坊","definition":"an opening in a wall topped by a curve, often built as a monument","definitionCN":"墙上的曲线顶开口，常作为纪念性建筑","example":"The triumphal arch marks the old entrance to the city.","exampleCN":"那座凯旋门标记着城市的旧入口。","why":"when the structure is mostly an opening, the word names the gateway rather than the engineering.","whyCN":"当结构主要是一个开口时，这个词指门本身，而非工程原理。"},{"no":"03","title":"The arch of the foot","titleCN":"足弓","definition":"the curved instep of the human foot, formed by bones and ligaments","definitionCN":"由骨骼与韧带形成的人脚背曲线","example":"The arch of the foot acts as a spring with every step.","exampleCN":"每走一步，足弓都像弹簧一样工作。","why":"the body has its own spanning curves, so the architectural word was applied to anatomy.","whyCN":"身体自身就有跨度的曲线，因此建筑词被用到解剖上。"},{"no":"04","title":"The brow's curve","titleCN":"眉弓","definition":"the bony ridge above the eye","definitionCN":"眼睛上方的骨质隆起","example":"A heavy arch above the eyes gives the skull a stern look.","exampleCN":"眼睛上方厚重的眉弓让头骨显得严厉。","why":"any bony curve can be called an arch, and the brow is the most visible one.","whyCN":"任何骨质曲线都可叫 arch，而眉弓是最显眼的一处。"},{"no":"05","title":"Anything shaped like a bow","titleCN":"拱形物；弧形","definition":"a curved object or line, such as a rainbow or a row of trees","definitionCN":"弯曲的物体或线条，如彩虹或一排行道树","example":"A pale arch of light stood over the valley after the rain.","exampleCN":"雨后，一道浅色光弧立在山谷上方。","why":"the shape sense is older than the building sense and survives in descriptions of nature.","whyCN":"形状义比建筑义更古老，并在自然描写中留存。"},{"no":"06","title":"To curve upward or over","titleCN":"动词：拱起、成拱形","definition":"to bend into a curve, or to span something in a curve","definitionCN":"弯成曲线，或以曲线跨越某物","example":"The cat arched its back at the sound of the door.","exampleCN":"听到门响，猫弓起了背。","why":"the verb is simply the shape turned into motion, and it applies to bodies, branches and eyebrows.","whyCN":"动词只是把形状变成动作，适用于身体、枝条与眉毛。"},{"no":"07","title":"Chief or principal","titleCN":"构词义：首要的、为首的","definition":"in compounds, first or foremost, as in arch-enemy or arch-criminal","definitionCN":"在复合词中表示第一位的、为首的，如头号敌人或首恶","example":"He became the arch-rival of the reigning champion.","exampleCN":"他成了在位冠军的头号对手。","why":"this sense has a different source: a Greek word for leader, not the Latin word for bow.","whyCN":"这一义项来源不同：它来自希腊语「首领」，而非拉丁语「弓」。"},{"no":"08","title":"A shoe's arch support","titleCN":"鞋弓支撑","definition":"the raised part inside a shoe that supports the instep","definitionCN":"鞋内托住脚背的隆起部分","example":"The insole's arch takes the pressure off the heel.","exampleCN":"鞋垫的足弓部分减轻了脚跟压力。","why":"shoemaking borrowed the anatomical word for the part of the foot it must hold.","whyCN":"制鞋业借用了这个解剖词，指它必须托住的那部分脚。"}],"etymology":{"intro":{"en":"English arch is two words that look alike: a Latin bow and a Greek leader. Dates are approximate.","cn":"英语 arch 是两个形似的词：一个来自拉丁语「弓」，一个来自希腊语「首领」。年代均为约数。"},"items":[{"era":"LATIN ARCUS","en":"Arcus meant a bow or a curved arc, and it named both the weapon and the shape.","cn":"arcus 指弓或弧线，既命名武器也命名形状。"},{"era":"OLD FRENCH ARCHE","en":"Old French arche carried the architectural sense into English, where it named a curved span.","cn":"古法语 arche 把建筑义带入英语，指曲线跨度。"},{"era":"GREEK ARKHOS","en":"Separately, Greek arkhos meant leader or chief, and its combining form entered English as a prefix.","cn":"另一方面，希腊语 arkhos 意为首领，其组合形式作为前缀进入英语。"},{"era":"ARCHITECTURAL ARCH","en":"From the twelfth century the pointed and round arch drove Gothic and Romanesque building.","cn":"从十二世纪起，尖拱与圆拱推动了哥特式与罗曼式建筑。"},{"era":"ANATOMY","en":"The same shape word was applied to the instep and the brow because both are curved supports.","cn":"同一个形状词被用于脚背与眉部，因为两者都是曲线支撑。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin ancestry of arcus is not established, and the Greek leader word has a separate disputed origin, so the two are not related despite identical spelling.","cn":"来源不确定（更深来源）：arcus 在拉丁语之前的谱系未得到证明，希腊语「首领」词另有争议来源；两者拼写相同但并无亲缘关系。"}]},"similar":{"note":{"en":"Group one holds words from the Latin bow family or easily mistaken for them; group two holds curved structures and shapes.","cn":"第一组是同出拉丁「弓」一族或容易误认的词；第二组是曲线结构与形状。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"arc","ipa":"/ɑːk/","tag":"the curve itself","definition":"A part of a circle, or an electric discharge across a gap; both come from the same Latin bow word.","definitionCN":"圆周的一段，或跨越间隙的放电；两义都来自同一个拉丁「弓」词。"},{"word":"archer","ipa":"/ˈɑːtʃə/","tag":"bow user","definition":"A person who shoots with a bow; it comes from the same Latin source but names a person.","definitionCN":"用弓射箭的人；同出拉丁来源，但指人。"},{"word":"arch-","ipa":"/ɑːtʃ/","tag":"different root","definition":"A prefix meaning chief, from Greek; it is unrelated to the Latin bow and must be read separately.","definitionCN":"表示「首领」的前缀，来自希腊语；与拉丁「弓」无关，须分开理解。"},{"word":"archway","ipa":"/ˈɑːtʃweɪ/","tag":"compound","definition":"A passage under an arch; it is arch plus way, a covered route rather than the structure alone.","definitionCN":"拱下的通道；由 arch 加 way 构成，指有顶路线而非单独结构。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vault","ipa":"/vɔːlt/","tag":"arched ceiling","definition":"An arched ceiling over a space; an arch spans an opening in a wall, while a vault covers a room.","definitionCN":"覆盖空间的拱形顶棚；arch 跨越墙上的开口，vault 覆盖房间。"},{"word":"dome","ipa":"/dəʊm/","tag":"rounded roof","definition":"A curved roof over a round space; it is an arch rotated around a centre.","definitionCN":"覆盖圆形空间的曲面屋顶；是绕中心旋转的拱。"},{"word":"beam","ipa":"/biːm/","tag":"straight span","definition":"A straight structural member carrying load; it works by bending, while an arch works by compression.","definitionCN":"承受荷载的直构件，靠弯曲工作；而拱靠受压工作。"},{"word":"curve","ipa":"/kɜːv/","tag":"general shape","definition":"Any line that bends; an arch is one kind of curve with a structural job.","definitionCN":"任何弯曲的线；arch 是带有结构任务的一种曲线。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real bow root, the real anatomy words and the separate Greek prefix.","cn":"正常联想：真实的「弓」词根、真实的解剖词与另一个希腊语前缀。"},"normal":[{"en":"The Latin root means bow, so the structure and the weapon share one curved shape.","cn":"拉丁词根意为弓，因此结构与武器共有一个弯曲的形状。"},{"en":"The family runs arch, arched, archer, archery, archway, archwise.","cn":"同族词包括 arch、arched、archer、archery、archway、archwise。"},{"en":"Fixed phrases mark the branches: stone arch, arch bridge, arch of the foot, arch enemy.","cn":"固定搭配标出各分支：石拱、拱桥、足弓、头号敌人。"},{"en":"The curve works by squeezing: each stone pushes its neighbour and the load slides down the legs.","cn":"这条曲线靠挤压工作：每块石头推着邻石，荷载沿两侧墙脚滑下。"},{"en":"The chief sense is a different word: Greek leader, not Latin bow.","cn":"「首要」义是另一个词：希腊语首领，而非拉丁语弓。"}],"abstract":[{"en":"Picture a row of stones learning to lean on each other so none falls.","cn":"想象一排石头学会彼此倚靠，于是一块也不落。"},{"en":"Picture a rainbow that has been asked to hold up a bridge.","cn":"想象一道彩虹被请求去托住一座桥。"},{"en":"Picture an eyebrow as a small bridge over an eye.","cn":"想象眉毛是一只眼睛上方的小桥。"}]},"examples":[{"en":"The bridge's arch has stood for six hundred years.","cn":"这座桥的拱已立了六百年。"},{"en":"High arches support the soles of runners.","cn":"高足弓支撑着跑者的脚底。"},{"en":"The two companies are arch rivals in the same market.","cn":"这两家公司在同一市场是头号对手。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"arcus（弓）→ 弯成弓形的承重结构 → 拱；同形前缀又表示「首领」","word":"arch"},"root":"名词 arch 来自拉丁 arcus「弓、弧」，经古法语 arche 入英语；表示「首领」的 arch- 另有希腊语 arkhos 来源，二者拼写相同但无亲缘。英语 arch。arcus 更深来源不确定。","sensesIntro":{"en":"Eight senses follow one curve: a bow becomes a span, then a gateway, then the body's own arches, then any curved shape, a verb, a separate 'chief' prefix and finally a shoe part.","cn":"八个义项沿同一条曲线展开：弓成为跨度，再成为门、身体自身的弓、任何弯曲形状、动词，另有一条「首领」前缀义，最后落到鞋内支撑。"},"semanticMap":{"core":{"en":"CORE IMAGE: wedge-shaped stones leaning on one another so the load travels down both legs.","cn":"核心意象：楔形石块彼此倚靠，使荷载沿两侧墙脚传下。"},"chain":["A BOW","A SPAN","A GATEWAY","A BODY CURVE","A VERB OF BENDING","A SEPARATE PREFIX"],"branches":[{"senses":"义项 01 · 05","en":"THE CURVE: a structural span and a rainbow are the same bowed line with and without a job.","cn":"曲线：承重跨度与彩虹，是同一条弓形线，一条有任务，一条没有。"},{"senses":"义项 02","en":"THE GATEWAY: when the opening matters more than the engineering, the arch becomes a door.","cn":"门：当开口比工程更重要时，拱就成了门。"},{"senses":"义项 03 · 04 · 08","en":"THE BODY: the foot, the brow and the shoe all repeat the same small bridge.","cn":"身体：脚、眉与鞋都重复着同一座小桥。"},{"senses":"义项 06","en":"THE ACTION: the shape becomes a verb when a back or a branch bends.","cn":"动作：当背或枝条弯曲时，形状变成动词。"},{"senses":"义项 07","en":"THE OTHER WORD: the 'chief' sense is a Greek leader, not a Latin bow.","cn":"另一个词：「首要」义是希腊语首领，而非拉丁语弓。"}]},"affixes":{"intro":{"en":"Arch is a Latin bow noun plus a separate Greek leader prefix, so the affix list must keep the two lines apart.","cn":"arch 是一个拉丁语「弓」名词加上一个独立的希腊语「首领」前缀，因此词缀清单必须把两条线分开。"},"latinIntro":{"en":"Latin arcus gives arc, arch, archer and archery; the prefix arch- comes from Greek arkhos and is not a relative.","cn":"拉丁语 arcus 给出 arc、arch、archer 与 archery；表示「首领」的前缀来自希腊语 arkhos，并非同族。"},"items":[{"word":"arcus","structure":"arcus, arcus (Latin noun, fourth declension)","meaning":"bow, arc","meaningCN":"弓；弧","example":"Arcus named the weapon and the curve.","exampleCN":"这个词既指武器也指曲线。"},{"word":"arc","structure":"arcus through French arc","meaning":"a part of a curve","meaningCN":"曲线的一段","example":"The arc of the bridge is shallow.","exampleCN":"这座桥的弧很浅。"},{"word":"arch","structure":"arcus through Old French arche","meaning":"a curved span","meaningCN":"曲线跨度","example":"The arch spans the nave.","exampleCN":"拱跨越中殿。"},{"word":"arched","structure":"arch + -ed (having)","meaning":"curved like an arch","meaningCN":"拱形的","example":"An arched window lights the stair.","exampleCN":"一扇拱窗照亮楼梯。"},{"word":"archer","structure":"arcus + -er (one who uses)","meaning":"a bowman","meaningCN":"弓箭手","example":"The archer drew the bow.","exampleCN":"弓箭手拉开了弓。"},{"word":"archery","structure":"archer + -y (practice)","meaning":"the sport of shooting with a bow","meaningCN":"射箭运动","example":"Archery requires a steady arm.","exampleCN":"射箭需要稳定的手臂。"},{"word":"archway","structure":"arch + way (English compound)","meaning":"a passage under an arch","meaningCN":"拱下通道","example":"The archway leads to the courtyard.","exampleCN":"拱道通向庭院。"},{"word":"arch-","structure":"arkh- (Greek prefix, 'chief', from arkhos)","meaning":"chief; principal","meaningCN":"首领的；首要的","example":"An arch-rival is the chief rival.","exampleCN":"头号对手就是最主要的对手。"}],"latinEntries":[{"word":"arcus","structure":"arcus, arcus (m., fourth declension)","meaning":"bow, arc","meaningCN":"弓；弧"},{"word":"arcuatus","structure":"arcuatus, arcuata, arcuatum (adj.)","meaning":"bow-shaped, arched","meaningCN":"弓形的；拱形的"}]}},{"word":"column","ipa_uk":"/ˈkɒləm/","ipa_us":"/ˈkɑːləm/","definition_zh":"圆柱；立柱；柱状物；专栏；表格的列；纵队","definition_en":"a tall upright pillar used as a support or ornament, or a vertical arrangement of items such as text, numbers or troops","core_image":"一根直立的石柱从基座升到柱头，顶上托着横梁，柱身有竖向的凹槽","scene":"神庙的柱廊只剩一排立柱，横梁早已不见。Each column rises from its base to a capital that once held a wooden beam.","sceneCN":"这里 column 指「建筑中直立的承重或装饰柱」（第 1 个义项：圆柱、立柱）；句意为每根柱子从基座升到柱头，柱头曾托住木梁。图中可辨识物件：柱廊、基座、柱身凹槽、柱头。","pos":[{"tag":"n.","zh":"圆柱；立柱"},{"tag":"n.","zh":"柱状物；专栏；列；纵队"}],"collocations":[{"phrase":"stone column","zh":"石柱"},{"phrase":"a column of smoke","zh":"一道烟柱"},{"phrase":"newspaper column","zh":"报纸专栏"},{"phrase":"the left column of the table","zh":"表格的左列"},{"phrase":"a column of troops","zh":"一队行军队列"},{"phrase":"column capital","zh":"柱头"}],"forms":[{"label":"单数形式","form":"column"},{"label":"复数形式","form":"columns"},{"label":"所有格","form":"column's"},{"label":"相关形容词","form":"columnar"},{"label":"相关人物名词","form":"columnist"}],"derivatives":[{"word":"columnar","pos":"adj.","zh":"柱状的；圆柱形的"},{"word":"columned","pos":"adj.","zh":"有立柱的"},{"word":"columnist","pos":"n.","zh":"专栏作家"},{"word":"columniation","pos":"n.","zh":"柱列布置；列柱法"},{"word":"columniform","pos":"adj.","zh":"柱状的；柱形的"}],"senses":[{"no":"01","title":"An upright architectural support","titleCN":"建筑立柱","definition":"a tall vertical shaft, usually stone, that supports a load or frames a space","definitionCN":"通常为石质的高大竖向柱身，用于承重或框定空间","example":"Each column is slightly thicker at the base to carry the roof.","exampleCN":"每根柱子底部略粗，以承住屋顶。","why":"the Latin word meant a rising shaft, and architecture kept that plain meaning longer than any other field.","whyCN":"拉丁词意为向上升起的柱身，建筑比其他领域更久地保留了这一朴素意义。"},{"no":"02","title":"Anything rising like a shaft","titleCN":"柱状物（烟、水、气）","definition":"a tall narrow mass of smoke, water, flame or air","definitionCN":"烟、水、火焰或空气形成的细高柱体","example":"A column of ash rose three kilometres above the crater.","exampleCN":"一根火山灰柱升到火山口上方三公里。","why":"the shape alone is enough: anything tall and narrow repeats the column without supporting anything.","whyCN":"单靠形状就够了：任何又高又窄之物都在重复柱子的形态，却什么也不支撑。"},{"no":"03","title":"A regular newspaper feature","titleCN":"报刊专栏","definition":"a recurring article in a newspaper or magazine, usually by one writer","definitionCN":"报刊上由固定作者定期撰写的文章栏目","example":"Her column appears every Thursday on the opinion page.","exampleCN":"她的专栏每周四出现在评论版。","why":"printed text was set in vertical columns, so a regular slot down the page became a regular piece of writing.","whyCN":"印刷文字按竖栏排版，因此页面上固定的竖条变成固定的文章栏目。"},{"no":"04","title":"A vertical line in a table","titleCN":"表格的列","definition":"a vertical set of cells in a table or spreadsheet","definitionCN":"表格或电子表格中竖向排列的一组单元格","example":"Enter the totals in the last column, not in the last row.","exampleCN":"把合计填进最后一列，而不是最后一行。","why":"data inherited the printer's column: values that belong together are stacked in one vertical strip.","whyCN":"数据继承了印刷工的「栏」：同属一类的数值被堆在同一条竖条里。"},{"no":"05","title":"A line of marching troops","titleCN":"行军纵队","definition":"a formation in which troops or vehicles move one behind another","definitionCN":"士兵或车辆前后相接行进的队形","example":"The column moved through the pass before dawn.","exampleCN":"纵队在天亮前穿过山口。","why":"a marching line is long and narrow, so military language borrowed the architectural shape.","whyCN":"行军队伍又长又窄，因此军事语言借用了建筑的形状词。"},{"no":"06","title":"The classical column type","titleCN":"古典柱式","definition":"one of the ordered types of column, such as Doric, Ionic or Corinthian","definitionCN":"多立克、爱奥尼或科林斯等按规矩定型的柱型","example":"The porch uses a single column type throughout.","exampleCN":"这道门廊通体只用一种柱式。","why":"when proportions became rules, 'column' also named a type rather than one shaft.","whyCN":"当比例成为规则时，column 也指一种类型，而非一根柱身。"},{"no":"07","title":"A vertical strip of type","titleCN":"排版中的分栏","definition":"one of several vertical strips of text on a printed page","definitionCN":"印刷页面上并列的竖向文字条之一","example":"The newsletter is set in two columns to fit the page.","exampleCN":"这份通讯排成两栏以适应页面。","why":"the printing sense is the physical ancestor of the newspaper and table senses.","whyCN":"排版义是报刊义与表格义的实体祖先。"},{"no":"08","title":"A separation tube in chemistry","titleCN":"色谱柱","definition":"a vertical tube packed with material through which a mixture is passed for separation","definitionCN":"装填材料、使混合物通过而分离的竖管","example":"The sample travels down the column at a controlled rate.","exampleCN":"样品以受控速度沿色谱柱下行。","why":"laboratory apparatus borrowed the shape word for any tall tube that holds a rising or falling flow.","whyCN":"实验室器具借用了这个形状词，指任何容纳升降流动的高管。"}],"etymology":{"intro":{"en":"Column comes from a Latin word for a rising shaft, and its vertical shape spread into print, data and military language. Dates are approximate.","cn":"column 来自拉丁语中表示「升起的柱身」的词，其竖向形状随后扩散到印刷、数据与军事语言。年代均为约数。"},"items":[{"era":"LATIN COLUMEN","en":"Columen meant top, summit or ridge, the highest part of a structure.","cn":"columen 指顶部、顶点或屋脊，即结构的最高处。"},{"era":"LATIN COLUMNA","en":"Columna named a column or pillar, formed from the same idea of something standing up high.","cn":"columna 指柱子，由「高高立起之物」这一同一观念构成。"},{"era":"LATIN CELLERE","en":"The verb behind the family meant to rise or stand high, and it also gave the adjective for 'high'.","cn":"这一族词背后的动词意为升起或高立，它也给出了表示「高」的形容词。"},{"era":"ARCHITECTURAL USE","en":"English borrowed the word for a supporting shaft, and the classical orders made it a unit of design.","cn":"英语借入这个词指承重柱身，古典柱式又使它成为设计单位。"},{"era":"PRINT AND DATA","en":"From the seventeenth century a vertical strip of type was a column, and tables and newspapers followed.","cn":"从十七世纪起，竖向的文字条被称为一栏，表格与报刊随后沿用。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin ancestry of the rising verb is not established, and the Indo-European form often cited is a reconstruction.","cn":"来源不确定（更深来源）：这个表示「升起」的动词在拉丁语之前的谱系未得到证明，常被引用的印欧语形式属重构形式。"}]},"similar":{"note":{"en":"Group one holds upright-support words that are constantly confused; group two holds vertical arrangements that borrow the shape.","cn":"第一组是极易混淆的直立支撑词；第二组是借用这一形状的竖向排列。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pillar","ipa":"/ˈpɪlə/","tag":"any shape of support","definition":"A support of any section, square or round; a column is usually round and follows an order.","definitionCN":"任意截面（方形或圆形）的支撑；column 通常为圆形并遵循柱式。"},{"word":"colonne","ipa":"/kəˈlɒn/","tag":"French form","definition":"The French form of the same word, used in English only in special phrases; it is not a separate English noun.","definitionCN":"同一词的法语形式，英语仅在特定短语中使用，并非独立英语名词。"},{"word":"columnist","ipa":"/ˈkɒləmɪst/","tag":"the writer","definition":"A person who writes a regular column; it names the author, not the vertical strip.","definitionCN":"定期撰写专栏的人；指作者，而非竖向栏目。"},{"word":"colonnade","ipa":"/kəˈlɑːneɪd/","tag":"a row of columns","definition":"A row of columns supporting a roof or framing a space; it is the plural arrangement, not one shaft.","definitionCN":"一排支撑屋顶或框定空间的柱子；指整排布置，而非单根柱身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"row","ipa":"/rəʊ/","tag":"horizontal line","definition":"A horizontal line of items in a table; it contrasts with the vertical column.","definitionCN":"表格中横向排列的一项；与竖向的 column 相对。"},{"word":"line","ipa":"/laɪn/","tag":"general word","definition":"Any row or queue; a column is a vertical line with a specific order or structure.","definitionCN":"泛指一行或一队；column 是有特定次序或结构的竖线。"},{"word":"shaft","ipa":"/ʃɑːft/","tag":"the long body","definition":"The long middle part of a column, or a deep vertical passage; it is a part, not the whole support.","definitionCN":"柱子的长中段，或深竖井；是部件，而非整个支撑物。"},{"word":"post","ipa":"/pəʊst/","tag":"timber support","definition":"A firm upright piece, usually of timber or metal; it is plainer and less monumental than a column.","definitionCN":"牢固的直立件，通常为木或金属；比 column 朴素、少纪念性。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real vertical root, the real print history and the real technical compounds.","cn":"正常联想：真实的「竖立」词根、真实的印刷史与真实的技术复合词。"},"normal":[{"en":"The root means something standing high, so every sense keeps the idea of a vertical strip.","cn":"词根意为高立之物，因此每个义项都保留「竖条」这一观念。"},{"en":"The family runs column, columnar, columned, columnist, columniation.","cn":"同族词包括 column、columnar、columned、columnist、columniation。"},{"en":"Fixed phrases mark the branches: stone column, column of smoke, newspaper column, column of troops.","cn":"固定搭配标出各分支：石柱、烟柱、报纸专栏、行军纵队。"},{"en":"Printing is the bridge: a vertical strip of type became a newspaper feature and a table field.","cn":"印刷是桥梁：竖向文字条变成报纸栏目与表格字段。"},{"en":"A column is usually round and follows an order; a pillar can be any shape.","cn":"column 通常为圆形并遵循柱式；pillar 可以是任意形状。"}],"abstract":[{"en":"Picture a single upright line holding up a whole horizontal world.","cn":"想象一条直立线撑起整个横向的世界。"},{"en":"Picture smoke standing so still that it looks like a stone shaft.","cn":"想象烟静止得像一根石柱。"},{"en":"Picture a page folded into strips, each strip a small separate voice.","cn":"想象一页纸折成若干竖条，每一条都是一个独立的小声音。"}]},"examples":[{"en":"The temple's columns are carved from single blocks of marble.","cn":"这座神庙的柱子由整块大理石雕成。"},{"en":"His column on city politics ran for twenty years.","cn":"他关于城市政治的专栏写了二十年。"},{"en":"Add the numbers in the second column.","cn":"把第二列的数字相加。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"columen（顶端、屋脊）→ 高高立起的柱 → 立柱；竖排的东西也叫 column","word":"column"},"root":"拉丁 columna「柱子」来自 columen「顶端、屋脊」，其背后动词意为「升起、高立」；英语 column。该动词的更早来源不确定，相关印欧形式属重构。","sensesIntro":{"en":"Eight senses follow one vertical strip: a stone shaft becomes a smoke shaft, a printed strip, a table field, a marching line, an order, a page column and a lab tube.","cn":"八个义项沿同一条竖条展开：石柱身成为烟柱、印刷竖条、表格字段、行军纵队、柱式、页面分栏，最后成为实验室管柱。"},"semanticMap":{"core":{"en":"CORE IMAGE: one upright line from base to capital, holding a horizontal load.","cn":"核心意象：一条从基座到柱头的直立线，托着横向荷载。"},"chain":["AN UPRIGHT SHAFT","A RISING MASS","A VERTICAL STRIP","A DATA FIELD","A MARCHING LINE","A LAB TUBE"],"branches":[{"senses":"义项 01 · 06","en":"THE SUPPORT: a single shaft and a named order are the same upright line at two levels of rule.","cn":"支撑：单根柱身与有名柱式，是同一条直立线的两种规则层级。"},{"senses":"义项 02","en":"THE MASS: smoke and water keep the shape but drop the load.","cn":"体量：烟与水保留形状，却卸掉了荷载。"},{"senses":"义项 03 · 07","en":"THE PRINT STRIP: a page column becomes a regular feature and a recurring voice.","cn":"印刷竖条：页面分栏成为固定栏目与固定声音。"},{"senses":"义项 04 · 08","en":"THE VERTICAL ARRANGEMENT: table fields and chromatography tubes both stack along one axis.","cn":"竖向排列：表格字段与色谱柱都沿同一轴线堆叠。"},{"senses":"义项 05","en":"THE LINE OF PEOPLE: troops on the move borrow the long narrow shape.","cn":"人的队列：行进的军队借用这条细长形状。"}]},"affixes":{"intro":{"en":"Column is a Latin noun of height, and its stem built adjectives, professions and technical terms in English.","cn":"column 是一个拉丁语「高度」名词，其词干在英语中构成形容词、职业名与技术术语。"},"latinIntro":{"en":"Latin columen and columna are the source; the related verb and adjective for 'high' stayed in Latin and reached English only through derived forms.","cn":"拉丁语 columen 与 columna 是来源；相关表示「高」的动词与形容词留在拉丁语中，仅通过派生形式进入英语。"},"items":[{"word":"columen","structure":"columen, columinis (Latin noun, third declension)","meaning":"top, summit, ridge","meaningCN":"顶部；顶点；屋脊","example":"Columen named the highest line of a roof.","exampleCN":"这个词指屋顶最高的那条线。"},{"word":"columna","structure":"columna, columnae (Latin noun, first declension)","meaning":"column, pillar","meaningCN":"柱子；立柱","example":"A columna held the porch roof.","exampleCN":"一根柱子托着门廊屋顶。"},{"word":"column","structure":"columna through French colonne","meaning":"an upright support","meaningCN":"直立支撑物","example":"The column has no join in its shaft.","exampleCN":"这根柱子的柱身没有接缝。"},{"word":"columnar","structure":"column + -ar (like or relating to)","meaning":"shaped like a column","meaningCN":"柱状的","example":"The cliff has a columnar structure.","exampleCN":"这处崖壁呈柱状结构。"},{"word":"columned","structure":"column + -ed (having)","meaning":"furnished with columns","meaningCN":"有立柱的","example":"A columned hall faces the square.","exampleCN":"一座有立柱的大厅面向广场。"},{"word":"columnist","structure":"column + -ist (writer of)","meaning":"a writer of a regular column","meaningCN":"专栏作家","example":"The columnist revised the piece twice.","exampleCN":"专栏作家把文章改了两遍。"},{"word":"columniation","structure":"column + -iation (arrangement)","meaning":"the arrangement of columns in a building","meaningCN":"建筑中柱子的布置方式","example":"Columniation decides the rhythm of the facade.","exampleCN":"柱列布置决定立面的节奏。"},{"word":"column chromatography","structure":"column + chromatography (English compound)","meaning":"separation through a packed vertical tube","meaningCN":"通过填充竖管进行的分离","example":"The lab runs column chromatography overnight.","exampleCN":"实验室让色谱柱过夜运行。"}],"latinEntries":[{"word":"columna","structure":"columna, columnae (f., first declension)","meaning":"column, pillar","meaningCN":"柱子；立柱"},{"word":"columen","structure":"columen, columinis (n., third declension)","meaning":"top, summit","meaningCN":"顶部；顶点"}]}},{"word":"pillar","ipa_uk":"/ˈpɪlə/","ipa_us":"/ˈpɪlər/","definition_zh":"柱子；支柱；栋梁；柱状物；桥墩；门柱","definition_en":"a tall upright support of any shape, or a person or thing regarded as essential to a group or system","core_image":"一根方正的立柱顶住门廊，旁边一根圆柱只作装饰；同一词也指撑起整座建筑的那个人","scene":"门廊左侧的方柱已被风雨磨圆了棱角。The central pillar takes most of the roof's weight, while the others only frame the entrance.","sceneCN":"这里 pillar 指「建筑中直立的支撑柱」（第 1 个义项：柱子、支柱）；句意为中央那根柱子承担屋顶的大部分重量，其余只用来框住入口。图中可辨识物件：门廊、方柱、圆柱、屋顶。","pos":[{"tag":"n.","zh":"柱子；支柱；栋梁"},{"tag":"n.","zh":"柱状物；墩柱"}],"collocations":[{"phrase":"stone pillar","zh":"石柱"},{"phrase":"a pillar of society","zh":"社会栋梁"},{"phrase":"a pillar of smoke","zh":"一道烟柱"},{"phrase":"bridge pillar","zh":"桥墩"},{"phrase":"gate pillar","zh":"门柱"},{"phrase":"pillar industry","zh":"支柱产业"}],"forms":[{"label":"单数形式","form":"pillar"},{"label":"复数形式","form":"pillars"},{"label":"所有格","form":"pillar's"},{"label":"相关形容词","form":"pillared"},{"label":"相关形容词（小柱）","form":"pillaret"}],"derivatives":[{"word":"pillared","pos":"adj.","zh":"有柱子的"},{"word":"pillar-box","pos":"n.","zh":"（英）邮筒"},{"word":"pillar-like","pos":"adj.","zh":"柱状的"},{"word":"pillar of society","pos":"n.","zh":"社会栋梁"},{"word":"pillar industry","pos":"n.","zh":"支柱产业"}],"senses":[{"no":"01","title":"An upright architectural support","titleCN":"建筑柱子","definition":"a tall upright support, square or round, often ornamental as well as structural","definitionCN":"高而直立的支撑件，方或圆，常兼具装饰与承重作用","example":"A square pillar flanked each side of the porch.","exampleCN":"门廊两侧各立一根方柱。","why":"the Latin source meant a pillar of any section, so the word never required the roundness of a classical column.","whyCN":"其拉丁来源指任意截面的柱子，因此这个词从不要求古典柱那样的圆形。"},{"no":"02","title":"A person who holds up a community","titleCN":"社会栋梁","definition":"a person regarded as a main support of a community or institution","definitionCN":"被视为社区或机构主要支撑的人","example":"The old teacher was a pillar of the village for fifty years.","exampleCN":"那位老教师五十年来一直是村里的栋梁。","why":"the metaphor is structural and moral at once: remove the person and the group sags.","whyCN":"这个比喻同时是结构与道德的：去掉这个人，群体就会塌下去。"},{"no":"03","title":"An essential part of a system","titleCN":"制度或经济的支柱","definition":"a component on which a system depends, such as a sector of an economy","definitionCN":"某个系统所依赖的组成部分，如经济中的某个部门","example":"Tourism is a pillar of the island's income.","exampleCN":"旅游业是这座岛屿收入的支柱。","why":"systems are described as buildings, so their load-bearing parts are described as pillars.","whyCN":"系统被描述为建筑，因此其承重部分被说成柱子。"},{"no":"04","title":"A tall narrow mass","titleCN":"柱状物（烟、光、盐）","definition":"a tall narrow shape of smoke, light, salt or rock","definitionCN":"烟、光、盐或岩石形成的细高形状","example":"A pillar of salt stood where the tide had cut the cliff.","exampleCN":"潮水切开的崖边立着一根盐柱。","why":"the shape is enough: the word needs no load and no building.","whyCN":"形状就够了：这个词不需要荷载，也不需要建筑。"},{"no":"05","title":"A bridge pier","titleCN":"桥墩","definition":"the vertical support that carries a bridge span","definitionCN":"承托桥梁跨度的竖向支撑","example":"The middle pillar of the bridge has been rebuilt twice.","exampleCN":"桥的中墩已重建过两次。","why":"engineering uses the plain word for any vertical load path, not only for ornamental shafts.","whyCN":"工程用这个朴素词指任何竖向承重路径，而不只用于装饰柱。"},{"no":"06","title":"A gatepost","titleCN":"门柱；界柱","definition":"a short sturdy post marking or carrying a gate or boundary","definitionCN":"标记或承托门与边界的短粗立柱","example":"The gate hangs between two brick pillars.","exampleCN":"大门挂在两根砖柱之间。","why":"one of the oldest uses is simply a post that marks a threshold.","whyCN":"最古老的用法之一就是标记门槛的一根柱子。"},{"no":"07","title":"One of three policy supports","titleCN":"三支柱体系（政策术语）","definition":"in policy language, one of several coordinated supports of a system, as in pension pillars","definitionCN":"政策语言中某个体系的几根协同支柱之一，如养老金三支柱","example":"The report describes the three pillars of the pension scheme.","exampleCN":"报告描述该养老金方案的三根支柱。","why":"policy analysts borrowed the architectural image to show that the system fails if one support is removed.","whyCN":"政策分析者借用建筑意象，说明抽掉一根支柱体系就会失效。"},{"no":"08","title":"A pillar industry","titleCN":"支柱产业","definition":"a sector that carries a large share of a region's output and employment","definitionCN":"承担某地区大部分产出与就业的产业部门","example":"Shipbuilding became the pillar of the coastal economy.","exampleCN":"造船业成为沿海经济的支柱。","why":"the fixed phrase turns the metaphor into an economic category with measurable weight.","whyCN":"这一固定说法把比喻变成一个有可测分量的经济范畴。"}],"etymology":{"intro":{"en":"Pillar comes from a Latin word for a pillar through Old French, and it has always meant a support of any shape. Dates are approximate.","cn":"pillar 经古法语来自拉丁语中表示「柱子」的词，历来指任意形状的支撑。年代均为约数。"},"items":[{"era":"LATIN PILA","en":"Pila named a pillar or pier; it is written the same as the word for a ball, and the two are usually treated as separate nouns.","cn":"pila 指柱子或墩柱；它与表示「球」的词拼写相同，通常被视为两个不同的名词。"},{"era":"MEDIEVAL LATIN PILARE","en":"A derived noun pilare named a pillar or a supporting post in later Latin.","cn":"后期拉丁语中派生名词 pilare 指柱子或支撑柱。"},{"era":"OLD FRENCH PILIER","en":"Old French pilier carried the word into English, where it named a support in a building or a gate.","cn":"古法语 pilier 把这个词带入英语，指建筑或大门中的支撑。"},{"era":"BRIDGES AND GATES","en":"By the medieval period the word covered bridge piers and gateposts as well as interior shafts.","cn":"到中世纪，这个词除室内柱身外还涵盖桥墩与门柱。"},{"era":"MORAL METAPHOR","en":"From the sixteenth century a trusted person could be called a pillar of the community or of the church.","cn":"从十六世纪起，受信赖的人可被称为社区或教会的栋梁。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the ancestry of pila before Latin is not established, and whether it is connected to the ball word is disputed; no shared origin has been demonstrated.","cn":"来源不确定（更深来源）：pila 在拉丁语之前的谱系未得到证明，它与表示「球」的词是否有联系也有争议；尚无证据显示两者同源。"}]},"similar":{"note":{"en":"Group one holds upright-support words that overlap with pillar; group two holds metaphorical supports and tall masses.","cn":"第一组是与 pillar 重叠的直立支撑词；第二组是比喻性支撑与高柱体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"column","ipa":"/ˈkɒləm/","tag":"round and ordered","definition":"A support, usually round and governed by an order; a pillar may be square and need follow no order.","definitionCN":"通常为圆形且受柱式规范的支撑；pillar 可为方形、无须遵循柱式。"},{"word":"pier","ipa":"/pɪə/","tag":"masonry support","definition":"A thick masonry support between openings or under a bridge; it is heavier and more wall-like than a pillar.","definitionCN":"开口之间或桥下的厚砌体支撑；比 pillar 更厚重、更像墙。"},{"word":"post","ipa":"/pəʊst/","tag":"everyday support","definition":"A plain upright piece of timber or metal; pillar sounds more monumental and more permanent.","definitionCN":"朴素木制或金属直立件；pillar 听起来更宏大、更持久。"},{"word":"pillaret","ipa":"/ˈpɪlərət/","tag":"diminutive","definition":"A small pillar; the suffix makes it a minor architectural member.","definitionCN":"小柱子；后缀使它成为次要建筑构件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mainstay","ipa":"/ˈmeɪnsteɪ/","tag":"nautical metaphor","definition":"The chief support of a system, from a sailing term for the rope holding a mast; it is closer to pillar sense two.","definitionCN":"体系的主要支撑，来自固定桅杆的航海术语；更接近 pillar 的第二个义项。"},{"word":"prop","ipa":"/prɒp/","tag":"temporary support","definition":"A support placed under something to hold it up; it is usually temporary and rarely ornamental.","definitionCN":"置于某物下方以托住的支撑，通常临时且少装饰。"},{"word":"support","ipa":"/səˈpɔːt/","tag":"general word","definition":"Anything that holds weight or sustains a system; it is the neutral term that pillar makes concrete.","definitionCN":"任何承重或维持体系之物；是中性的总称，pillar 使之具体化。"},{"word":"backbone","ipa":"/ˈbækbəʊn/","tag":"body metaphor","definition":"The central strength of a group or system, from the spine; it stresses unity rather than vertical support.","definitionCN":"群体或体系的核心力量，来自脊柱；强调统一性而非竖向支撑。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin source, the real bridge and gate uses, and the real policy phrase.","cn":"正常联想：真实的拉丁来源、真实的桥梁与门柱用法、真实的政策说法。"},"normal":[{"en":"The word never required a round shaft, so a square gatepost is as much a pillar as a marble column.","cn":"这个词从不要求圆形柱身，因此方形门柱与大理石圆柱一样是 pillar。"},{"en":"The family runs pillar, pillared, pillaret, pillar-box, pillar-like.","cn":"同族词包括 pillar、pillared、pillaret、pillar-box、pillar-like。"},{"en":"Fixed phrases mark the branches: stone pillar, pillar of society, bridge pillar, pillar industry.","cn":"固定搭配标出各分支：石柱、社会栋梁、桥墩、支柱产业。"},{"en":"The metaphor is load-bearing: take the person away and the group sags.","cn":"这个比喻是承重的：把人抽走，群体就会塌。"},{"en":"A pillar of salt and a pillar of smoke need no building at all.","cn":"盐柱与烟柱根本不需要建筑。"}],"abstract":[{"en":"Picture a village where one person is literally holding up the roof.","cn":"想象一个村庄里真有一个人托着屋顶。"},{"en":"Picture a bridge standing on one leg in the middle of a river.","cn":"想象一座桥用一条腿立在河心。"},{"en":"Picture a policy report drawn as a temple with three columns.","cn":"想象一份政策报告被画成一座有三根柱子的神庙。"}]},"examples":[{"en":"The pillar at the gate carries the date of the first owner.","cn":"门柱上刻着第一任主人的日期。"},{"en":"She was a pillar of the hospital's volunteer service.","cn":"她是这家医院志愿服务的栋梁。"},{"en":"A pillar of cloud rose over the burning refinery.","cn":"燃烧的炼油厂上方升起一根烟柱。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"pila（柱子）+ 英语名词尾 → 直立的支撑 → 柱子、支柱、栋梁","word":"pillar"},"root":"古法语 pilier 来自中世纪拉丁 pilare，其源头是拉丁 pila「柱子、墩柱」；英语 pillar。pila 的更早谱系不确定，与表示「球」的 pila 是否有关尚无证据。","sensesIntro":{"en":"Eight senses follow one upright piece: a building support becomes a person, a system part, a tall mass, a bridge pier, a gatepost, a policy support and an industry.","cn":"八个义项沿同一根直立件展开：建筑支撑成为人、体系部件、高柱体、桥墩、门柱、政策支柱与产业。"},"semanticMap":{"core":{"en":"CORE IMAGE: a plain upright block that holds something heavier than itself.","cn":"核心意象：一块朴素的直立体，托着比它更重的东西。"},"chain":["AN UPRIGHT BLOCK","A BUILDING SUPPORT","A PERSON","A SYSTEM PART","A TALL MASS","A POLICY PHRASE"],"branches":[{"senses":"义项 01 · 05 · 06","en":"THE PHYSICAL SUPPORT: a shaft, a pier and a gatepost are the same block in three positions.","cn":"实体支撑：柱身、桥墩与门柱，是同一块直立体在三个位置。"},{"senses":"义项 02","en":"THE PERSON: a trusted member is described as holding the group up.","cn":"人：受信赖的成员被描述为托住群体的人。"},{"senses":"义项 03 · 07","en":"THE SYSTEM: economic sectors and policy supports are load-bearing parts.","cn":"体系：经济部门与政策支撑都是承重部件。"},{"senses":"义项 04","en":"THE MASS: smoke, salt and light keep only the tall narrow shape.","cn":"体量：烟、盐与光只保留了细高的形状。"},{"senses":"义项 08","en":"THE CATEGORY: the metaphor hardens into the fixed term pillar industry.","cn":"范畴：比喻固化为「支柱产业」这一固定术语。"}]},"affixes":{"intro":{"en":"Pillar is a borrowed noun with almost no productive affix of its own; its family is built with English endings and fixed compounds.","cn":"pillar 是借入名词，本身几乎没有能产词缀；其词族由英语词尾与固定复合词构成。"},"latinIntro":{"en":"Latin pila and the later pilare are the direct sources; English formed pillared and pillaret from the noun, not from new Latin words.","cn":"拉丁语 pila 与后期的 pilare 是直接来源；英语的 pillared 与 pillaret 是从名词构成，而非新的拉丁词。"},"items":[{"word":"pila","structure":"pila, pilae (Latin noun, first declension)","meaning":"pillar, pier","meaningCN":"柱子；墩柱","example":"Pila held the portico.","exampleCN":"柱子托住了门廊。"},{"word":"pilare","structure":"pilare, pilaris (medieval Latin noun)","meaning":"pillar, supporting post","meaningCN":"柱子；支撑柱","example":"Pilare named the pier of a bridge.","exampleCN":"这个词指桥墩。"},{"word":"pilier","structure":"pilier (Old French noun)","meaning":"pillar, post","meaningCN":"柱子；立柱","example":"A stone pilier framed the gate.","exampleCN":"一根石柱框住大门。"},{"word":"pillar","structure":"pilier through Middle English","meaning":"an upright support","meaningCN":"直立支撑","example":"The pillar carries the arch.","exampleCN":"这根柱子承住拱。"},{"word":"pillared","structure":"pillar + -ed (having)","meaning":"having pillars","meaningCN":"有柱子的","example":"A pillared porch marks the entrance.","exampleCN":"一道有柱的门廊标出入口。"},{"word":"pillaret","structure":"pillar + -et (small)","meaning":"a small pillar","meaningCN":"小柱子","example":"Pillarets divide the window bays.","exampleCN":"小柱把窗间分隔开。"},{"word":"pillar-box","structure":"pillar + box (British compound)","meaning":"a freestanding public post box","meaningCN":"立式公共邮筒","example":"The red pillar-box stands at the corner.","exampleCN":"红色邮筒立在街角。"},{"word":"pillar industry","structure":"pillar + industry (English compound)","meaning":"a sector that carries an economy","meaningCN":"支撑经济的产业","example":"Steel was once a pillar industry here.","exampleCN":"钢铁一度是这里的支柱产业。"}],"latinEntries":[{"word":"pila","structure":"pila, pilae (f., first declension)","meaning":"pillar, pier","meaningCN":"柱子；墩柱"},{"word":"pilare","structure":"pilare, pilaris (n., third declension; medieval Latin)","meaning":"supporting pillar","meaningCN":"支撑柱"}]}},{"word":"vault","ipa_uk":"/vɔːlt/","ipa_us":"/vɔːlt/","definition_zh":"拱顶；穹窿；地下室；金库；墓室；跳跃；撑杆跳","definition_en":"an arched ceiling or a room covered by one, a secure underground room, or a leap over something","core_image":"弧形石顶从两侧墙脚上升，在正中交会；地面之下另有一间锁着的石室，走廊尽头则有人撑杆跃过横杆","scene":"教堂中殿上方的石顶由两侧墙脚起弧，在正中交会。The vault above the nave has carried the roof for eight centuries.","sceneCN":"这里 vault 指「覆盖空间的拱形顶棚」（第 1 个义项：拱顶、穹窿）；句意为中殿上方的拱顶已承住屋顶八个世纪。图中可辨识物件：弧形石顶、两侧墙脚、中殿、屋顶。","pos":[{"tag":"n.","zh":"拱顶；穹窿；地下室；金库；墓室"},{"tag":"v.","zh":"跳跃越过；撑杆跳"}],"collocations":[{"phrase":"barrel vault","zh":"筒形拱顶"},{"phrase":"ribbed vault","zh":"肋拱顶"},{"phrase":"bank vault","zh":"银行金库"},{"phrase":"burial vault","zh":"家族墓室"},{"phrase":"pole vault","zh":"撑杆跳"},{"phrase":"the vault of heaven","zh":"天穹（诗语）"}],"forms":[{"label":"单数形式","form":"vault"},{"label":"复数形式","form":"vaults"},{"label":"所有格","form":"vault's"},{"label":"动词三单","form":"vaults"},{"label":"动词过去式","form":"vaulted"},{"label":"动词过去分词","form":"vaulted"},{"label":"动词现在分词","form":"vaulting"}],"derivatives":[{"word":"vaulted","pos":"adj.","zh":"拱形的；有拱顶的"},{"word":"vaulting","pos":"n.","zh":"拱顶结构；跳跃"},{"word":"vaulter","pos":"n.","zh":"撑杆跳运动员"},{"word":"pole vault","pos":"n.","zh":"撑杆跳项目"},{"word":"vault-like","pos":"adj.","zh":"拱顶般的"}],"senses":[{"no":"01","title":"An arched ceiling","titleCN":"拱顶；穹窿","definition":"a ceiling formed by an arch or a series of arches","definitionCN":"由一道拱或一系列拱构成的顶棚","example":"The barrel vault runs the whole length of the corridor.","exampleCN":"筒形拱顶贯通整条走廊。","why":"the word came from a Latin term for something rolled or turned, and an arch turned over a space is exactly that shape.","whyCN":"这个词来自拉丁语中表示「卷、转」的说法，而绕空间翻转的拱正是那种形状。"},{"no":"02","title":"The space under a vault","titleCN":"拱顶覆盖的空间","definition":"a room or passage roofed by an arch","definitionCN":"由拱顶覆盖的房间或通道","example":"The vault under the choir is open to visitors in summer.","exampleCN":"唱诗席下方的拱顶空间夏季向访客开放。","why":"a roof and the room it covers are so closely joined that one word names both.","whyCN":"屋顶与其覆盖的房间结合得太紧，于是一个词兼指两者。"},{"no":"03","title":"An underground storage room","titleCN":"地下室；地窖","definition":"a secure room below ground, often bricked or stone-lined","definitionCN":"地下安全房间，常以砖石砌成","example":"The wine vault stays at a constant twelve degrees.","exampleCN":"酒窖常年保持十二度。","why":"stone-lined cellars were built with arched roofs, so the roof word became the room word.","whyCN":"石砌地窖多用拱形顶，因此屋顶词变成房间词。"},{"no":"04","title":"A bank's strong room","titleCN":"金库；保险库","definition":"a heavily protected room where money and valuables are kept","definitionCN":"存放金钱与贵重物品的强力防护房间","example":"The bank vault opens only with two separate keys.","exampleCN":"银行金库只有用两把不同的钥匙才能打开。","why":"security borrowed the cellar's solidity, and the word now suggests steel and locks rather than stone.","whyCN":"保安借用了地窖的坚固感，这个词如今让人想到钢与锁，而非石头。"},{"no":"05","title":"A family burial chamber","titleCN":"家族墓室","definition":"a stone room beneath a church or in a cemetery used for burials","definitionCN":"教堂之下或墓地中用于安葬的石室","example":"Three generations are buried in the vault under the chapel.","exampleCN":"有三代人葬在小教堂下的墓室里。","why":"the underground arched room was a natural place for the dead, so the word acquired a funerary sense.","whyCN":"地下的拱形房间很适合安置死者，因此这个词获得了丧葬义。"},{"no":"06","title":"A crypt beneath a church","titleCN":"教堂地下墓室","definition":"the vaulted chamber under the main altar of a church","definitionCN":"教堂主祭坛下的拱顶房间","example":"The crypt vault was dug in the eleventh century.","exampleCN":"这座地下墓室建于十一世纪。","why":"church building gave the underground room a precise liturgical place and name.","whyCN":"教堂建筑赋予地下房间一个精确的礼仪位置与名称。"},{"no":"07","title":"A leap over an obstacle","titleCN":"跳跃；跃过","definition":"a jump made with the hands or a pole, especially over something","definitionCN":"用手或杆完成的跳跃，尤指越过某物","example":"He cleared the fence with a single vault.","exampleCN":"他一跃就越过了围栏。","why":"this sense came through a different French verb meaning to turn or tumble, and a turning body is a leaping body.","whyCN":"这一义项来自另一个法语动词，意为翻转或翻滚，而翻转的身体正是跳跃的身体。"},{"no":"08","title":"The pole vault event","titleCN":"撑杆跳项目","definition":"the athletics event in which an athlete clears a bar with a long pole","definitionCN":"运动员用长杆越过横杆的田径项目","example":"She set the national record in the vault last season.","exampleCN":"上个赛季她在撑杆跳项目上刷新了全国纪录。","why":"the event name is the leap noun narrowed into a sport with rules and a bar.","whyCN":"项目名是把跳跃名词收窄为有规则与横杆的运动。"}],"etymology":{"intro":{"en":"Vault is two senses from one Latin rolling root: a turned roof and a turned body. Dates are approximate.","cn":"vault 的两个义项同出一个拉丁语「滚动」词根：翻转的屋顶与翻转的身体。年代均为约数。"},"items":[{"era":"LATIN VOLVERE","en":"Volvere meant to roll, turn or wrap around, and it supplied a family of words about curved and rolling motion.","cn":"volvere 意为滚动、转动或缠绕，衍生出一族关于曲线与滚动运动的词。"},{"era":"LATIN VOLUTA","en":"Voluta named a spiral or scroll shape, and it described the curled capital of a column.","cn":"voluta 指螺旋或涡卷形状，也描述柱头的卷曲。"},{"era":"VULGAR LATIN VOLTA","en":"A later form named a turn or an arched covering, and Old French voute carried the roof sense to English.","cn":"后期形式指转弯或拱形覆盖，古法语 voute 把屋顶义带入英语。"},{"era":"OLD FRENCH VOLTER","en":"A related verb meant to turn or tumble, and its English descendant gave the leap sense.","cn":"一个相关动词意为翻转或翻滚，其英语后裔给出了跳跃义。"},{"era":"MEDIEVAL BUILDING","en":"Romanesque and Gothic masons made the vault a structural system, and the word followed stone, cellar and tomb.","cn":"罗曼式与哥特式石匠把拱顶发展成结构体系，这个词随石头、地窖与墓室延伸。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Latin ancestry of volvere is not settled, and the Indo-European root commonly proposed for it is a reconstruction rather than a recorded form.","cn":"来源不确定（更深来源）：volvere 在拉丁语之前的谱系尚无定论，通常为其提出的印欧语词根是重构形式，而非有记录的形式。"}]},"similar":{"note":{"en":"Group one holds curved-roof words and easily confused forms; group two holds secure rooms and jumping words.","cn":"第一组是曲面屋顶词与易混形式；第二组是安全房间与跳跃词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"vaulted","ipa":"/ˈvɔːltɪd/","tag":"adjective","definition":"Having a vault; it describes a building rather than naming the roof.","definitionCN":"有拱顶的；描述建筑，而非命名屋顶。"},{"word":"volute","ipa":"/vəˈljuːt/","tag":"scroll shape","definition":"A spiral scroll on an Ionic capital, from the same Latin rolling root.","definitionCN":"爱奥尼柱头上的螺旋涡卷，同出拉丁「滚动」词根。"},{"word":"volt","ipa":"/vəʊlt/","tag":"unrelated unit","definition":"The unit of electrical force, named after an Italian scientist; it has no connection to the roof word.","definitionCN":"电动势单位，以意大利科学家命名，与屋顶词无关。"},{"word":"vaulting","ipa":"/ˈvɔːltɪŋ/","tag":"two jobs","definition":"It can mean either the building of vaults or the act of leaping; context decides which.","definitionCN":"既指建造拱顶，也指跳跃动作，由语境决定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dome","ipa":"/dəʊm/","tag":"round roof","definition":"A rounded roof over a circular space; a vault is usually arched along a line or a grid.","definitionCN":"覆盖圆形空间的圆顶；拱顶通常沿一条线或网格起拱。"},{"word":"crypt","ipa":"/krɪpt/","tag":"underground chamber","definition":"A stone chamber beneath a church, usually for burial; it often has a vault but need not.","definitionCN":"教堂下的石室，通常用于安葬；常有拱顶，但非必需。"},{"word":"cellar","ipa":"/ˈselə/","tag":"storage below ground","definition":"An underground storage room, usually for wine or goods; it is plainer than the secure vault.","definitionCN":"地下储藏室，通常存酒或货物；比强调安全性的 vault 朴素。"},{"word":"leap","ipa":"/liːp/","tag":"the general jump","definition":"A jump, often a long one; vault is a leap over an obstacle or with a pole.","definitionCN":"泛指跳跃，常指远跳；vault 是越过障碍或以杆完成的跳。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real rolling root, the real building terms and the real athletics event.","cn":"正常联想：真实的「滚动」词根、真实的建筑术语与真实的田径项目。"},"normal":[{"en":"One root means roll or turn: a turned roof and a turning body gave the two main senses.","cn":"同一个词根意为滚动或转动：翻转的屋顶与翻转的身体给出两个主要义项。"},{"en":"The family runs vault, vaulted, vaulting, vaulter, pole vault, vault-like.","cn":"同族词包括 vault、vaulted、vaulting、vaulter、pole vault、vault-like。"},{"en":"Fixed phrases mark the branches: barrel vault, ribbed vault, bank vault, burial vault, pole vault.","cn":"固定搭配标出各分支：筒形拱顶、肋拱顶、银行金库、家族墓室、撑杆跳。"},{"en":"A stone roof over a cellar became the word for the cellar and then for a bank's strong room.","cn":"地窖上的石顶先成为地窖之名，再成为银行金库之名。"},{"en":"The gymnastics sense keeps the turning body, not the stone.","cn":"跳跃义保留的是翻转的身体，而非石头。"}],"abstract":[{"en":"Picture a stone bowl turned upside down and buried halfway.","cn":"想象一只石碗倒扣过来，一半埋进土里。"},{"en":"Picture a locked room under a church where the only light comes from the door.","cn":"想象教堂之下一间上锁的屋子，唯一的光来自门口。"},{"en":"Picture a body turning in the air as if rolling over an invisible line.","cn":"想象一具身体在空中翻转，仿佛越过一条看不见的线。"}]},"examples":[{"en":"The vault of the nave is held by ribs of cut stone.","cn":"中殿的拱顶由切石肋支撑。"},{"en":"The documents were moved to a vault during the flood.","cn":"洪水期间，文件被转移到金库。"},{"en":"He vaulted the low wall without breaking stride.","cn":"他一步未停就越过了矮墙。"}],"dict_mnemonic":{"note":"拆词记忆 · 非词源","text":"volvere（滚动、翻转）→ 翻转成拱的顶 → 拱顶、地下室、金库；翻转身体 → 跳跃","word":"vault"},"root":"拉丁 volvere「滚动、翻转」衍生 voluta「涡卷」与后期 volta「拱形覆盖」，经古法语 voute 入英语；跳跃义经古法语 volter「翻转、翻滚」而来。英语 vault。volvere 的更早来源不确定，相关印欧词根属重构。","sensesIntro":{"en":"Eight senses follow one turn: a roof turns over a space, the room beneath it becomes a cellar, a strong room and a tomb, while a turning body becomes a leap and a sport.","cn":"八个义项沿同一次翻转展开：屋顶绕空间翻转，其下的房间成为地窖、金库与墓室；而翻转的身体成为跳跃与运动项目。"},"semanticMap":{"core":{"en":"CORE IMAGE: a curve rising from two feet and meeting at the middle, and a body turning over a bar.","cn":"核心意象：一条从两侧墙脚升起、在中间交会的曲线，以及一具越过横杆翻转的身体。"},"chain":["A TURNED ROOF","A COVERED ROOM","A CELLAR","A STRONG ROOM","A TOMB","A LEAP"],"branches":[{"senses":"义项 01","en":"THE ROOF: the first sense is the curved ceiling itself.","cn":"屋顶：第一个义项就是曲面顶棚本身。"},{"senses":"义项 02 · 03","en":"THE ROOM BELOW: a vaulted space and a storage cellar are the roof and the room it shelters.","cn":"其下的房间：拱顶空间与储藏地窖，是屋顶与它所庇护的房间。"},{"senses":"义项 04 · 05 · 06","en":"SECURE DEPTHS: a bank's strong room, a family tomb and a church crypt all turn the underground room into protection.","cn":"安全的地下：银行金库、家族墓室与教堂地下墓室，都把地下房间变成保护。"},{"senses":"义项 07","en":"THE TURNED BODY: the leap comes from the same root's idea of turning over.","cn":"翻转的身体：跳跃来自同一词根「翻转」的观念。"},{"senses":"义项 08","en":"THE SPORT: the leap is narrowed into an event with a pole and a bar.","cn":"运动：跳跃被收窄为有杆与横杆的项目。"}]},"affixes":{"intro":{"en":"Vault comes from a Latin rolling verb, so its affix list follows one root through roof, room and leap.","cn":"vault 来自一个拉丁语「滚动」动词，因此其词缀清单沿同一词根贯穿屋顶、房间与跳跃。"},"latinIntro":{"en":"Latin volvere and voluta stand behind the roof sense, while the leap sense came through a French verb for turning over.","cn":"拉丁语 volvere 与 voluta 支撑屋顶义，而跳跃义经一个表示翻转的法语动词而来。"},"items":[{"word":"volvere","structure":"volvere, volvi, volutum (Latin verb, third conjugation)","meaning":"to roll, turn, wrap","meaningCN":"滚动；转动；缠绕","example":"The root pictures motion around a centre.","exampleCN":"这个词根描绘绕中心的运动。"},{"word":"voluta","structure":"voluta, volutae (Latin noun, first declension)","meaning":"a spiral, scroll","meaningCN":"螺旋；涡卷","example":"A voluta curls at the top of a column.","exampleCN":"涡卷卷在柱顶。"},{"word":"volta","structure":"volta (Vulgar Latin noun, 'a turn')","meaning":"a turn; an arched covering","meaningCN":"转弯；拱形覆盖","example":"The turn became a roof.","exampleCN":"这个「转」变成了屋顶。"},{"word":"vault","structure":"voute (Old French) through English","meaning":"an arched ceiling; a secure room","meaningCN":"拱形顶棚；安全房间","example":"The vault covers the nave.","exampleCN":"拱顶覆盖中殿。"},{"word":"vaulted","structure":"vault + -ed (having)","meaning":"roofed with a vault","meaningCN":"有拱顶的","example":"A vaulted cellar stays cool.","exampleCN":"有拱顶的地窖保持凉爽。"},{"word":"vaulting","structure":"vault + -ing (action or result)","meaning":"vault construction, or the act of leaping","meaningCN":"拱顶建造，或跳跃动作","example":"Vaulting began with stone and ended in sport.","exampleCN":"这个词从石头开始，最后落到运动。"},{"word":"vaulter","structure":"vault + -er (one who does)","meaning":"a person who vaults","meaningCN":"跳跃者；撑杆跳选手","example":"The vaulter cleared the bar on the third try.","exampleCN":"撑杆跳选手第三次越过横杆。"},{"word":"pole vault","structure":"pole + vault (English compound)","meaning":"the athletics event of jumping with a pole","meaningCN":"撑杆跳项目","example":"The pole vault needs speed and timing.","exampleCN":"撑杆跳需要速度与时机。"}],"latinEntries":[{"word":"volvere","structure":"volvere, volvi, volutum (v., third conjugation)","meaning":"to roll, turn","meaningCN":"滚动；转动"},{"word":"voluta","structure":"voluta, volutae (f., first declension)","meaning":"spiral, scroll","meaningCN":"螺旋；涡卷"}]}}]);
